export default "{\"schema\":\"ai-brain.inert-reference.v1\",\"trust\":\"untrusted_reference_only\",\"records\":[{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/guards.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7cf872f494432c4478e067763a00a58204f489c1db8de0ffe0345b3fe8d3cbee\",\"content\":\"\\\"\\\"\\\"Permission-enforcement guards for guarded API routes.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom contextlib import contextmanager\\nfrom contextvars import ContextVar\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom fastapi import HTTPException, status\\nfrom lfx.log.logger import logger\\n\\nfrom langflow.services.auth.context import (\\n    current_auth_context_for_audit,\\n    current_auth_context_for_authz,\\n    current_auth_is_api_key,\\n)\\nfrom langflow.services.authorization import audit as _audit\\nfrom langflow.services.authorization.access_ceiling import (\\n    external_access_allows,\\n    get_current_external_access_context,\\n)\\nfrom langflow.services.authorization.actions import (\\n    DeploymentAction,\\n    FileAction,\\n    FlowAction,\\n    KnowledgeBaseAction,\\n    ProjectAction,\\n    ProviderAccountAction,\\n    ShareAction,\\n    VariableAction,\\n    VoiceAction,\\n)\\nfrom langflow.services.deps import get_authorization_service, get_settings_service\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Iterator, Sequence\\n    from uuid import UUID\\n\\n    from langflow.services.database.models.user.model import User, UserRead\\n\\n# Action enums coerced to string values.\\n_ACTION_ENUMS = (\\n    FlowAction,\\n    DeploymentAction,\\n    ProjectAction,\\n    KnowledgeBaseAction,\\n    VariableAction,\\n    FileAction,\\n    ShareAction,\\n    ProviderAccountAction,\\n    VoiceAction,\\n)\\n\\n# Resource-owner keys included in audit details (kept in one place so a new\\n# resource type does not need to hand-update ``ensure_permission``).\\n_OWNER_CONTEXT_KEYS = (\\n    \\\"flow_user_id\\\",\\n    \\\"deployment_user_id\\\",\\n    \\\"project_user_id\\\",\\n    \\\"knowledge_base_user_id\\\",\\n    \\\"variable_user_id\\\",\\n    \\\"file_user_id\\\",\\n    \\\"share_user_id\\\",\\n    \\\"provider_account_user_id\\\",\\n    \\\"voice_user_id\\\",\\n)\\n\\n# Default 403 detail. UUID-leaking detail strings are opt-in via ``detail=...``\\n# on ``ensure_permission`` so the secure default is the easy path. See review\\n# item I2 on PR #13153.\\n_DEFAULT_DENY_DETAIL = \\\"Permission denied\\\"\\n\\n\\ndef _auth_context(user: User | UserRead) -> dict[str, Any]:\\n    \\\"\\\"\\\"Build the base context dict passed to authorization enforce calls.\\\"\\\"\\\"\\n    return {\\n        **current_auth_context_for_authz(),\\n        \\\"is_superuser\\\": getattr(user, \\\"is_superuser\\\", False),\\n    }\\n\\n\\ndef _auth_audit_details() -> dict[str, str]:\\n    \\\"\\\"\\\"Build JSON-friendly auth context for audit details.\\\"\\\"\\\"\\n    return current_auth_context_for_audit()\\n\\n\\n# A capability probe is the UI asking \\\"may I offer this control?\\\" \u2014 not an\\n# attempt to use it. Enforcement is identical either way, but the *audit row*\\n# is not: probing wrote a row named after an action nobody performed, so the\\n# sidebar rendering N projects wrote N ``share:create`` rows with no resource\\n# and no share behind them. Suppress the decision row for the probe only;\\n# real attempts, including denied ones, are audited exactly as before.\\n_capability_probe: ContextVar[bool] = ContextVar(\\\"langflow_authz_capability_probe\\\", default=False)\\n\\n\\n@contextmanager\\ndef capability_probe() -> Iterator[None]:\\n    \\\"\\\"\\\"Evaluate permissions for a UI capability answer without auditing the check.\\n\\n    Wrap only reads whose entire purpose is to decide whether an affordance is\\n    offered. The guard still runs and still denies; nothing about enforcement\\n    changes. Anything that can have an effect \u2014 or that a caller invoked\\n    intending an effect \u2014 must stay outside this scope so its decision is\\n    recorded.\\n    \\\"\\\"\\\"\\n    token = _capability_probe.set(True)\\n    try:\\n        yield\\n    finally:\\n        _capability_probe.reset(token)\\n\\n\\nasync def _audit_suppressed() -> None:\\n    \\\"\\\"\\\"Awaitable no-op standing in for a suppressed decision row.\\\"\\\"\\\"\\n    return\\n\\n\\ndef _audit_guard_decision(\\n    *,\\n    user_id: UUID | None,\\n    action: str,\\n    obj: str,\\n    result: str,\\n    details: dict[str, Any] | None = None,\\n):\\n    \\\"\\\"\\\"Record one authorization *decision* made by a guard.\\n\\n    Every row written from this module is a check, not an effect. Tagging it\\n    keeps it distinguishable from the row a route writes after a mutation is\\n    durable: both share an action name (a ``share:create`` check and a created\\n    share both read ``share:create``), so without the tag a reader cannot tell\\n    an evaluated permission from a performed action. Returns the coroutine so\\n    callers can await it or gather several.\\n    \\\"\\\"\\\"\\n    if _capability_probe.get():\\n        return _audit_suppressed()\\n    return _audit.audit_decision(\\n        user_id=user_id,\\n        action=action,\\n        obj=obj,\\n        result=result,\\n        details={**(details or {}), \\\"event\\\": _audit.AUDIT_EVENT_DECISION},\\n    )\\n\\n\\nasync def _api_key_scopes_require_plugin_enforcement() -> bool:\\n    \\\"\\\"\\\"Return True when owner override must not hide API-key caveats.\\\"\\\"\\\"\\n    if not current_auth_is_api_key():\\n        return False\\n\\n    settings = get_settings_service()\\n    if not settings.auth_settings.AUTHZ_ENABLED:\\n        return False\\n\\n    authz = get_authorization_service()\\n    supports_api_key_scopes = getattr(authz, \\\"supports_api_key_scopes\\\", None)\\n    if supports_api_key_scopes is None:\\n        return False\\n    try:\\n        return bool(await supports_api_key_scopes())\\n    except Exception:  # noqa: BLE001\\n        logger.exception(\\\"Authorization plugin failed API-key scope capability check; preserving owner override\\\")\\n        return False\\n\\n\\nasync def should_apply_owner_override() -> bool:\\n    \\\"\\\"\\\"Return True when Langflow should apply the built-in owner override.\\\"\\\"\\\"\\n    return not await _api_key_scopes_require_plugin_enforcement()\\n\\n\\ndef _coerce_action(\\n    act: DeploymentAction\\n    | FlowAction\\n    | ProjectAction\\n    | KnowledgeBaseAction\\n    | VariableAction\\n    | FileAction\\n    | ShareAction\\n    | ProviderAccountAction\\n    | VoiceAction\\n    | str,\\n) -> str:\\n    \\\"\\\"\\\"Return the string value of an action enum or pass through a raw string.\\\"\\\"\\\"\\n    if isinstance(act, _ACTION_ENUMS):\\n        return act.value\\n    return act\\n\\n\\ndef _resolve_authz_domain(workspace_id: UUID | None, scope_id: UUID | None) -> str:\\n    \\\"\\\"\\\"Resolve policy domain: project scope, then workspace, else ``*``.\\\"\\\"\\\"\\n    if scope_id is not None:\\n        return f\\\"project:{scope_id}\\\"\\n    if workspace_id is not None:\\n        return f\\\"workspace:{workspace_id}\\\"\\n    return \\\"*\\\"\\n\\n\\n# Backward-compatible alias.\\n_resolve_flow_domain = _resolve_authz_domain\\n\\n\\nasync def ensure_permission(\\n    user: User | UserRead,\\n    *,\\n    domain: str,\\n    obj: str,\\n    act: str,\\n    context: dict[str, Any] | None = None,\\n    detail: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Raise HTTP 403 when the user may not perform the action (audited).\\n\\n    ``detail`` overrides the default non-disclosing 403 message. Callers that\\n    have already verified the resource exists for the requester (e.g. routes\\n    operating on user-owned data) may pass a richer string. The default is\\n    intentionally generic so a missing ``deny_to_404`` wrap cannot leak the\\n    resource UUID \u2014 see review item I2 on PR #13153.\\n    \\\"\\\"\\\"\\n    # Caller context first; user auth fields cannot be overwritten.\\n    merged_context = {**(context or {}), **_auth_context(user)}\\n    audit_action = f\\\"{obj.split(':', 1)[0]}:{act}\\\" if \\\":\\\" in obj else act\\n    audit_details: dict[str, Any] = {\\\"domain\\\": domain, **_auth_audit_details()}\\n    for owner_key in _OWNER_CONTEXT_KEYS:\\n        if owner_key in merged_context and merged_context[owner_key] is not None:\\n            audit_details[owner_key] = str(merged_context[owner_key])\\n\\n    settings = get_settings_service()\\n    if not settings.auth_settings.AUTHZ_ENABLED:\\n        # Auditing is independently configurable so operators can observe the\\n        # allow-by-disabled-enforcement path before turning RBAC on.\\n        await _audit_guard_decision(\\n            user_id=user.id,\\n            action=audit_action,\\n            obj=obj,\\n            result=_audit.AUDIT_ALLOW,\\n            details=audit_details,\\n        )\\n        return\\n\\n    authz = get_authorization_service()\\n    # Fail closed when enforce() raises (deny + audit, not HTTP 500).\\n    deny_detail = detail if detail is not None else _DEFAULT_DENY_DETAIL\\n    try:\\n        allowed = await authz.enforce(\\n            user_id=user.id,\\n            domain=domain,\\n            obj=obj,\\n            act=act,\\n            context=merged_context,\\n        )\\n    except Exception as exc:\\n        logger.exception(\\\"Authorization plugin raised during enforce; failing closed\\\")\\n        await _audit_guard_decision(\\n            user_id=user.id,\\n            action=audit_action,\\n            obj=obj,\\n            result=_audit.AUDIT_DENY,\\n            details={**audit_details, \\\"error\\\": str(exc)},\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=deny_detail,\\n        ) from exc\\n\\n    await _audit_guard_decision(\\n        user_id=user.id,\\n        action=audit_action,\\n        obj=obj,\\n        result=_audit.AUDIT_ALLOW if allowed else _audit.AUDIT_DENY,\\n        details=audit_details,\\n    )\\n\\n    if not allowed:\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=deny_detail,\\n        )\\n\\n\\nasync def _ensure_resource_permission(\\n    user: User | UserRead,\\n    *,\\n    resource_type: str,\\n    resource_id: UUID | str | None,\\n    owner_id: UUID | None,\\n    owner_override_allowed: bool,\\n    act_str: str,\\n    resolved_domain: str,\\n    extra_context: dict[str, Any],\\n) -> None:\\n    \\\"\\\"\\\"Build object key, apply owner override, else delegate to ensure_permission.\\\"\\\"\\\"\\n    obj = f\\\"{resource_type}:{resource_id}\\\" if resource_id else f\\\"{resource_type}:*\\\"\\n\\n    external_context = get_current_external_access_context()\\n    if external_context is not None and not external_access_allows(act_str, external_context):\\n        await _audit_guard_decision(\\n            user_id=user.id,\\n            action=f\\\"{resource_type}:{act_str}\\\",\\n            obj=obj,\\n            result=_audit.AUDIT_DENY,\\n            details={\\n                \\\"domain\\\": resolved_domain,\\n                \\\"external_auth_provider\\\": external_context.provider,\\n                \\\"external_access_level\\\": external_context.level,\\n            },\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"External credentials do not allow this action\\\",\\n        )\\n\\n    if (\\n        owner_override_allowed\\n        and owner_id is not None\\n        and getattr(user, \\\"id\\\", None) == owner_id\\n        and await should_apply_owner_override()\\n    ):\\n        await _audit_guard_decision(\\n            user_id=user.id,\\n            action=f\\\"{resource_type}:{act_str}\\\",\\n            obj=obj,\\n            result=_audit.AUDIT_OWNER_OVERRIDE,\\n            details={\\\"domain\\\": resolved_domain, **_auth_audit_details()},\\n        )\\n        return\\n\\n    await ensure_permission(\\n        user,\\n        domain=resolved_domain,\\n        obj=obj,\\n        act=act_str,\\n        context=extra_context,\\n    )\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Resource registry \u2014 collapses the ensure_*_permission family into one path.\\n# See review item I1 on PR #13153.\\n# --------------------------------------------------------------------------- #\\n\\n\\n@dataclass(frozen=True)\\nclass _ResourceSpec:\\n    \\\"\\\"\\\"Static metadata for one resource type's ``ensure_*_permission`` helper.\\\"\\\"\\\"\\n\\n    resource_type: str  # Object slug prefix, e.g. \\\"flow\\\"\\n    owner_kw: str  # Public kwarg carrying the owner id, e.g. \\\"flow_user_id\\\"\\n    id_kw: str  # Public kwarg carrying the resource id, e.g. \\\"flow_id\\\"\\n    # Public kwarg the resolver consults for the *outer* domain bucket\\n    # (workspace). ``None`` means the helper does not accept a workspace scope.\\n    workspace_kw: str | None\\n    # Public kwarg the resolver consults for the *inner* domain bucket\\n    # (project/folder). ``None`` means the helper does not accept this scope.\\n    scope_kw: str | None\\n    # Extra kwargs forwarded verbatim into ``extra_context`` (no domain effect).\\n    extra_context_kws: tuple[str, ...] = ()\\n    # CREATE normally has no existing resource owner, so caller-supplied owner\\n    # ids must not trigger the owner override. Resource families whose CREATE\\n    # action targets an existing owned resource may opt in explicitly.\\n    owner_override_on_create: bool = False\\n    # Public kwarg carrying the owner of the *container* a CREATE writes into\\n    # (e.g. the destination project for a new flow). The new resource has no\\n    # owner yet, so this is the only ownership the check can consult. It must\\n    # be resolved server-side from the destination row, never echoed from the\\n    # request, or a caller could assert ownership of a container they do not\\n    # own. ``None`` means CREATE has no container to inherit ownership from.\\n    create_container_owner_kw: str | None = None\\n\\n\\n_RESOURCE_SPECS: dict[str, _ResourceSpec] = {\\n    \\\"flow\\\": _ResourceSpec(\\n        resource_type=\\\"flow\\\",\\n        owner_kw=\\\"flow_user_id\\\",\\n        id_kw=\\\"flow_id\\\",\\n        workspace_kw=\\\"workspace_id\\\",\\n        scope_kw=\\\"folder_id\\\",\\n        # A project owner can always create flows in their own project: the\\n        # project is the owned resource the new flow lands in, and owner\\n        # override is documented as preceding any policy rule. Without this a\\n        # user holding a read-only role cannot use the default project that was\\n        # created for them.\\n        create_container_owner_kw=\\\"folder_user_id\\\",\\n    ),\\n    \\\"deployment\\\": _ResourceSpec(\\n        resource_type=\\\"deployment\\\",\\n        owner_kw=\\\"deployment_user_id\\\",\\n        id_kw=\\\"deployment_id\\\",\\n        workspace_kw=\\\"workspace_id\\\",\\n        scope_kw=\\\"project_id\\\",\\n    ),\\n    \\\"project\\\": _ResourceSpec(\\n        resource_type=\\\"project\\\",\\n        owner_kw=\\\"project_user_id\\\",\\n        id_kw=\\\"project_id\\\",\\n        workspace_kw=\\\"workspace_id\\\",\\n        # Existing-project checks use the concrete project domain so plugins\\n        # can distinguish reserved projects from their parent workspace.\\n        # CREATE has no project id and still resolves to the workspace/global\\n        # domain as before.\\n        scope_kw=\\\"project_id\\\",\\n    ),\\n    \\\"knowledge_base\\\": _ResourceSpec(\\n        resource_type=\\\"knowledge_base\\\",\\n        owner_kw=\\\"kb_user_id\\\",\\n        id_kw=\\\"kb_id\\\",\\n        workspace_kw=\\\"workspace_id\\\",\\n        scope_kw=\\\"project_id\\\",\\n        extra_context_kws=(\\\"kb_name\\\",),\\n    ),\\n    \\\"variable\\\": _ResourceSpec(\\n        resource_type=\\\"variable\\\",\\n        owner_kw=\\\"variable_user_id\\\",\\n        id_kw=\\\"variable_id\\\",\\n        workspace_kw=\\\"workspace_id\\\",\\n        scope_kw=None,\\n    ),\\n    \\\"file\\\": _ResourceSpec(\\n        resource_type=\\\"file\\\",\\n        owner_kw=\\\"file_user_id\\\",\\n        id_kw=\\\"file_id\\\",\\n        workspace_kw=\\\"workspace_id\\\",\\n        scope_kw=None,\\n    ),\\n    \\\"share\\\": _ResourceSpec(\\n        resource_type=\\\"share\\\",\\n        owner_kw=\\\"share_user_id\\\",\\n        id_kw=\\\"share_id\\\",\\n        workspace_kw=None,\\n        scope_kw=None,\\n        # Creating a share authorizes against the already-existing target\\n        # resource owner, not the prospective share-row owner.\\n        owner_override_on_create=True,\\n    ),\\n    \\\"provider_account\\\": _ResourceSpec(\\n        resource_type=\\\"provider_account\\\",\\n        owner_kw=\\\"provider_account_user_id\\\",\\n        id_kw=\\\"provider_account_id\\\",\\n        workspace_kw=None,\\n        scope_kw=None,\\n        # A newly-created provider account always belongs to the caller.\\n        owner_override_on_create=True,\\n    ),\\n    \\\"voice\\\": _ResourceSpec(\\n        resource_type=\\\"voice\\\",\\n        owner_kw=\\\"voice_user_id\\\",\\n        id_kw=\\\"voice_id\\\",\\n        workspace_kw=None,\\n        scope_kw=None,\\n    ),\\n}\\n\\n\\nasync def _ensure_typed(\\n    user: User | UserRead,\\n    *,\\n    spec_key: str,\\n    act_str: str,\\n    kwargs: dict[str, Any],\\n    domain_override: str | None,\\n) -> None:\\n    \\\"\\\"\\\"Shared body for ``ensure_*_permission`` helpers.\\n\\n    ``kwargs`` is the keyword-argument dict the caller passed to the public\\n    helper. The registry tells us which key carries the id, the owner, and the\\n    domain components; everything else flows into ``extra_context`` verbatim.\\n    \\\"\\\"\\\"\\n    spec = _RESOURCE_SPECS[spec_key]\\n\\n    resource_id = kwargs.get(spec.id_kw)\\n    owner_id = kwargs.get(spec.owner_kw)\\n    workspace_id = kwargs.get(spec.workspace_kw) if spec.workspace_kw else None\\n    scope_id = kwargs.get(spec.scope_kw) if spec.scope_kw else None\\n\\n    if domain_override is not None:\\n        resolved_domain = domain_override\\n    elif spec.workspace_kw is None and spec.scope_kw is None:\\n        # Shares have no domain bucket.\\n        resolved_domain = \\\"*\\\"\\n    else:\\n        resolved_domain = _resolve_authz_domain(workspace_id, scope_id)\\n\\n    # ``extra_context`` mirrors the legacy clone shape so audit rows and\\n    # plugin matchers continue to see the same key names. We forward every\\n    # kwarg the helper declares except ``domain`` (already resolved).\\n    extra_context: dict[str, Any] = {}\\n    if spec.workspace_kw is not None:\\n        extra_context[spec.workspace_kw] = workspace_id\\n    if spec.scope_kw is not None:\\n        extra_context[spec.scope_kw] = scope_id\\n    extra_context[spec.owner_kw] = owner_id\\n    if spec.create_container_owner_kw is not None:\\n        extra_context[spec.create_container_owner_kw] = kwargs.get(spec.create_container_owner_kw)\\n    if spec_key == \\\"knowledge_base\\\":\\n        # KB also forwards the resource id under its public name for plugins\\n        # that scope policy by kb_id directly (mirrors the legacy clone).\\n        extra_context[spec.id_kw] = resource_id\\n    for key in spec.extra_context_kws:\\n        extra_context[key] = kwargs.get(key)\\n\\n    # On CREATE the resource does not exist yet, so ownership can only come\\n    # from the container it is created in. Everything else authorizes against\\n    # the resource's own owner.\\n    is_create = act_str == \\\"create\\\"\\n    container_owner_id = kwargs.get(spec.create_container_owner_kw) if spec.create_container_owner_kw else None\\n    if is_create and spec.create_container_owner_kw is not None:\\n        override_owner_id = container_owner_id\\n        owner_override_allowed = True\\n    else:\\n        override_owner_id = owner_id\\n        owner_override_allowed = not is_create or spec.owner_override_on_create\\n\\n    await _ensure_resource_permission(\\n        user,\\n        resource_type=spec.resource_type,\\n        resource_id=resource_id,\\n        owner_id=override_owner_id,\\n        owner_override_allowed=owner_override_allowed,\\n        act_str=act_str,\\n        resolved_domain=resolved_domain,\\n        extra_context=extra_context,\\n    )\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Public ``ensure_*_permission`` helpers \u2014 thin wrappers over ``_ensure_typed``.\\n# Kept individually typed so call sites get IDE / mypy help on which kwargs\\n# each resource accepts.\\n# --------------------------------------------------------------------------- #\\n\\n\\nasync def ensure_flow_permission(\\n    user: User | UserRead,\\n    act: FlowAction | str,\\n    *,\\n    flow_id: UUID | None = None,\\n    flow_user_id: UUID | None = None,\\n    workspace_id: UUID | None = None,\\n    folder_id: UUID | None = None,\\n    folder_user_id: UUID | None = None,\\n    domain: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Check flow permission (owner override, then plugin enforce).\\n\\n    ``folder_user_id`` is the owner of the destination project and is only\\n    consulted for CREATE, where there is no flow owner yet. Pass the value read\\n    from the destination folder row, not one taken from the request body.\\n    \\\"\\\"\\\"\\n    await _ensure_typed(\\n        user,\\n        spec_key=\\\"flow\\\",\\n        act_str=_coerce_action(act),\\n        kwargs={\\n            \\\"flow_id\\\": flow_id,\\n            \\\"flow_user_id\\\": flow_user_id,\\n            \\\"workspace_id\\\": workspace_id,\\n            \\\"folder_id\\\": folder_id,\\n            \\\"folder_user_id\\\": folder_user_id,\\n        },\\n        domain_override=domain,\\n    )\\n\\n\\nasync def _audit_flow_decision_batch(\\n    *,\\n    user_id: UUID | None,\\n    act_str: str,\\n    domain: str,\\n    flow_results: Sequence[tuple[UUID, str]],\\n) -> None:\\n    \\\"\\\"\\\"Audit one allow/deny/owner-override decision per flow id concurrently.\\\"\\\"\\\"\\n    await asyncio.gather(\\n        *(\\n            _audit_guard_decision(\\n                user_id=user_id,\\n                action=f\\\"flow:{act_str}\\\",\\n                obj=f\\\"flow:{flow_id}\\\",\\n                result=result,\\n                details={\\\"domain\\\": domain, **_auth_audit_details()},\\n            )\\n            for flow_id, result in flow_results\\n        )\\n    )\\n\\n\\nasync def ensure_flows_permission(\\n    user: User | UserRead,\\n    act: FlowAction | str,\\n    *,\\n    flow_ids: Sequence[UUID],\\n    flow_user_id: UUID | None = None,\\n    workspace_id: UUID | None = None,\\n    folder_id: UUID | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Authorize ``act`` on every flow id via batched plugin enforce.\\n\\n    Mirrors :func:`ensure_flow_permission` semantics (external-access ceiling,\\n    owner override, domain resolution, audit) but issues one\\n    ``batch_enforce`` call instead of N individual ``enforce`` round-trips.\\n    ``flow_user_id`` / ``workspace_id`` / ``folder_id`` apply to the whole\\n    batch (same owner-namespace / domain for every id). Raises HTTP 403 if any\\n    flow is denied.\\n    \\\"\\\"\\\"\\n    if not flow_ids:\\n        return\\n\\n    act_str = _coerce_action(act)\\n    user_id = getattr(user, \\\"id\\\", None)\\n    resolved_domain = _resolve_authz_domain(workspace_id, folder_id)\\n\\n    external_context = get_current_external_access_context()\\n    if external_context is not None and not external_access_allows(act_str, external_context):\\n        # Same fail-closed path as the single-flow guard; audit the ceiling deny\\n        # once rather than per flow.\\n        await _audit_guard_decision(\\n            user_id=user_id,\\n            action=f\\\"flow:{act_str}\\\",\\n            obj=\\\"flow:*\\\",\\n            result=_audit.AUDIT_DENY,\\n            details={\\n                \\\"domain\\\": resolved_domain,\\n                \\\"external_auth_provider\\\": external_context.provider,\\n                \\\"external_access_level\\\": external_context.level,\\n                \\\"flow_count\\\": len(flow_ids),\\n            },\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"External credentials do not allow this action\\\",\\n        )\\n\\n    settings = get_settings_service()\\n    if not settings.auth_settings.AUTHZ_ENABLED:\\n        await _audit_flow_decision_batch(\\n            user_id=user_id,\\n            act_str=act_str,\\n            domain=resolved_domain,\\n            flow_results=[(flow_id, _audit.AUDIT_ALLOW) for flow_id in flow_ids],\\n        )\\n        return\\n\\n    auth_context = _auth_context(user)\\n    owner_override_enabled = await should_apply_owner_override()\\n    if owner_override_enabled and user_id is not None and flow_user_id == user_id:\\n        await _audit_flow_decision_batch(\\n            user_id=user_id,\\n            act_str=act_str,\\n            domain=resolved_domain,\\n            flow_results=[(flow_id, _audit.AUDIT_OWNER_OVERRIDE) for flow_id in flow_ids],\\n        )\\n        return\\n\\n    authz = get_authorization_service()\\n    requests = [(f\\\"flow:{flow_id}\\\", act_str) for flow_id in flow_ids]\\n    try:\\n        results = await authz.batch_enforce(\\n            user_id=user_id,\\n            domain=resolved_domain,\\n            requests=requests,\\n            context=auth_context,\\n        )\\n    except Exception as exc:\\n        logger.exception(\\\"Authorization plugin raised during batch_enforce; failing closed\\\")\\n        await _audit_guard_decision(\\n            user_id=user_id,\\n            action=f\\\"flow:{act_str}\\\",\\n            obj=\\\"flow:*\\\",\\n            result=_audit.AUDIT_DENY,\\n            details={\\\"domain\\\": resolved_domain, \\\"error\\\": str(exc), **_auth_audit_details()},\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=_DEFAULT_DENY_DETAIL,\\n        ) from exc\\n\\n    if len(results) != len(flow_ids):\\n        logger.error(\\n            \\\"Authorization plugin returned %d batch results for %d flow ids; failing closed\\\",\\n            len(results),\\n            len(flow_ids),\\n        )\\n        await _audit_guard_decision(\\n            user_id=user_id,\\n            action=f\\\"flow:{act_str}\\\",\\n            obj=\\\"flow:*\\\",\\n            result=_audit.AUDIT_DENY,\\n            details={\\n                \\\"domain\\\": resolved_domain,\\n                \\\"error\\\": \\\"batch_enforce result count mismatch\\\",\\n                \\\"expected_results\\\": len(flow_ids),\\n                \\\"actual_results\\\": len(results),\\n                **_auth_audit_details(),\\n            },\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=_DEFAULT_DENY_DETAIL,\\n        )\\n\\n    await _audit_flow_decision_batch(\\n        user_id=user_id,\\n        act_str=act_str,\\n        domain=resolved_domain,\\n        flow_results=[\\n            (flow_id, _audit.AUDIT_ALLOW if allowed else _audit.AUDIT_DENY)\\n            for flow_id, allowed in zip(flow_ids, results, strict=True)\\n        ],\\n    )\\n    if not all(results):\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=_DEFAULT_DENY_DETAIL,\\n        )\\n\\n\\nasync def ensure_deployment_permission(\\n    user: User | UserRead,\\n    act: DeploymentAction | str,\\n    *,\\n    deployment_id: UUID | None = None,\\n    deployment_user_id: UUID | None = None,\\n    workspace_id: UUID | None = None,\\n    project_id: UUID | None = None,\\n    domain: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Check deployment permission (owner override, then plugin enforce).\\\"\\\"\\\"\\n    await _ensure_typed(\\n        user,\\n        spec_key=\\\"deployment\\\",\\n        act_str=_coerce_action(act),\\n        kwargs={\\n            \\\"deployment_id\\\": deployment_id,\\n            \\\"deployment_user_id\\\": deployment_user_id,\\n            \\\"workspace_id\\\": workspace_id,\\n            \\\"project_id\\\": project_id,\\n        },\\n        domain_override=domain,\\n    )\\n\\n\\nasync def ensure_provider_account_permission(\\n    user: User | UserRead,\\n    act: ProviderAccountAction | str,\\n    *,\\n    provider_account_id: UUID | None = None,\\n    provider_account_user_id: UUID | None = None,\\n    domain: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Check provider-account permission without exposing credential metadata.\\\"\\\"\\\"\\n    await _ensure_typed(\\n        user,\\n        spec_key=\\\"provider_account\\\",\\n        act_str=_coerce_action(act),\\n        kwargs={\\n            \\\"provider_account_id\\\": provider_account_id,\\n            \\\"provider_account_user_id\\\": provider_account_user_id,\\n        },\\n        domain_override=domain,\\n    )\\n\\n\\nasync def ensure_voice_permission(\\n    user: User | UserRead,\\n    act: VoiceAction | str,\\n    *,\\n    voice_id: UUID | None = None,\\n    voice_user_id: UUID | None = None,\\n    domain: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Check credential-backed voice permission.\\\"\\\"\\\"\\n    await _ensure_typed(\\n        user,\\n        spec_key=\\\"voice\\\",\\n        act_str=_coerce_action(act),\\n        kwargs={\\n            \\\"voice_id\\\": voice_id,\\n            \\\"voice_user_id\\\": voice_user_id,\\n        },\\n        domain_override=domain,\\n    )\\n\\n\\nasync def ensure_project_permission(\\n    user: User | UserRead,\\n    act: ProjectAction | str,\\n    *,\\n    project_id: UUID | None = None,\\n    project_user_id: UUID | None = None,\\n    workspace_id: UUID | None = None,\\n    domain: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Check project (folder) permission (owner override, then plugin enforce).\\\"\\\"\\\"\\n    await _ensure_typed(\\n        user,\\n        spec_key=\\\"project\\\",\\n        act_str=_coerce_action(act),\\n        kwargs={\\n            \\\"project_id\\\": project_id,\\n            \\\"project_user_id\\\": project_user_id,\\n            \\\"workspace_id\\\": workspace_id,\\n        },\\n        domain_override=domain,\\n    )\\n\\n\\nasync def ensure_knowledge_base_permission(\\n    user: User | UserRead,\\n    act: KnowledgeBaseAction | str,\\n    *,\\n    kb_id: UUID | None = None,\\n    kb_user_id: UUID | None = None,\\n    kb_name: str | None = None,\\n    workspace_id: UUID | None = None,\\n    project_id: UUID | None = None,\\n    domain: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Check knowledge-base permission (owner override, then plugin enforce).\\\"\\\"\\\"\\n    await _ensure_typed(\\n        user,\\n        spec_key=\\\"knowledge_base\\\",\\n        act_str=_coerce_action(act),\\n        kwargs={\\n            \\\"kb_id\\\": kb_id,\\n            \\\"kb_user_id\\\": kb_user_id,\\n            \\\"kb_name\\\": kb_name,\\n            \\\"workspace_id\\\": workspace_id,\\n            \\\"project_id\\\": project_id,\\n        },\\n        domain_override=domain,\\n    )\\n\\n\\nasync def ensure_variable_permission(\\n    user: User | UserRead,\\n    act: VariableAction | str,\\n    *,\\n    variable_id: UUID | None = None,\\n    variable_user_id: UUID | None = None,\\n    workspace_id: UUID | None = None,\\n    domain: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Check variable permission (owner override, then plugin enforce).\\\"\\\"\\\"\\n    await _ensure_typed(\\n        user,\\n        spec_key=\\\"variable\\\",\\n        act_str=_coerce_action(act),\\n        kwargs={\\n            \\\"variable_id\\\": variable_id,\\n            \\\"variable_user_id\\\": variable_user_id,\\n            \\\"workspace_id\\\": workspace_id,\\n        },\\n        domain_override=domain,\\n    )\\n\\n\\nasync def ensure_file_permission(\\n    user: User | UserRead,\\n    act: FileAction | str,\\n    *,\\n    file_id: UUID | None = None,\\n    file_user_id: UUID | None = None,\\n    workspace_id: UUID | None = None,\\n    domain: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Check file permission (owner override, then plugin enforce).\\\"\\\"\\\"\\n    await _ensure_typed(\\n        user,\\n        spec_key=\\\"file\\\",\\n        act_str=_coerce_action(act),\\n        kwargs={\\n            \\\"file_id\\\": file_id,\\n            \\\"file_user_id\\\": file_user_id,\\n            \\\"workspace_id\\\": workspace_id,\\n        },\\n        domain_override=domain,\\n    )\\n\\n\\nasync def ensure_share_permission(\\n    user: User | UserRead,\\n    act: ShareAction | str,\\n    *,\\n    share_id: UUID | None = None,\\n    share_user_id: UUID | None = None,\\n    domain: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Check share-row permission (owner override, then plugin enforce).\\\"\\\"\\\"\\n    await _ensure_typed(\\n        user,\\n        spec_key=\\\"share\\\",\\n        act_str=_coerce_action(act),\\n        kwargs={\\n            \\\"share_id\\\": share_id,\\n            \\\"share_user_id\\\": share_user_id,\\n        },\\n        domain_override=domain,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/invalidation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f280f75ae5989d47d8b865f33de0f45932755dafd7deb1855b0fc4a07fbfd00e\",\"content\":\"\\\"\\\"\\\"Post-commit cache-invalidation helpers for authz admin writes.\\n\\nThe admin routes commit a policy-relevant change to the DB *before* asking the\\nauthorization plugin to drop its cached decisions. That ordering is intentional\\n(the DB row is the source of truth and must land first) but it leaves a window\\nwhere the plugin's invalidation call could fail \u2014 leaving a stale cache while\\nthe API returns 5xx, so the caller can't even tell the mutation took effect.\\n\\nThese helpers bound that window:\\n\\n* ``safe_invalidate_user`` / ``safe_invalidate_role`` try the targeted call\\n  first. On failure they fall back to ``invalidate_all`` \u2014 broader hammer,\\n  same correctness floor \u2014 and log the original error.\\n* ``safe_invalidate_all`` does the same with a single best-effort attempt.\\n\\nNone of them raise: the DB write is already durable, and surfacing a plugin\\nRPC failure as an API failure would only encourage the caller to retry,\\nmaking the bad situation worse. Plugins that detect a stale cache during a\\nlater ``enforce()`` should fail closed; these helpers are the proactive path.\\n\\nTests should patch ``invalidate_user`` / ``invalidate_role`` to raise and\\nassert that (a) the helper does not propagate, and (b) ``invalidate_all`` was\\nattempted. See ``test_authz_admin_routes.py``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from lfx.services.authorization.base import BaseAuthorizationService\\n\\n\\nasync def safe_invalidate_user(\\n    svc: BaseAuthorizationService,\\n    user_id: UUID,\\n    *,\\n    op: str,\\n) -> None:\\n    \\\"\\\"\\\"Drop cached policy for ``user_id``; fall back to ``invalidate_all`` on failure.\\n\\n    ``op`` is a short string (\\\"role_assignment:create\\\", \\\"team_member:delete\\\", \u2026)\\n    used only in log lines so an operator chasing a stale-cache report can\\n    identify which admin write triggered the fallback.\\n    \\\"\\\"\\\"\\n    try:\\n        await svc.invalidate_user(user_id)\\n    except Exception as exc:  # noqa: BLE001 \u2014 plugin contract is best-effort\\n        logger.warning(\\n            \\\"invalidate_user failed after %s for user=%s; falling back to invalidate_all: %s\\\",\\n            op,\\n            user_id,\\n            exc,\\n        )\\n    else:\\n        return\\n    try:\\n        await svc.invalidate_all()\\n    except Exception as exc:  # noqa: BLE001\\n        logger.error(\\n            \\\"invalidate_all fallback failed after %s for user=%s; cache may be stale: %s\\\",\\n            op,\\n            user_id,\\n            exc,\\n        )\\n\\n\\nasync def safe_invalidate_role(\\n    svc: BaseAuthorizationService,\\n    role_id: UUID,\\n    *,\\n    op: str,\\n) -> None:\\n    \\\"\\\"\\\"Drop cached policy for ``role_id``; fall back to ``invalidate_all`` on failure.\\\"\\\"\\\"\\n    try:\\n        await svc.invalidate_role(role_id)\\n    except Exception as exc:  # noqa: BLE001\\n        logger.warning(\\n            \\\"invalidate_role failed after %s for role=%s; falling back to invalidate_all: %s\\\",\\n            op,\\n            role_id,\\n            exc,\\n        )\\n    else:\\n        return\\n    try:\\n        await svc.invalidate_all()\\n    except Exception as exc:  # noqa: BLE001\\n        logger.error(\\n            \\\"invalidate_all fallback failed after %s for role=%s; cache may be stale: %s\\\",\\n            op,\\n            role_id,\\n            exc,\\n        )\\n\\n\\nasync def safe_invalidate_all(\\n    svc: BaseAuthorizationService,\\n    *,\\n    op: str,\\n) -> None:\\n    \\\"\\\"\\\"Drop all cached policy; log on failure but never raise.\\\"\\\"\\\"\\n    try:\\n        await svc.invalidate_all()\\n    except Exception as exc:  # noqa: BLE001\\n        logger.error(\\n            \\\"invalidate_all failed after %s; cache may be stale: %s\\\",\\n            op,\\n            exc,\\n        )\\n\\n\\n__all__ = [\\\"safe_invalidate_all\\\", \\\"safe_invalidate_role\\\", \\\"safe_invalidate_user\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/lifecycle.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"50812fd51da0ca9cb4be890c53c5181cc2d9351e6f8cbcd92177c35df94382fe\",\"content\":\"\\\"\\\"\\\"Transactional lifecycle helpers for authorization plugins.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from lfx.services.authorization.base import (\\n        AuthorizationMutation,\\n        AuthorizationMutationKind,\\n        BaseAuthorizationService,\\n    )\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\nasync def acquire_identity_mutation_lock(\\n    service: BaseAuthorizationService,\\n    session: AsyncSession,\\n    *,\\n    kind: AuthorizationMutationKind,\\n    entity_id: UUID | None = None,\\n    affected_user_ids: tuple[UUID, ...] = (),\\n) -> None:\\n    \\\"\\\"\\\"Run the plugin's lock-only preflight before canonical identity reads.\\\"\\\"\\\"\\n    await service.acquire_identity_mutation_lock(\\n        session=session,\\n        kind=kind,\\n        entity_id=entity_id,\\n        affected_user_ids=affected_user_ids,\\n    )\\n\\n\\nasync def validate_identity_mutation(\\n    service: BaseAuthorizationService,\\n    session: AsyncSession,\\n    mutation: AuthorizationMutation,\\n) -> None:\\n    \\\"\\\"\\\"Run the plugin's pre-mutation identity guard in the caller's transaction.\\\"\\\"\\\"\\n    await service.validate_identity_mutation(\\n        session=session,\\n        mutation=mutation,\\n    )\\n\\n\\nasync def stage_identity_mutation(\\n    service: BaseAuthorizationService,\\n    session: AsyncSession,\\n    mutation: AuthorizationMutation,\\n) -> None:\\n    \\\"\\\"\\\"Stage derived policy before commit; failures abort the canonical write.\\\"\\\"\\\"\\n    await service.stage_identity_mutation(\\n        session=session,\\n        event=mutation,\\n    )\\n\\n\\nasync def safe_identity_mutation_committed(\\n    service: BaseAuthorizationService,\\n    mutation: AuthorizationMutation,\\n) -> None:\\n    \\\"\\\"\\\"Publish a committed change without misreporting the durable DB result.\\n\\n    Staging is the correctness boundary. Publication is a post-commit\\n    convergence optimization, so a plugin failure is logged and left to the\\n    plugin's durable retry/reconciliation path rather than surfaced as a 5xx\\n    that could encourage a duplicate write.\\n    \\\"\\\"\\\"\\n    try:\\n        await service.identity_mutation_committed(mutation)\\n    except Exception:  # noqa: BLE001\\n        logger.exception(\\n            \\\"Authorization lifecycle publication failed after %s for entity=%s\\\",\\n            mutation.kind.value,\\n            mutation.entity_id,\\n        )\\n\\n\\nasync def safe_directory_membership_committed(\\n    service: BaseAuthorizationService,\\n    *,\\n    user_id: UUID,\\n    changed: bool,\\n) -> None:\\n    \\\"\\\"\\\"Publish committed directory membership without misreporting durable success.\\\"\\\"\\\"\\n    try:\\n        await service.directory_membership_committed(user_id=user_id, changed=changed)\\n    except Exception:  # noqa: BLE001\\n        logger.exception(\\n            \\\"Authorization directory publication failed after commit for user=%s\\\",\\n            user_id,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/listing.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f96816d7614e7295c4bcf239fd3a8d5bd0c3dd728f85908fd90d2ed0a886294f\",\"content\":\"\\\"\\\"\\\"List-endpoint filter for authorization checks (batched enforce).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any, TypeVar\\n\\nfrom lfx.services.authorization.base import ResourceVisibilityScope\\nfrom sqlalchemy import Select, and_, false\\nfrom sqlmodel import col, or_\\n\\nfrom langflow.services.authorization.actions import FlowAction\\nfrom langflow.services.authorization.guards import (\\n    _api_key_scopes_require_plugin_enforcement,\\n    _auth_context,\\n    _coerce_action,\\n    should_apply_owner_override,\\n)\\nfrom langflow.services.deps import get_authorization_service, get_settings_service\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Callable, Sequence\\n    from uuid import UUID\\n\\n    from sqlalchemy.orm.attributes import InstrumentedAttribute\\n    from sqlalchemy.sql.elements import ColumnElement\\n\\n    from langflow.services.database.models.user.model import User, UserRead\\n\\n\\nT = TypeVar(\\\"T\\\")\\n# Bound to SQLAlchemy's ``Select`` so the helper accepts both a scalar\\n# ``SelectOfScalar`` (e.g. ``select(Folder)``) and a multi-column ``Select``\\n# (e.g. the deployment page query ``select(Deployment, func.coalesce(...))``),\\n# preserving the concrete statement type through ``.where()`` (returns ``Self``).\\nStatementT = TypeVar(\\\"StatementT\\\", bound=Select[Any])\\n\\n\\ndef _default_resource_id_getter(item: Any) -> UUID:\\n    \\\"\\\"\\\"Default key extractor used by filter_visible_resources.\\\"\\\"\\\"\\n    return item.id\\n\\n\\nasync def filter_visible_resources(\\n    user: User | UserRead,\\n    *,\\n    resource_type: str,\\n    candidates: list[T],\\n    key: Callable[[T], UUID] | None = None,\\n    domain: str = \\\"*\\\",\\n    domain_extractor: Callable[[T], str] | None = None,\\n    owner_extractor: Callable[[T], UUID | None] | None = None,\\n    act: FlowAction | str = FlowAction.READ,\\n) -> list[T]:\\n    \\\"\\\"\\\"Return candidates the user may read (no-op when AUTHZ_ENABLED is false).\\\"\\\"\\\"\\n    settings = get_settings_service()\\n    if not settings.auth_settings.AUTHZ_ENABLED or not candidates:\\n        return candidates\\n\\n    extractor = key if key is not None else _default_resource_id_getter\\n    authz = get_authorization_service()\\n    act_str = _coerce_action(act)\\n    user_id = getattr(user, \\\"id\\\", None)\\n    owner_override_enabled = not await _api_key_scopes_require_plugin_enforcement()\\n\\n    # Owned rows skip batch_enforce (matches direct-read owner override).\\n    owned_indices: set[int] = set()\\n    enforce_indices: list[int] = []\\n    enforce_items: list[T] = []\\n    for index, item in enumerate(candidates):\\n        if (\\n            owner_override_enabled\\n            and owner_extractor is not None\\n            and user_id is not None\\n            and owner_extractor(item) == user_id\\n        ):\\n            owned_indices.add(index)\\n        else:\\n            enforce_indices.append(index)\\n            enforce_items.append(item)\\n\\n    decisions: list[bool] = [False] * len(candidates)\\n    for index in owned_indices:\\n        decisions[index] = True\\n\\n    if enforce_items:\\n        if domain_extractor is None:\\n            # Single-domain batch_enforce.\\n            requests = [(f\\\"{resource_type}:{extractor(item)}\\\", act_str) for item in enforce_items]\\n            results = await authz.batch_enforce(\\n                user_id=user_id,\\n                domain=domain,\\n                requests=requests,\\n                context=_auth_context(user),\\n            )\\n            for original_index, allowed in zip(enforce_indices, results, strict=True):\\n                decisions[original_index] = allowed\\n        else:\\n            # One batch_enforce per resolved domain.\\n            buckets: dict[str, list[tuple[int, T]]] = {}\\n            for original_index, item in zip(enforce_indices, enforce_items, strict=True):\\n                buckets.setdefault(domain_extractor(item), []).append((original_index, item))\\n\\n            auth_context = _auth_context(user)\\n            for resolved_domain, bucket in buckets.items():\\n                bucket_requests = [(f\\\"{resource_type}:{extractor(item)}\\\", act_str) for _, item in bucket]\\n                bucket_results = await authz.batch_enforce(\\n                    user_id=user_id,\\n                    domain=resolved_domain,\\n                    requests=bucket_requests,\\n                    context=auth_context,\\n                )\\n                for (original_index, _), allowed in zip(bucket, bucket_results, strict=True):\\n                    decisions[original_index] = allowed\\n\\n    return [item for item, allowed in zip(candidates, decisions, strict=True) if allowed]\\n\\n\\nasync def visible_id_prefilter(\\n    user: User | UserRead,\\n    *,\\n    resource_type: str,\\n    domain: str = \\\"*\\\",\\n    act: FlowAction | str = FlowAction.READ,\\n) -> list[UUID] | None:\\n    \\\"\\\"\\\"Return the concrete resource ids the caller may ``act`` on, or ``None``.\\n\\n    Thin wrapper over :meth:`BaseAuthorizationService.list_visible_resource_ids`\\n    that gates on ``AUTHZ_ENABLED``. A concrete list lets a list endpoint push a\\n    ``WHERE id IN (...)`` prefilter into its DB query (unioned with the caller's\\n    owned rows via :func:`restrict_to_owned_or_visible`) and skip the fetch-all\\n    + per-row :func:`filter_visible_resources` fallback \u2014 the point of the hook\\n    at large-tenant scale.\\n\\n    Returns ``None`` (meaning \\\"no prefilter; use the in-memory fallback\\\") when\\n    ``AUTHZ_ENABLED`` is false or when the registered service declines to\\n    prefilter \u2014 the OSS pass-through always declines (its base\\n    ``list_visible_resource_ids`` returns ``None``). Callers MUST treat ``None``\\n    as \\\"preserve today's owner-scoped query plus :func:`filter_visible_resources`\\\"\\n    so OSS behavior is byte-for-byte unchanged.\\n    \\\"\\\"\\\"\\n    settings = get_settings_service()\\n    if not settings.auth_settings.AUTHZ_ENABLED:\\n        return None\\n    authz = get_authorization_service()\\n    return await authz.list_visible_resource_ids(\\n        user_id=getattr(user, \\\"id\\\", None),\\n        resource_type=resource_type,\\n        domain=domain,\\n        act=_coerce_action(act),\\n        context=_auth_context(user),\\n    )\\n\\n\\nasync def visible_scope_prefilter(\\n    user: User | UserRead,\\n    *,\\n    resource_type: str,\\n    domain: str = \\\"*\\\",\\n    act: FlowAction | str = FlowAction.READ,\\n) -> ResourceVisibilityScope | None:\\n    \\\"\\\"\\\"Return a compact SQL visibility scope, or ``None`` for the OSS fallback.\\n\\n    Unlike :func:`visible_id_prefilter`, this hook can represent global,\\n    workspace, and project wildcard grants without materializing every matching\\n    resource UUID. The base service adapts legacy concrete-ID plugins.\\n    \\\"\\\"\\\"\\n    settings = get_settings_service()\\n    if not settings.auth_settings.AUTHZ_ENABLED:\\n        return None\\n    authz = get_authorization_service()\\n    get_visibility = getattr(authz, \\\"get_resource_visibility\\\", None)\\n    if get_visibility is not None:\\n        return await get_visibility(\\n            user_id=getattr(user, \\\"id\\\", None),\\n            resource_type=resource_type,\\n            domain=domain,\\n            act=_coerce_action(act),\\n            context=_auth_context(user),\\n        )\\n\\n    # Compatibility for duck-typed services that predate the new base method.\\n    visible_ids = await authz.list_visible_resource_ids(\\n        user_id=getattr(user, \\\"id\\\", None),\\n        resource_type=resource_type,\\n        domain=domain,\\n        act=_coerce_action(act),\\n        context=_auth_context(user),\\n    )\\n    if visible_ids is None:\\n        return None\\n    return ResourceVisibilityScope(resource_ids=tuple(visible_ids))\\n\\n\\ndef restrict_to_owned_or_visible(\\n    stmt: StatementT,\\n    *,\\n    id_column: InstrumentedAttribute,\\n    owner_clause: ColumnElement[bool],\\n    visible_ids: Sequence[UUID],\\n) -> StatementT:\\n    \\\"\\\"\\\"Constrain ``stmt`` to the prefilter union: owner rows \u2295 plugin-visible ids.\\n\\n    A row is kept when it satisfies ``owner_clause`` (the caller's own rows,\\n    always visible via the owner-override invariant \u2014 so an empty ``visible_ids``\\n    still returns every owned row) OR its id is in ``visible_ids`` (rows a\\n    registered authorization plugin reports the caller may read).\\n\\n    ``stmt`` may be a scalar ``select(Model)`` or a multi-column statement (e.g.\\n    the deployment page query ``select(Deployment, func.coalesce(...))``); the\\n    concrete statement type is preserved on return so callers keep their row\\n    shape. ``owner_clause`` must describe only rows the caller owns outright \u2014\\n    do NOT fold a ``user_id IS NULL`` term into it, or null-owner rows would be\\n    blanket-included here while the in-memory fallback policy-checks them via\\n    :func:`filter_visible_resources` (its ``owner_extractor`` returns ``None``,\\n    which never equals a real user id, so those rows go through ``batch_enforce``).\\n    Keeping null-owner rows out of ``owner_clause`` makes a null-owner row\\n    visible only when the plugin lists its id, so both paths enforce alike.\\n\\n    Apply this BEFORE pagination so the page total counts only rows in the\\n    union; an in-memory post-filter would leave the total overcounting rows it\\n    then drops. ``visible_ids`` comes from :func:`visible_id_prefilter`; pass it\\n    only when that returned a concrete list (``None`` keeps today's behavior).\\n    \\\"\\\"\\\"\\n    return stmt.where(or_(col(id_column).in_(list(visible_ids)), owner_clause))\\n\\n\\nasync def apply_owned_or_visible_prefilter(\\n    stmt: StatementT,\\n    *,\\n    id_column: InstrumentedAttribute,\\n    owner_clause: ColumnElement[bool],\\n    visible_ids: Sequence[UUID],\\n) -> StatementT:\\n    \\\"\\\"\\\"Apply a concrete visible-id prefilter, respecting owner override.\\n\\n    When :func:`should_apply_owner_override` is true, delegates to\\n    :func:`restrict_to_owned_or_visible` (owner \u2295 ``visible_ids``). When override\\n    is off, constrains to ``visible_ids`` alone.\\n    \\\"\\\"\\\"\\n    if await should_apply_owner_override():\\n        return restrict_to_owned_or_visible(\\n            stmt,\\n            id_column=id_column,\\n            owner_clause=owner_clause,\\n            visible_ids=visible_ids,\\n        )\\n    return stmt.where(col(id_column).in_(list(visible_ids)))\\n\\n\\ndef restrict_to_owned_or_visible_scope(\\n    stmt: StatementT,\\n    *,\\n    id_column: InstrumentedAttribute,\\n    owner_clause: ColumnElement[bool],\\n    visibility: ResourceVisibilityScope,\\n    workspace_column: InstrumentedAttribute | None = None,\\n    workspace_expression: ColumnElement[Any] | None = None,\\n    project_column: InstrumentedAttribute | None = None,\\n) -> StatementT:\\n    \\\"\\\"\\\"Apply owner, concrete-ID, workspace, and project visibility before pagination.\\\"\\\"\\\"\\n    if visibility.all_resources:\\n        if project_column is None or not visibility.excluded_global_project_ids:\\n            return stmt\\n        # Global role access can exclude reserved projects without enumerating\\n        # every visible resource. Ownership and concrete grants remain additive,\\n        # so users retain their own resources and directly shared resources in\\n        # an otherwise excluded project. Folderless resources remain global.\\n        global_clauses: list[ColumnElement[bool]] = [\\n            owner_clause,\\n            col(project_column).is_(None),\\n            col(project_column).not_in(visibility.excluded_global_project_ids),\\n        ]\\n        if visibility.resource_ids:\\n            global_clauses.append(col(id_column).in_(visibility.resource_ids))\\n        return stmt.where(or_(*global_clauses))\\n\\n    clauses: list[ColumnElement[bool]] = [owner_clause]\\n    if visibility.resource_ids:\\n        clauses.append(col(id_column).in_(visibility.resource_ids))\\n    resolved_workspace = workspace_expression\\n    if resolved_workspace is None and workspace_column is not None:\\n        resolved_workspace = col(workspace_column)\\n    workspace_project_allowed: ColumnElement[bool] | None = None\\n    if project_column is not None and visibility.excluded_workspace_project_ids:\\n        # A workspace-only resource has no project to exclude. Keep it visible\\n        # for an explicit workspace grant while excluding resources attached to\\n        # reserved projects. The explicit ``IS NULL`` branch also keeps SQL's\\n        # three-valued NULL semantics aligned with ``resource_visible_in_scope``.\\n        workspace_project_allowed = or_(\\n            col(project_column).is_(None),\\n            col(project_column).not_in(visibility.excluded_workspace_project_ids),\\n        )\\n    if resolved_workspace is not None and visibility.workspace_ids:\\n        workspace_clause = resolved_workspace.in_(visibility.workspace_ids)\\n        if workspace_project_allowed is not None:\\n            workspace_clause = and_(workspace_clause, workspace_project_allowed)\\n        clauses.append(workspace_clause)\\n    if resolved_workspace is not None and project_column is not None and visibility.include_unassigned_workspace:\\n        # The logical unassigned workspace contains projects whose stored\\n        # workspace is NULL; it does not contain folderless/workspace-less\\n        # resources. Requiring a concrete project keeps list filtering aligned\\n        # with direct authorization, which resolves this scope through the\\n        # resource's project relation.\\n        unassigned_project_allowed = col(project_column).is_not(None)\\n        if visibility.excluded_workspace_project_ids:\\n            unassigned_project_allowed = and_(\\n                unassigned_project_allowed,\\n                col(project_column).not_in(visibility.excluded_workspace_project_ids),\\n            )\\n        workspace_clause = and_(resolved_workspace.is_(None), unassigned_project_allowed)\\n        clauses.append(workspace_clause)\\n    if project_column is not None and visibility.project_ids:\\n        clauses.append(col(project_column).in_(visibility.project_ids))\\n    return stmt.where(or_(*clauses))\\n\\n\\nasync def apply_owned_or_visible_scope_prefilter(\\n    stmt: StatementT,\\n    *,\\n    id_column: InstrumentedAttribute,\\n    owner_clause: ColumnElement[bool],\\n    visibility: ResourceVisibilityScope,\\n    workspace_column: InstrumentedAttribute | None = None,\\n    workspace_expression: ColumnElement[Any] | None = None,\\n    project_column: InstrumentedAttribute | None = None,\\n) -> StatementT:\\n    \\\"\\\"\\\"Apply a structured visibility prefilter, respecting owner override.\\\"\\\"\\\"\\n    effective_owner_clause = owner_clause if await should_apply_owner_override() else false()\\n    return restrict_to_owned_or_visible_scope(\\n        stmt,\\n        id_column=id_column,\\n        owner_clause=effective_owner_clause,\\n        visibility=visibility,\\n        workspace_column=workspace_column,\\n        workspace_expression=workspace_expression,\\n        project_column=project_column,\\n    )\\n\\n\\ndef resource_visible_in_scope(\\n    *,\\n    resource_id: UUID,\\n    visibility: ResourceVisibilityScope,\\n    workspace_id: UUID | None = None,\\n    project_id: UUID | None = None,\\n) -> bool:\\n    \\\"\\\"\\\"Evaluate a compact visibility scope for an already-loaded resource.\\\"\\\"\\\"\\n    globally_visible = visibility.all_resources and (\\n        project_id is None or project_id not in visibility.excluded_global_project_ids\\n    )\\n    workspace_project_allowed = project_id is None or project_id not in visibility.excluded_workspace_project_ids\\n    unassigned_project_allowed = project_id is not None and project_id not in visibility.excluded_workspace_project_ids\\n    return bool(\\n        globally_visible\\n        or resource_id in visibility.resource_ids\\n        or (workspace_project_allowed and workspace_id is not None and workspace_id in visibility.workspace_ids)\\n        or (unassigned_project_allowed and workspace_id is None and visibility.include_unassigned_workspace)\\n        or (project_id is not None and project_id in visibility.project_ids)\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/public_access.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6e258dc0b625dea16a84736942c53b278f99578d3b4c725dde3513c92aa78db8\",\"content\":\"\\\"\\\"\\\"Fail-closed authorization for anonymous direct-link flow access.\\n\\nAnonymous visitors are not users and never enter the authenticated OSS\\nallow-all authorization path. A request must first match a canonical PUBLIC\\n``AuthzShare`` or one of the two release-compatibility grants, then (when\\nauthorization is enabled) pass an opt-in plugin tenant and policy decision.\\nThese grants are direct-link only and must never be used by list endpoints.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import dataclass\\nfrom datetime import datetime, timezone\\nfrom enum import Enum\\nfrom typing import TYPE_CHECKING\\n\\nfrom fastapi import HTTPException, status\\nfrom lfx.log.logger import logger\\nfrom lfx.services.authorization import (\\n    PUBLIC_ANONYMOUS_ACTOR_ID,\\n    AuthorizationPrincipal,\\n    PublicAuthorizationRequest,\\n    PublicResourceAction,\\n)\\nfrom lfx.services.deps import session_scope_readonly\\nfrom pydantic import BaseModel, Field\\nfrom sqlmodel import select\\n\\nfrom langflow.services.authorization.audit import AUDIT_ALLOW, AUDIT_DENY, audit_decision\\nfrom langflow.services.authorization.guards import _resolve_authz_domain\\nfrom langflow.services.database.models.auth import AuthzShare, ShareScope\\nfrom langflow.services.database.models.flow.model import AccessTypeEnum\\nfrom langflow.services.database.models.user.model import UserRead\\nfrom langflow.services.deps import get_authorization_service, get_settings_service\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n    from langflow.services.database.models.flow.model import Flow\\n\\n\\nclass PublicGrantSource(str, Enum):\\n    \\\"\\\"\\\"Durable or compatibility source of an anonymous direct-link grant.\\\"\\\"\\\"\\n\\n    AUTHZ_SHARE = \\\"authz_share\\\"\\n    LEGACY_ACCESS_TYPE = \\\"legacy_access_type\\\"\\n    A2A_AUTH_NONE = \\\"a2a_auth_none\\\"\\n\\n\\nclass PublicFlowCapabilities(BaseModel):\\n    \\\"\\\"\\\"Anonymous direct-link capabilities for one flow.\\n\\n    Serialized into direct-link responses so a client renders the actions this\\n    layer would actually allow, rather than re-deriving them from the legacy\\n    ``Flow.access_type`` flag.\\n    \\\"\\\"\\\"\\n\\n    can_read: bool = Field(description=\\\"Anonymous callers may read this flow at its direct link.\\\")\\n    can_execute: bool = Field(description=\\\"Anonymous callers may run this flow at its direct link.\\\")\\n\\n\\n_READ_PERMISSIONS = frozenset({\\\"read\\\", \\\"execute\\\", \\\"write\\\", \\\"admin\\\"})\\n_EXECUTE_PERMISSIONS = frozenset({\\\"execute\\\", \\\"write\\\", \\\"admin\\\"})\\nPUBLIC_FLOW_NOT_FOUND_DETAIL = \\\"Flow not found\\\"\\n\\n\\ndef public_grant_allows(permission_level: str, action: PublicResourceAction) -> bool:\\n    \\\"\\\"\\\"Apply the OSS anonymous action floor to a share permission level.\\n\\n    Higher share levels retain their read/execute implication, but anonymous\\n    callers can never mutate, create, delete, deploy, or administer resources.\\n    \\\"\\\"\\\"\\n    if action is PublicResourceAction.READ:\\n        return permission_level in _READ_PERMISSIONS\\n    if action is PublicResourceAction.EXECUTE:\\n        return permission_level in _EXECUTE_PERMISSIONS\\n    return False\\n\\n\\ndef public_execution_user() -> UserRead:\\n    \\\"\\\"\\\"Return the stable non-persisted runtime identity for public execution.\\\"\\\"\\\"\\n    epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)\\n    return UserRead(\\n        id=PUBLIC_ANONYMOUS_ACTOR_ID,\\n        username=\\\"anonymous-public\\\",\\n        profile_image=None,\\n        store_api_key=None,\\n        is_active=True,\\n        is_superuser=False,\\n        create_at=epoch,\\n        updated_at=epoch,\\n        last_login_at=None,\\n        optins=None,\\n    )\\n\\n\\nasync def _public_share_permission(session: AsyncSession, flow_id: UUID) -> str | None:\\n    statement = select(AuthzShare.permission_level).where(\\n        AuthzShare.resource_type == \\\"flow\\\",\\n        AuthzShare.resource_id == flow_id,\\n        AuthzShare.scope == ShareScope.PUBLIC.value,\\n    )\\n    return (await session.exec(statement)).first()\\n\\n\\nasync def _resolve_grant(\\n    *,\\n    flow: Flow,\\n    action: PublicResourceAction,\\n    session: AsyncSession | None,\\n    compatibility_grant: PublicGrantSource | None,\\n) -> PublicGrantSource | None:\\n    if action not in {PublicResourceAction.READ, PublicResourceAction.EXECUTE}:\\n        return None\\n\\n    if session is None:\\n        async with session_scope_readonly() as read_session:\\n            permission = await _public_share_permission(read_session, flow.id)\\n    else:\\n        permission = await _public_share_permission(session, flow.id)\\n\\n    if permission is not None:\\n        # A canonical PUBLIC share is authoritative for every anonymous action on\\n        # this resource. Its level bounds the grant, so a still-set legacy flag\\n        # cannot widen a read-only share back to execute, and the level the owner\\n        # chose is the level that is enforced.\\n        return PublicGrantSource.AUTHZ_SHARE if public_grant_allows(permission, action) else None\\n    if flow.access_type is AccessTypeEnum.PUBLIC:\\n        return PublicGrantSource.LEGACY_ACCESS_TYPE\\n    if compatibility_grant is PublicGrantSource.A2A_AUTH_NONE:\\n        return PublicGrantSource.A2A_AUTH_NONE\\n    return None\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass _PublicDecision:\\n    \\\"\\\"\\\"One resolved anonymous decision, before it is audited or enforced.\\\"\\\"\\\"\\n\\n    allowed: bool\\n    domain: str\\n    grant_source: str\\n    tenant: str | None\\n\\n\\nasync def _decide(\\n    *,\\n    flow: Flow,\\n    action: PublicResourceAction,\\n    principal: AuthorizationPrincipal,\\n    request_host: str | None,\\n    compatibility_grant: PublicGrantSource | None,\\n    session: AsyncSession | None,\\n) -> _PublicDecision:\\n    \\\"\\\"\\\"Resolve the grant and, when authorization is enabled, the policy verdict.\\\"\\\"\\\"\\n    source = await _resolve_grant(\\n        flow=flow,\\n        action=action,\\n        session=session,\\n        compatibility_grant=compatibility_grant,\\n    )\\n    domain = _resolve_authz_domain(flow.workspace_id, flow.folder_id)\\n    request = PublicAuthorizationRequest(\\n        principal=principal,\\n        resource_type=\\\"flow\\\",\\n        resource_id=flow.id,\\n        action=action,\\n        domain_hint=domain,\\n        request_host=request_host,\\n        grant_source=source.value if source is not None else \\\"none\\\",\\n    )\\n\\n    allowed = source is not None\\n    tenant: str | None = None\\n    auth_settings = get_settings_service().auth_settings\\n    if allowed and auth_settings.AUTHZ_ENABLED:\\n        try:\\n            # Resolving the service is inside the guard on purpose: a service that\\n            # cannot be constructed must deny like any other policy failure and\\n            # still record the audit row in the caller, not escape as a 500.\\n            authorization_service = get_authorization_service()\\n            if not await authorization_service.supports_public_principals():\\n                allowed = False\\n            else:\\n                tenant = await authorization_service.resolve_public_tenant(request)\\n                allowed = bool(tenant) and await authorization_service.enforce_public(request, tenant=tenant)\\n        except Exception:  # noqa: BLE001 - an anonymous policy failure must fail closed\\n            allowed = False\\n            await logger.aexception(\\\"Anonymous public authorization failed closed for flow %s\\\", flow.id)\\n\\n    return _PublicDecision(allowed=allowed, domain=domain, grant_source=request.grant_source, tenant=tenant)\\n\\n\\nasync def authorize_public_flow_access(\\n    *,\\n    flow: Flow,\\n    action: PublicResourceAction,\\n    request_host: str | None = None,\\n    compatibility_grant: PublicGrantSource | None = None,\\n    session: AsyncSession | None = None,\\n) -> AuthorizationPrincipal:\\n    \\\"\\\"\\\"Authorize a direct-link flow action and return its anonymous principal.\\n\\n    The caller must load the exact flow by its direct-link identifier. This\\n    function never performs tenant discovery and never grants list visibility.\\n\\n    A canonical PUBLIC share, when present, is the only grant consulted: its\\n    permission level bounds the action and a still-set legacy flag cannot widen\\n    it. With no share row, changing ``Flow.access_type``/A2A ``auth_type``\\n    removes the compatibility grant. New starts and resumes call this function\\n    again, while already-running work is not interrupted.\\n    \\\"\\\"\\\"\\n    principal = AuthorizationPrincipal.public_anonymous()\\n    decision = await _decide(\\n        flow=flow,\\n        action=action,\\n        principal=principal,\\n        request_host=request_host,\\n        compatibility_grant=compatibility_grant,\\n        session=session,\\n    )\\n\\n    await audit_decision(\\n        user_id=None,\\n        principal=principal,\\n        action=f\\\"flow:{action.value}\\\",\\n        obj=f\\\"flow:{flow.id}\\\",\\n        result=AUDIT_ALLOW if decision.allowed else AUDIT_DENY,\\n        details={\\n            \\\"domain\\\": decision.domain,\\n            \\\"grant_source\\\": decision.grant_source,\\n            **({\\\"tenant\\\": decision.tenant} if decision.tenant is not None else {}),\\n        },\\n    )\\n    if not decision.allowed:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=PUBLIC_FLOW_NOT_FOUND_DETAIL)\\n    return principal\\n\\n\\nasync def public_flow_capabilities(\\n    *,\\n    flow: Flow,\\n    request_host: str | None = None,\\n    session: AsyncSession | None = None,\\n) -> PublicFlowCapabilities:\\n    \\\"\\\"\\\"Report which anonymous direct-link actions this flow currently permits.\\n\\n    A direct-link UI needs this because the grant it was admitted by is not\\n    visible in the flow row: a canonical ``AuthzShare(scope=public)`` authorizes\\n    a flow whose ``access_type`` is still PRIVATE, and its permission level \u2014\\n    not the legacy flag \u2014 is what bounds execution. Re-deriving public access\\n    from ``Flow.access_type`` in the client disagrees with this layer in both\\n    directions, so callers should render from these flags instead.\\n\\n    Advisory only. It grants nothing: every action still authorizes itself on\\n    its own request path through :func:`authorize_public_flow_access`. It is\\n    also deliberately not audited \u2014 the visitor is not attempting these actions,\\n    and emitting a DENY row per page view would turn every read-only share into\\n    a stream of false anonymous-denial signals for operators.\\n    \\\"\\\"\\\"\\n    principal = AuthorizationPrincipal.public_anonymous()\\n\\n    async def _allows(action: PublicResourceAction) -> bool:\\n        decision = await _decide(\\n            flow=flow,\\n            action=action,\\n            principal=principal,\\n            request_host=request_host,\\n            compatibility_grant=None,\\n            session=session,\\n        )\\n        return decision.allowed\\n\\n    return PublicFlowCapabilities(\\n        can_read=await _allows(PublicResourceAction.READ),\\n        can_execute=await _allows(PublicResourceAction.EXECUTE),\\n    )\\n\\n\\n__all__ = [\\n    \\\"PUBLIC_ANONYMOUS_ACTOR_ID\\\",\\n    \\\"PUBLIC_FLOW_NOT_FOUND_DETAIL\\\",\\n    \\\"PublicFlowCapabilities\\\",\\n    \\\"PublicGrantSource\\\",\\n    \\\"PublicResourceAction\\\",\\n    \\\"authorize_public_flow_access\\\",\\n    \\\"public_execution_user\\\",\\n    \\\"public_flow_capabilities\\\",\\n    \\\"public_grant_allows\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f645aca0ecf51d1c72dfbf62da3e7986eacf1512509bec2d7b8ab4fac86670a1\",\"content\":\"\\\"\\\"\\\"Langflow authorization service (OSS pass-through; plugins enforce RBAC).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Sequence\\n    from uuid import UUID\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.authorization.base import BaseAuthorizationService\\nfrom lfx.services.schema import ServiceType\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.auth import AuthSettings\\n    from lfx.services.settings.service import SettingsService\\n\\n\\nclass LangflowAuthorizationService(BaseAuthorizationService):\\n    \\\"\\\"\\\"OSS pass-through authorization service (always allows).\\\"\\\"\\\"\\n\\n    def __init__(self, settings_service: SettingsService) -> None:\\n        \\\"\\\"\\\"Store the settings service reference.\\\"\\\"\\\"\\n        super().__init__()\\n        self.settings_service = settings_service\\n        self.set_ready()\\n        logger.debug(\\\"Langflow authorization service initialized\\\")\\n        # Loud, operator-visible warning when AUTHZ_ENABLED is on but the\\n        # registered service is the OSS pass-through. Without an enforcement\\n        # plugin registered via ``lfx.toml``, ``enforce()`` returns True for\\n        # every request \u2014 so flipping the env var alone changes nothing except\\n        # audit-log emission. The dry-run CLI helps verify policy decisions,\\n        # but ops engineers can be misled by a \\\"True\\\" flag.\\n        try:\\n            authz_enabled = bool(getattr(settings_service.auth_settings, \\\"AUTHZ_ENABLED\\\", False))\\n        except Exception:  # noqa: BLE001 \u2014 never break startup on a warning probe\\n            authz_enabled = False\\n        if authz_enabled and not self.SUPPORTS_CROSS_USER_FETCH:\\n            logger.warning(\\n                \\\"LANGFLOW_AUTHZ_ENABLED=true but the OSS pass-through authorization service is \\\"\\n                \\\"registered (no enforcement plugin found). Every enforce() call will return True; \\\"\\n                \\\"route guards still run and audit rows still write, but no policy is applied. \\\"\\n                \\\"Register an authorization plugin via lfx.toml or set LANGFLOW_AUTHZ_ENABLED=false \\\"\\n                \\\"to silence this warning.\\\"\\n            )\\n\\n    @property\\n    def name(self) -> str:\\n        \\\"\\\"\\\"Return the canonical service-type name.\\\"\\\"\\\"\\n        return ServiceType.AUTHORIZATION_SERVICE.value\\n\\n    def _authz_settings(self) -> AuthSettings:\\n        \\\"\\\"\\\"Return the live AuthSettings snapshot.\\\"\\\"\\\"\\n        return self.settings_service.auth_settings\\n\\n    async def is_enabled(self) -> bool:\\n        \\\"\\\"\\\"Return True when AUTHZ_ENABLED is set.\\\"\\\"\\\"\\n        return self._authz_settings().AUTHZ_ENABLED\\n\\n    async def enforce(\\n        self,\\n        *,\\n        user_id: UUID,  # noqa: ARG002\\n        domain: str,  # noqa: ARG002\\n        obj: str,  # noqa: ARG002\\n        act: str,  # noqa: ARG002\\n        context: dict[str, Any] | None = None,  # noqa: ARG002\\n    ) -> bool:\\n        \\\"\\\"\\\"Allow every request in the OSS default.\\\"\\\"\\\"\\n        return True\\n\\n    async def batch_enforce(\\n        self,\\n        *,\\n        user_id: UUID,  # noqa: ARG002\\n        domain: str,  # noqa: ARG002\\n        requests: Sequence[tuple[str, str]],\\n        context: dict[str, Any] | None = None,  # noqa: ARG002\\n    ) -> list[bool]:\\n        \\\"\\\"\\\"Return True for each request.\\\"\\\"\\\"\\n        return [True] * len(requests)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f0d53994f5fce43c0607f27ac2c07ce393efa118facd964d24cca090b37c165d\",\"content\":\"\\\"\\\"\\\"Backward-compatible re-exports for the split authorization helpers.\\n\\nThe implementations now live in:\\n\\n* ``langflow.services.authorization.audit``   \u2014 batched audit pipeline\\n* ``langflow.services.authorization.guards``  \u2014 ``ensure_*_permission`` family\\n* ``langflow.services.authorization.listing`` \u2014 ``filter_visible_resources``\\n\\nThis module is preserved so existing imports\\n(``from langflow.services.authorization.utils import ensure_flow_permission``)\\nkeep working. New code should import from the focused submodules above.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom fastapi import HTTPException, status\\n\\nfrom langflow.services.authorization.audit import (\\n    _AUDIT_BATCH_MAX,\\n    _AUDIT_QUEUE_MAX,\\n    AuditPersistenceError,\\n    _audit_writer_loop,\\n    _AuditEntry,\\n    _ensure_audit_writer_started,\\n    _flush_audit_batch,\\n    _split_obj,\\n    audit_decision,\\n    drain_pending_audit_writes,\\n    get_audit_producer_health,\\n)\\nfrom langflow.services.authorization.audit import (\\n    AUDIT_ALLOW as _AUDIT_ALLOW,\\n)\\nfrom langflow.services.authorization.audit import (\\n    AUDIT_DENY as _AUDIT_DENY,\\n)\\nfrom langflow.services.authorization.audit import (\\n    AUDIT_OWNER_OVERRIDE as _AUDIT_OWNER_OVERRIDE,\\n)\\nfrom langflow.services.authorization.audit import (\\n    AUDIT_SKIP as _AUDIT_SKIP,\\n)\\nfrom langflow.services.authorization.guards import (\\n    _ACTION_ENUMS,\\n    _OWNER_CONTEXT_KEYS,\\n    _auth_context,\\n    _coerce_action,\\n    _ensure_resource_permission,\\n    _resolve_authz_domain,\\n    _resolve_flow_domain,\\n    ensure_deployment_permission,\\n    ensure_file_permission,\\n    ensure_flow_permission,\\n    ensure_flows_permission,\\n    ensure_knowledge_base_permission,\\n    ensure_permission,\\n    ensure_project_permission,\\n    ensure_provider_account_permission,\\n    ensure_share_permission,\\n    ensure_variable_permission,\\n    ensure_voice_permission,\\n    should_apply_owner_override,\\n)\\nfrom langflow.services.authorization.listing import (\\n    _default_resource_id_getter,\\n    filter_visible_resources,\\n)\\nfrom langflow.services.deps import get_authorization_service, get_settings_service\\n\\n# Pre-rename name kept for plugins built against the casbin-specific\\n# wording. Functionally identical to ``_resolve_authz_domain`` \u2014 same\\n# (workspace_id, scope_id) \u2192 domain-string resolution. New code should\\n# import ``_resolve_authz_domain`` directly.\\n_resolve_casbin_domain = _resolve_authz_domain\\n\\n\\ndef permission_denied_to_http(exc):\\n    \\\"\\\"\\\"Translate an InsufficientPermissionsError into a 403 HTTPException.\\\"\\\"\\\"\\n    return HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=exc.message)\\n\\n\\n__all__ = [\\n    \\\"_ACTION_ENUMS\\\",\\n    \\\"_AUDIT_ALLOW\\\",\\n    \\\"_AUDIT_BATCH_MAX\\\",\\n    \\\"_AUDIT_DENY\\\",\\n    \\\"_AUDIT_OWNER_OVERRIDE\\\",\\n    \\\"_AUDIT_QUEUE_MAX\\\",\\n    \\\"_AUDIT_SKIP\\\",\\n    \\\"_OWNER_CONTEXT_KEYS\\\",\\n    \\\"AuditPersistenceError\\\",\\n    \\\"_AuditEntry\\\",\\n    \\\"_audit_writer_loop\\\",\\n    \\\"_auth_context\\\",\\n    \\\"_coerce_action\\\",\\n    \\\"_default_resource_id_getter\\\",\\n    \\\"_ensure_audit_writer_started\\\",\\n    \\\"_ensure_resource_permission\\\",\\n    \\\"_flush_audit_batch\\\",\\n    \\\"_resolve_authz_domain\\\",\\n    \\\"_resolve_casbin_domain\\\",\\n    \\\"_resolve_flow_domain\\\",\\n    \\\"_split_obj\\\",\\n    \\\"audit_decision\\\",\\n    \\\"drain_pending_audit_writes\\\",\\n    \\\"ensure_deployment_permission\\\",\\n    \\\"ensure_file_permission\\\",\\n    \\\"ensure_flow_permission\\\",\\n    \\\"ensure_flows_permission\\\",\\n    \\\"ensure_knowledge_base_permission\\\",\\n    \\\"ensure_permission\\\",\\n    \\\"ensure_project_permission\\\",\\n    \\\"ensure_provider_account_permission\\\",\\n    \\\"ensure_share_permission\\\",\\n    \\\"ensure_variable_permission\\\",\\n    \\\"ensure_voice_permission\\\",\\n    \\\"filter_visible_resources\\\",\\n    \\\"get_audit_producer_health\\\",\\n    \\\"get_authorization_service\\\",\\n    \\\"get_settings_service\\\",\\n    \\\"permission_denied_to_http\\\",\\n    \\\"should_apply_owner_override\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/background_execution/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"abf402e1b2c7d582dff1bc11e5b6225409f46bb85ef1e089a7fdc8359ad53e31\",\"content\":\"\\\"\\\"\\\"Background execution service: facade + default in-process backend.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/background_execution/executor.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5d735179890c9a92dbafcf9ee53bb1c1ec4c49703d9c7ee6c2656638e9e6a85d\",\"content\":\"\\\"\\\"\\\"Bounded in-process executor for background workflow jobs.\\n\\nA small pool of worker tasks drains a single ``asyncio.Queue`` of submitted\\njobs. Concurrency is capped at ``max_concurrency`` so background runs cannot\\nstarve the request event loop. A job is a ``(key, coro_factory)`` pair: the\\nfactory is invoked by the worker that picks it up, so the coroutine is created\\nat execution time (not submit time) and a queued job holds no live coroutine.\\n\\nCancellation is keyed: ``cancel(key)`` cancels the in-flight task for that key.\\nA still-queued job is cancelled cooperatively by the caller (the runner checks\\nthe durable STOP signal before it starts emitting); the executor only owns\\nin-flight task cancellation.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nfrom collections.abc import Awaitable, Callable\\n\\nfrom lfx.log.logger import logger\\n\\nCoroFactory = Callable[[], Awaitable[None]]\\n\\n\\nclass InProcessExecutor:\\n    \\\"\\\"\\\"A bounded worker pool over an asyncio.Queue.\\\"\\\"\\\"\\n\\n    def __init__(self, max_concurrency: int = 5) -> None:\\n        self._max_concurrency = max(int(max_concurrency), 1)\\n        self._queue: asyncio.Queue[tuple[str, CoroFactory]] = asyncio.Queue()\\n        self._workers: list[asyncio.Task] = []\\n        # Maps a job key to its in-flight task so cancel() can reach it.\\n        self._in_flight: dict[str, asyncio.Task] = {}\\n        self._closed = False\\n\\n    async def start(self) -> None:\\n        if self._workers:\\n            return\\n        self._closed = False\\n        self._workers = [asyncio.create_task(self._worker(i)) for i in range(self._max_concurrency)]\\n        await logger.adebug(f\\\"InProcessExecutor started with {self._max_concurrency} workers\\\")\\n\\n    async def stop(self) -> None:\\n        self._closed = True\\n        # Cancel the in-flight JOB tasks directly first, then await them. A job\\n        # that catches its cancel (a user-stop reconciles to CANCELLED) would\\n        # otherwise leave the worker's ``await task`` in cancellation limbo, so we\\n        # do not rely on cancellation propagating through the worker. Awaiting the\\n        # job tasks here lets each one's shielded terminal reconcile finish BEFORE\\n        # teardown \u2014 without it a reconcile write races a closing DB engine and a\\n        # \\\"Task was destroyed but it is pending\\\" warning is logged.\\n        # return_exceptions swallows the CancelledError each task raises so one\\n        # cancel cannot mask the others.\\n        in_flight = list(self._in_flight.values())\\n        for task in in_flight:\\n            task.cancel()\\n        if in_flight:\\n            await asyncio.gather(*in_flight, return_exceptions=True)\\n        self._in_flight.clear()\\n        for task in self._workers:\\n            task.cancel()\\n        for task in self._workers:\\n            with contextlib.suppress(asyncio.CancelledError):\\n                await task\\n        self._workers.clear()\\n\\n    async def submit(self, key: str, coro_factory: CoroFactory) -> None:\\n        \\\"\\\"\\\"Enqueue a job. A free worker picks it up and invokes the factory.\\\"\\\"\\\"\\n        if self._closed:\\n            msg = \\\"Executor is closed\\\"\\n            raise RuntimeError(msg)\\n        await self._queue.put((key, coro_factory))\\n\\n    async def cancel(self, key: str) -> bool:\\n        \\\"\\\"\\\"Cancel the in-flight task for ``key``. Returns False if not in flight.\\\"\\\"\\\"\\n        task = self._in_flight.get(key)\\n        if task is None or task.done():\\n            return False\\n        task.cancel()\\n        return True\\n\\n    @staticmethod\\n    async def _await_task(task: asyncio.Task) -> None:\\n        # A bare ``await task`` relies on the task's own wakeup of its awaiter. On\\n        # Python 3.10, when stop() cancels this worker while the job task is also\\n        # finishing, that wakeup is lost: the job task completes but the worker is\\n        # never rescheduled, so the event loop idles forever in select(None) \u2014 a\\n        # hard deadlock in stop(). A done-callback + Event is immune (it is the\\n        # same mechanism stop()'s own asyncio.gather uses, which never hangs), and\\n        # task.result() re-raises CancelledError/exception exactly like await task.\\n        done = asyncio.Event()\\n        task.add_done_callback(lambda _t: done.set())\\n        await done.wait()\\n        task.result()\\n\\n    async def _worker(self, worker_id: int) -> None:\\n        while True:\\n            try:\\n                key, coro_factory = await self._queue.get()\\n            except asyncio.CancelledError:\\n                return\\n            task = asyncio.create_task(coro_factory())\\n            self._in_flight[key] = task\\n            try:\\n                await self._await_task(task)\\n            except asyncio.CancelledError:\\n                # A cancelled job must not take the worker down with it \u2014 but a\\n                # cancel aimed at the WORKER (stop()) must. ``Task.cancelling()``\\n                # is Python 3.11+; the project supports 3.10, so we distinguish\\n                # the two with an explicit ``_closed`` flag set by ``stop()``\\n                # rather than that version-specific API. When ``stop()`` ran, the\\n                # cancel targets the worker \u2014 re-raise to exit. Otherwise it was\\n                # a ``cancel(key)`` aimed at the job \u2014 swallow and keep serving.\\n                if self._closed:\\n                    raise\\n                await logger.adebug(f\\\"Background job {key} cancelled on worker {worker_id}\\\")\\n            except Exception as exc:  # noqa: BLE001\\n                await logger.aerror(f\\\"Background job {key} failed on worker {worker_id}: {exc}\\\", exc_info=True)\\n            finally:\\n                if self._in_flight.get(key) is task:\\n                    self._in_flight.pop(key, None)\\n                self._queue.task_done()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/background_execution/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bf78a70ec223faeb0f2737b5dacdf3944b311eff68aabaee0b1fad6dd1548b13\",\"content\":\"\\\"\\\"\\\"Factory for BackgroundExecutionService.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom typing_extensions import override\\n\\nfrom langflow.services.background_execution.service import BackgroundExecutionService\\nfrom langflow.services.factory import ServiceFactory\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.service import SettingsService\\n\\n\\nclass BackgroundExecutionServiceFactory(ServiceFactory):\\n    def __init__(self) -> None:\\n        super().__init__(BackgroundExecutionService)\\n\\n    @override\\n    def create(self, settings_service: SettingsService):\\n        return BackgroundExecutionService(settings_service)\\n\\n\\ndef select_background_backend(settings, *, client, job_service):\\n    \\\"\\\"\\\"Pick the scaled background backend per settings, or None for the default.\\n\\n    Scaled (redis) when ``settings.background_backend_is_scaled`` is True \u2014 a\\n    separate ``langflow worker`` process drains the claim queue and publishes\\n    live frames to redis Streams. Otherwise return None: the facade owns the\\n    in-process executor + in-memory bus path directly (no separate backend\\n    object). Backend selection follows the existing job_queue_type/redis\\n    settings; see ``Settings.background_backend_is_scaled``.\\n    \\\"\\\"\\\"\\n    if settings.background_backend_is_scaled:\\n        from langflow.services.background_execution.redis_backend import RedisBackgroundQueue\\n\\n        return RedisBackgroundQueue(client=client, job_service=job_service)\\n    return None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/background_execution/live_bus.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5e00ef0c66e22e681f5b108c59c0115458e9d0977f7ac55f4213af7592e384bc\",\"content\":\"\\\"\\\"\\\"In-process live event bus for background workflow runs.\\n\\nPublishers (the runner) push ``LiveFrame``s for a job; live subscribers receive\\nthem through a bounded per-subscriber queue. ``reattach`` first replays the\\ndurable log (via the injected ``read_durable``) from the caller's last seen seq,\\nthen switches to the live tail \u2014 deduplicating any seq already replayed so a\\nframe straddling the replay/tail boundary is emitted exactly once.\\n\\nThis bus is process-local; the redis backend (Phase 3) swaps it for redis\\nStreams behind the same facade method (``events``). Nothing else changes.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nfrom collections import OrderedDict\\nfrom collections.abc import AsyncIterator, Awaitable, Callable\\nfrom dataclasses import dataclass\\n\\n# Per-subscriber buffer cap. A slow client falling behind a fast producer drops\\n# the oldest live frame rather than growing without bound; the durable log is\\n# the source of truth for anything the client missed, reachable via reattach.\\n_SUBSCRIBER_MAXSIZE = 1000\\n\\n# Cap on the closed-marker map. ``close()`` records each finished job so a later\\n# direct reattach/subscribe to it terminates immediately instead of blocking on a\\n# live tail that will never produce. The map is evicted eagerly when a job's last\\n# subscriber drops; this LRU cap is the backstop for jobs that close and are\\n# never reattached, so a long-lived API process cannot leak one key per job\\n# without bound. The facade also gates terminal jobs on the persisted JobStatus,\\n# so an evicted marker never causes a missed/blocked production reattach.\\n_CLOSED_MARKER_MAXSIZE = 4096\\n\\n\\n@dataclass(frozen=True)\\nclass LiveFrame:\\n    \\\"\\\"\\\"One framed event on the live bus.\\n\\n    ``seq`` is the durable cursor used for ``Last-Event-ID``. For a durable\\n    milestone it is the row's ``job_events.seq``; for an ephemeral frame it is\\n    the seq of the most recent durable milestone (so ordering stays monotonic).\\n    ``data`` is the already-formatted SSE frame bytes.\\n\\n    ``durable`` says whether this frame has a ``job_events`` row of its own.\\n    Only durable frames can come back from a replay, so only they are\\n    seq-deduped on reattach; ephemeral frames share the preceding milestone's\\n    seq and would otherwise be mistaken for replays of it.\\n    \\\"\\\"\\\"\\n\\n    seq: int\\n    data: bytes\\n    durable: bool = True\\n\\n\\nReadDurable = Callable[[int], Awaitable[list[LiveFrame]]]\\n# True once the run will produce no more durable frames (terminal; +SUSPENDED in LE-1442).\\nIsDone = Callable[[], Awaitable[bool]]\\n\\n_DURABLE_POLL_INTERVAL_S = 0.5\\n\\n# Sentinel pushed into a subscriber queue to signal end-of-stream.\\n_CLOSED = object()\\n\\n\\nclass InMemoryLiveBus:\\n    def __init__(self) -> None:\\n        # job_id -> set of subscriber queues.\\n        self._subscribers: dict[str, set[asyncio.Queue]] = {}\\n        # job_id -> True once closed; late subscribers end immediately. Bounded\\n        # LRU (OrderedDict) so a long-lived process cannot leak one key per job;\\n        # see ``_mark_closed`` / ``_CLOSED_MARKER_MAXSIZE``.\\n        self._closed: OrderedDict[str, bool] = OrderedDict()\\n\\n    def _new_queue(self, job_id: str) -> asyncio.Queue:\\n        queue: asyncio.Queue = asyncio.Queue(maxsize=_SUBSCRIBER_MAXSIZE)\\n        self._subscribers.setdefault(job_id, set()).add(queue)\\n        return queue\\n\\n    def _drop_queue(self, job_id: str, queue: asyncio.Queue) -> None:\\n        subs = self._subscribers.get(job_id)\\n        if subs is not None:\\n            subs.discard(queue)\\n            if not subs:\\n                self._subscribers.pop(job_id, None)\\n\\n    async def publish(self, job_id: str, frame: LiveFrame) -> None:\\n        \\\"\\\"\\\"Push ``frame`` to every live subscriber for ``job_id``.\\\"\\\"\\\"\\n        for queue in list(self._subscribers.get(job_id, set())):\\n            if queue.full():\\n                with contextlib.suppress(asyncio.QueueEmpty):\\n                    queue.get_nowait()\\n            with contextlib.suppress(asyncio.QueueFull):\\n                queue.put_nowait(frame)\\n\\n    def _mark_closed(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Record a job as closed, bounding the map to an LRU of recent jobs.\\n\\n        Always recorded (even with no subscribers) so a later direct reattach to\\n        the finished job terminates instead of blocking on a tail that will never\\n        produce. The OrderedDict is the LRU: re-mark moves the key to the end, and\\n        the oldest entry is dropped once the cap is exceeded. Eviction of a very\\n        old marker is safe \u2014 the facade gates terminal jobs on the persisted\\n        JobStatus, so a production reattach never depends on this in-process flag.\\n        \\\"\\\"\\\"\\n        self._closed[job_id] = True\\n        self._closed.move_to_end(job_id)\\n        while len(self._closed) > _CLOSED_MARKER_MAXSIZE:\\n            self._closed.popitem(last=False)\\n\\n    async def close(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Mark the job's stream ended and wake every subscriber.\\\"\\\"\\\"\\n        self._mark_closed(job_id)\\n        for queue in list(self._subscribers.get(job_id, set())):\\n            with contextlib.suppress(asyncio.QueueFull):\\n                queue.put_nowait(_CLOSED)\\n\\n    def subscribe(self, job_id: str) -> AsyncIterator[LiveFrame]:\\n        \\\"\\\"\\\"Live-only subscription: frames published from now until close.\\n\\n        The subscriber queue is registered eagerly here (not inside the\\n        generator) so a frame published between ``subscribe(...)`` and the\\n        first ``__anext__`` is not lost \u2014 the queue already exists to catch it.\\n        \\\"\\\"\\\"\\n        if self._closed.get(job_id):\\n\\n            async def _empty() -> AsyncIterator[LiveFrame]:\\n                return\\n                yield  # pragma: no cover - makes this an async generator\\n\\n            return _empty()\\n\\n        queue = self._new_queue(job_id)\\n\\n        async def _gen() -> AsyncIterator[LiveFrame]:\\n            try:\\n                while True:\\n                    item = await queue.get()\\n                    if item is _CLOSED:\\n                        return\\n                    yield item\\n            finally:\\n                self._drop_queue(job_id, queue)\\n\\n        return _gen()\\n\\n    def reattach(\\n        self,\\n        job_id: str,\\n        last_seq: int,\\n        read_durable: ReadDurable,\\n        *,\\n        is_done: IsDone | None = None,\\n        poll_interval_s: float = _DURABLE_POLL_INTERVAL_S,\\n    ) -> AsyncIterator[LiveFrame]:\\n        \\\"\\\"\\\"Replay the durable log after ``last_seq``, then tail the live bus.\\n\\n        A subscriber queue is registered BEFORE the durable read so no live\\n        frame published during replay is lost. Frames whose seq was already\\n        replayed (or already <= last_seq) are skipped so the boundary emits\\n        each seq exactly once.\\n\\n        With ``is_done`` set, the tail also polls the durable log on idle so a\\n        reattach landing on a worker that is NOT running the job (its runner\\n        writes the durable log, not this process's bus) still advances gap-free\\n        and ends when ``is_done()`` reports the job reached a terminal state.\\n        \\\"\\\"\\\"\\n        # Register eagerly (not inside the generator) so frames published\\n        # between ``reattach(...)`` and the first ``__anext__`` are captured.\\n        queue = self._new_queue(job_id)\\n\\n        async def _gen() -> AsyncIterator[LiveFrame]:\\n            highest = last_seq\\n\\n            async def drain_durable(after: int) -> tuple[int, list[LiveFrame]]:\\n                fresh = [f for f in await read_durable(after) if f.seq > after]\\n                return (fresh[-1].seq if fresh else after), fresh\\n\\n            try:\\n                for frame in await read_durable(last_seq):\\n                    highest = max(highest, frame.seq)\\n                    yield frame\\n                # If the job closed before/while we replayed, drain nothing more.\\n                if self._closed.get(job_id) and queue.empty():\\n                    return\\n                while True:\\n                    if is_done is None:\\n                        item = await queue.get()\\n                    else:\\n                        try:\\n                            item = await asyncio.wait_for(queue.get(), timeout=poll_interval_s)\\n                        except asyncio.TimeoutError:\\n                            highest, fresh = await drain_durable(highest)\\n                            for frame in fresh:\\n                                yield frame\\n                            if await is_done():\\n                                highest, fresh = await drain_durable(highest)\\n                                for frame in fresh:\\n                                    yield frame\\n                                return\\n                            continue\\n                    if item is _CLOSED:\\n                        return\\n                    if item.durable:\\n                        if item.seq <= highest:\\n                            continue\\n                        highest = item.seq\\n                    yield item\\n            finally:\\n                self._drop_queue(job_id, queue)\\n\\n        return _gen()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/background_execution/runner.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"385429b24456f108a81b7581278405d87c44a8c23f9a1bf28fc6776b2d32d5a3\",\"content\":\"\\\"\\\"\\\"Drive a background workflow run through a StreamAdapter.\\n\\nThe runner consumes ``(frame_bytes, event_type)`` pairs from a frame source\\n(the v1 build-vertex loop wrapped by ``_stream_event_frames``), and for each:\\n\\n* durable frame   -> ``JobService.append_event`` (assigns a seq) + publish live\\n* ephemeral frame -> publish live only, tagged with the last durable seq\\n\\nBetween frames it polls the durable STOP signal at the vertex boundary and\\ncooperatively cancels. Terminal handling writes durable ``result``/``error``,\\ncloses the live bus, and routes the status transition through\\n``JobService.execute_with_status`` so TIMED_OUT / CANCELLED / FAILED mapping is\\nreused from the single source of truth.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nimport json\\nfrom collections.abc import AsyncIterator, Callable\\nfrom datetime import datetime, timedelta, timezone\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.workflow.adapters.langflow import WORKFLOW_OUTPUT_CAPTURE_EVENT\\n\\nfrom langflow.services.background_execution.live_bus import LiveFrame\\nfrom langflow.services.database.models.jobs.model import JobStatus, SignalType\\nfrom langflow.services.jobs.exceptions import HUMAN_INPUT_REQUIRED_EVENT, PauseRequested\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from lfx.workflow.adapters import StreamAdapter\\n\\n    from langflow.services.background_execution.live_bus import InMemoryLiveBus\\n    from langflow.services.jobs.service import JobService\\n\\n# A frame source yields (sse_frame_bytes, protocol_event_type) pairs.\\nFrameSource = Callable[..., AsyncIterator[tuple[bytes, str]]]\\n\\n# Receives the hydrated checkpoint (or None) + the human decision on resume.\\nResumeHook = Callable[[Any, Any], Any]\\n\\n__all__ = [\\\"HUMAN_INPUT_REQUIRED_EVENT\\\", \\\"FrameSource\\\", \\\"JobRunner\\\", \\\"ResumeHook\\\"]\\n\\n\\nasync def _passthrough_resume_hook(checkpoint: Any, decision: Any) -> None:  # noqa: ARG001\\n    return None\\n\\n\\nclass JobRunner:\\n    def __init__(\\n        self,\\n        *,\\n        job_service: JobService,\\n        live_bus: InMemoryLiveBus,\\n        adapter: StreamAdapter,\\n        frame_source: FrameSource,\\n        job_timeout: float | None = None,\\n        owner: str | None = None,\\n        heartbeat_interval_s: float = 15.0,\\n        resume_hook: ResumeHook | None = None,\\n        checkpoint_store: Any = None,\\n        input_deadline_s: float | None = None,\\n    ) -> None:\\n        self._jobs = job_service\\n        self._bus = live_bus\\n        self._adapter = adapter\\n        self._frame_source = frame_source\\n        # Producer (LE-1447/1449) supplies the real decision fold-back; default no-op.\\n        self._resume_hook = resume_hook or _passthrough_resume_hook\\n        self._checkpoint_store = checkpoint_store\\n        # When set, the whole run is bounded by this wall-clock budget; an overrun\\n        # surfaces as asyncio.TimeoutError, which execute_with_status maps to\\n        # TIMED_OUT. None means unbounded (the prior behaviour).\\n        self._job_timeout = job_timeout\\n        # Human-latency budget for a SUSPENDED run, independent of _job_timeout. When set,\\n        # the suspend path stamps a deadline the sweep enforces; None disables it (LE-1452).\\n        self._input_deadline_s = input_deadline_s\\n        # Liveness: while a run is in flight, a background task refreshes the\\n        # job-row heartbeat so a reconciler can tell this live run from a\\n        # genuinely orphaned one. ``owner`` is a process-unique token; when None\\n        # (scripted tests that don't care about liveness) the heartbeat is off.\\n        self._owner = owner\\n        self._heartbeat_interval_s = max(heartbeat_interval_s, 0.1)\\n\\n    async def run(self, *, job_id: UUID, source_kwargs: dict[str, Any]) -> None:\\n        \\\"\\\"\\\"Execute one background job to a terminal state.\\\"\\\"\\\"\\n\\n        async def _wrapped() -> None:\\n            # Per-pass clock: paused time never accrues here (resume re-enqueues a fresh\\n            # run). The suspend-window budget is the separate input deadline (LE-1452).\\n            if self._job_timeout is not None:\\n                await asyncio.wait_for(\\n                    self._drive(job_id=job_id, source_kwargs=source_kwargs),\\n                    timeout=self._job_timeout,\\n                )\\n            else:\\n                await self._drive(job_id=job_id, source_kwargs=source_kwargs)\\n\\n        heartbeat_task = self._start_heartbeat(job_id)\\n        paused = False\\n        try:\\n            await self._jobs.execute_with_status(job_id, _wrapped)\\n        except PauseRequested as exc:\\n            # Stop the heartbeat BEFORE stamping suspend metadata: both are whole-blob\\n            # read-modify-writes, so a beat racing the stamp would clobber the request id.\\n            await self._stop_heartbeat(heartbeat_task)\\n            heartbeat_task = None\\n            try:\\n                await self._suspend(job_id, exc)\\n            except Exception as suspend_exc:  # noqa: BLE001\\n                # Why: a failed suspend must not leave the job paused-but-broken with an open bus and a\\n                # hanging client; mark FAILED and leave paused=False so the finally closes the bus.\\n                await logger.aerror(f\\\"Background job {job_id} failed to suspend: {suspend_exc}\\\", exc_info=True)\\n                with contextlib.suppress(Exception):\\n                    await self._jobs.update_job_status(job_id, JobStatus.FAILED, finished_timestamp=True)\\n                with contextlib.suppress(Exception):\\n                    await self._jobs.set_error(\\n                        job_id,\\n                        {\\\"type\\\": \\\"suspend_failed\\\", \\\"detail\\\": \\\"Workflow suspension failed.\\\"},\\n                    )\\n            else:\\n                paused = True\\n                await logger.adebug(f\\\"Background job {job_id} suspended for human input\\\")\\n        except asyncio.CancelledError as exc:\\n            user_tagged = bool(exc.args) and exc.args[0] == \\\"LANGFLOW_USER_CANCELLED\\\"\\n            if not user_tagged and not await self._stop_requested(job_id):\\n                raise\\n            await logger.adebug(f\\\"Background job {job_id} stopped\\\")\\n        except Exception as exc:  # noqa: BLE001\\n            await logger.aerror(f\\\"Background job {job_id} runner error: {exc}\\\", exc_info=True)\\n        finally:\\n            await self._stop_heartbeat(heartbeat_task)\\n            if not paused:  # a suspended run is resumable: keep the bus open, skip terminal reconcile\\n                with contextlib.suppress(Exception):\\n                    if await asyncio.shield(self._reconcile_stop(job_id)):\\n                        await logger.adebug(f\\\"Background job {job_id} reconciled to CANCELLED after a racing stop\\\")\\n                with contextlib.suppress(Exception):\\n                    await asyncio.shield(self._finalize_terminal_event(job_id))\\n                await self._bus.close(str(job_id))\\n\\n    async def _suspend(self, job_id: UUID, exc: PauseRequested) -> None:\\n        \\\"\\\"\\\"Suspend mechanics: durable pause event + SUSPENDED status, no finalization.\\n\\n        Records the pending request id so resume (LE-1446) can enforce single use.\\n        Deliberately does NOT call ``set_result``/``set_error``, the terminal-event\\n        finalizer, or close the live bus \u2014 the run is resumable.\\n        \\\"\\\"\\\"\\n        await self._jobs.append_event(job_id, HUMAN_INPUT_REQUIRED_EVENT, exc.payload)\\n        metadata: dict[str, Any] = {}\\n        if exc.request_id is not None:\\n            metadata[\\\"pending_request_id\\\"] = exc.request_id\\n        if self._input_deadline_s is not None:\\n            deadline = datetime.now(timezone.utc) + timedelta(seconds=self._input_deadline_s)\\n            metadata[\\\"input_deadline_at\\\"] = deadline.isoformat()\\n        if exc.output_events:\\n            # Durable stash of the pre-pause terminal outputs so the resumed pass can\\n            # pre-seed its capture list. Deduped so a resume-pause-resume cycle does\\n            # not accumulate duplicates (the pre-seed already folds the prior stash in).\\n            metadata[\\\"pre_pause_outputs\\\"] = self._dedup_outputs(exc.output_events)\\n        # Publish SUSPENDED only when the resume guard and pre-pause captures are\\n        # visible in the same committed row. Otherwise a racing resume can claim\\n        # the job between separate status and metadata transactions.\\n        await self._jobs.suspend_job(job_id, metadata)\\n\\n    async def _finalize_terminal_event(self, job_id: UUID) -> None:\\n        \\\"\\\"\\\"Backfill the error blob + terminal event for TIMED_OUT / CANCELLED.\\n\\n        ``execute_with_status`` writes the TIMED_OUT/CANCELLED status but no\\n        durable error blob or terminal ``job_events`` row, so a consumer keying\\n        on a terminal event TYPE (not just stream close) would not find one. This\\n        appends ``run_timed_out`` / ``run_cancelled`` and, for a CANCELLED row\\n        that a racing completion left with a populated ``result``, clears the\\n        result and sets ``error={type: cancelled}`` so the terminal state is\\n        internally consistent (no CANCELLED row carrying a completed-run result).\\n        \\\"\\\"\\\"\\n        job = await self._jobs.get_job_by_job_id(job_id)\\n        if job is None:\\n            return\\n        if job.status == JobStatus.TIMED_OUT:\\n            if job.error is None:\\n                await self._jobs.set_error(job_id, {\\\"type\\\": \\\"timed_out\\\"})\\n            await self._jobs.append_event(job_id, \\\"run_timed_out\\\", {\\\"type\\\": \\\"timed_out\\\"})\\n        elif job.status == JobStatus.CANCELLED:\\n            # A late stop that won over a genuine completion may have left a\\n            # completed-run result behind \u2014 overwrite it so the row is consistent.\\n            if job.result is not None:\\n                await self._jobs.set_result(job_id, None)\\n            if job.error is None:\\n                await self._jobs.set_error(job_id, {\\\"type\\\": \\\"cancelled\\\"})\\n            await self._jobs.append_event(job_id, \\\"run_cancelled\\\", {\\\"type\\\": \\\"cancelled\\\"})\\n\\n    def _start_heartbeat(self, job_id: UUID) -> asyncio.Task | None:\\n        \\\"\\\"\\\"Spawn the periodic heartbeat task for a run (None when owner unset).\\n\\n        The task writes the owner + a fresh timestamp immediately, then refreshes\\n        on the interval until cancelled in ``run``'s finally. A heartbeat write\\n        failure is swallowed so a transient DB hiccup never kills the run.\\n        \\\"\\\"\\\"\\n        if self._owner is None:\\n            return None\\n\\n        async def _beat() -> None:\\n            while True:\\n                with contextlib.suppress(Exception):\\n                    await self._jobs.heartbeat(job_id, self._owner)\\n                await asyncio.sleep(self._heartbeat_interval_s)\\n\\n        return asyncio.create_task(_beat())\\n\\n    @staticmethod\\n    async def _stop_heartbeat(task: asyncio.Task | None) -> None:\\n        if task is None:\\n            return\\n        task.cancel()\\n        with contextlib.suppress(asyncio.CancelledError, Exception):\\n            await task\\n\\n    async def _reconcile_stop(self, job_id: UUID) -> bool:\\n        \\\"\\\"\\\"Force CANCELLED when a STOP signal exists. Returns True if it acted.\\n\\n        Also stamps the STOP signal ``consumed_at`` so it does not linger: an\\n        unconsumed STOP would grow the signals table and make a later re-enqueued\\n        run of the same job self-cancel off the stale signal. This runs in the\\n        runner's ``finally`` (shielded), so it is the single point where a stop is\\n        finalized \u2014 the right place to mark it consumed.\\n        \\\"\\\"\\\"\\n        if not await self._stop_requested(job_id):\\n            return False\\n        await self._jobs.update_job_status(job_id, JobStatus.CANCELLED, finished_timestamp=True)\\n        await self._jobs.consume_signals(job_id, SignalType.STOP)\\n        return True\\n\\n    async def _drive(self, *, job_id: UUID, source_kwargs: dict[str, Any]) -> None:\\n        \\\"\\\"\\\"The wrapped coroutine: stream frames, persist, publish, finalize result/error.\\\"\\\"\\\"\\n        resume = await self._maybe_resume(job_id)\\n        if resume is not None:\\n            source_kwargs = {**source_kwargs, \\\"resume\\\": resume}\\n        last_durable_seq = 0\\n        errored_payload: dict[str, Any] | None = None\\n        # Terminal outputs the run produced, captured so GET status can return\\n        # the result without forcing a /events re-attach. The frame source emits\\n        # a protocol-neutral off-wire capture for both langflow and AG-UI. The\\n        # public langflow ``output`` event is also accepted as a fallback for\\n        # injected/exported FrameSource implementations that do not emit the\\n        # private capture; final deduplication keeps the two paths from doubling.\\n        #\\n        # A resumed run starts a FRESH frame stream and the output loop skips\\n        # re-emitting checkpoint-restored vertices, so any terminal output the\\n        # pre-pause pass produced would be lost. Pre-seed from the stash _suspend\\n        # wrote to job_metadata; _dedup_outputs lets a re-emitted vertex overwrite\\n        # its stale entry at finalize (resumed pass wins).\\n        output_events: list[dict[str, Any]] = await self._load_pre_pause_outputs(job_id) if resume is not None else []\\n        async for frame_bytes, event_type in self._frame_source(**source_kwargs):\\n            if event_type == WORKFLOW_OUTPUT_CAPTURE_EVENT:\\n                # Off-wire terminal-output capture (both protocols): record it into\\n                # the in-memory result ONLY. Deliberately no ``append_event`` (never\\n                # in ``job_events``) and no ``publish`` (never on the live bus), so the\\n                # wire is unchanged and both protocols populate ``Job.result``.\\n                payload = self._decode_payload(frame_bytes)\\n                output_data = payload.get(\\\"data\\\")\\n                if isinstance(output_data, dict):\\n                    output_events.append(output_data)\\n                continue\\n            if event_type == HUMAN_INPUT_REQUIRED_EVENT:\\n                from langflow.services.jobs.service import _unwrap_pause_payload\\n\\n                payload = self._decode_payload(frame_bytes)\\n                request = _unwrap_pause_payload(payload) or {}\\n                # Carry the pre-pause captures out with the exception so _suspend can\\n                # stash them; without this the resumed pass starts empty and the final\\n                # result drops every terminal output produced before the pause.\\n                raise PauseRequested(\\n                    payload=payload,\\n                    request_id=request.get(\\\"request_id\\\"),\\n                    output_events=output_events,\\n                )\\n            if self._adapter.is_durable(event_type):\\n                # Vertex/milestone-boundary cooperative cancel: a STOP written to\\n                # the durable signal table flips the job at the next durable\\n                # frame. Poll only here (not on every ephemeral token): a stop is\\n                # honored at boundaries anyway, so a per-token DB read is wasted\\n                # work that scales with the token stream.\\n                if await self._stop_requested(job_id):\\n                    raise self._user_cancelled()\\n                payload = self._decode_payload(frame_bytes)\\n                seq = await self._jobs.append_event(job_id, event_type, payload)\\n                last_durable_seq = seq\\n                await self._bus.publish(str(job_id), LiveFrame(seq=seq, data=self._restamp_id(frame_bytes, seq)))\\n                if event_type == \\\"output\\\":\\n                    # Fallback for custom frame sources that emit the standard\\n                    # adapter event but not WORKFLOW_OUTPUT_CAPTURE_EVENT.\\n                    output_data = payload.get(\\\"data\\\")\\n                    if isinstance(output_data, dict):\\n                        output_events.append(output_data)\\n                if event_type == self._adapter.terminal_error_type:\\n                    errored_payload = payload\\n            else:\\n                await self._bus.publish(\\n                    str(job_id),\\n                    LiveFrame(\\n                        seq=last_durable_seq,\\n                        data=self._restamp_id(frame_bytes, last_durable_seq),\\n                        durable=False,\\n                    ),\\n                )\\n\\n        # Final cooperative-stop check: a STOP that lands after the last frame\\n        # (or while a fast flow was finishing) must still win over a clean\\n        # completion, so a user's stop intent is never silently overwritten with\\n        # COMPLETED. Mirrors the old _finalize_job_status \\\"never overwrite\\n        # CANCELLED\\\" guard.\\n        if await self._stop_requested(job_id):\\n            raise self._user_cancelled()\\n\\n        if errored_payload is not None:\\n            await self._jobs.set_error(job_id, errored_payload.get(\\\"data\\\", errored_payload))\\n            # Surface as a failure so execute_with_status writes FAILED.\\n            msg = \\\"Background job emitted a terminal error event\\\"\\n            raise RuntimeError(msg)\\n        await self._jobs.set_result(job_id, {\\\"status\\\": \\\"completed\\\", \\\"outputs\\\": self._dedup_outputs(output_events)})\\n\\n    async def _load_pre_pause_outputs(self, job_id: UUID) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"Return terminal outputs a prior suspend stashed in job_metadata, or [].\\n\\n        Read once at the top of a resumed ``_drive`` to seed the capture list so\\n        outputs produced before the pause survive into the completed-run result.\\n        \\\"\\\"\\\"\\n        job = await self._jobs.get_job_by_job_id(job_id)\\n        prior = (job.job_metadata or {}).get(\\\"pre_pause_outputs\\\") if job else None\\n        if isinstance(prior, list):\\n            return [event for event in prior if isinstance(event, dict)]\\n        return []\\n\\n    @staticmethod\\n    def _dedup_outputs(events: list[dict[str, Any]]) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"Merge pre-pause and resumed-pass captures keyed by ``component_id``.\\n\\n        A resumed run re-emits the branch vertices it had to rebuild, so one\\n        ``component_id`` can appear both in the pre-seeded pre-pause outputs and in\\n        the fresh captures. Keep each component's FIRST position (pre-pause outputs\\n        stay ahead of ones produced after resume) but its LATEST value (the resumed\\n        pass wins for anything it re-emitted). Events without a ``component_id`` are\\n        passed through untouched, in order.\\n        \\\"\\\"\\\"\\n        index: dict[str, int] = {}\\n        merged: list[dict[str, Any]] = []\\n        for event in events:\\n            cid = event.get(\\\"component_id\\\")\\n            if cid is not None and cid in index:\\n                merged[index[cid]] = event\\n                continue\\n            if cid is not None:\\n                index[cid] = len(merged)\\n            merged.append(event)\\n        return merged\\n\\n    async def _maybe_resume(self, job_id: UUID) -> dict[str, Any] | None:\\n        data = await self._pending_resume(job_id)\\n        if data is None:\\n            return None\\n        checkpoint = await self._load_checkpoint(job_id)\\n        await self._resume_hook(checkpoint, data.get(\\\"decision\\\"))\\n        await self._jobs.consume_signals(job_id, SignalType.RESUME)\\n        return {\\\"request_id\\\": data.get(\\\"request_id\\\"), \\\"decision\\\": data.get(\\\"decision\\\")}\\n\\n    async def _pending_resume(self, job_id: UUID) -> dict[str, Any] | None:\\n        for signal in await self._jobs.unconsumed_signals(job_id):\\n            if signal.signal_type == SignalType.RESUME:\\n                return signal.data or {}\\n        return None\\n\\n    async def _load_checkpoint(self, job_id: UUID) -> Any:\\n        store = self._checkpoint_store\\n        if store is None:\\n            from lfx.services.deps import get_checkpoint_service\\n\\n            store = get_checkpoint_service()\\n        return await store.load_by_run_id(str(job_id))\\n\\n    async def _stop_requested(self, job_id: UUID) -> bool:\\n        signals = await self._jobs.unconsumed_signals(job_id)\\n        return any(s.signal_type == SignalType.STOP for s in signals)\\n\\n    @staticmethod\\n    def _user_cancelled() -> asyncio.CancelledError:\\n        exc = asyncio.CancelledError()\\n        exc.args = (\\\"LANGFLOW_USER_CANCELLED\\\",)\\n        return exc\\n\\n    @staticmethod\\n    def _restamp_id(frame_bytes: bytes, seq: int) -> bytes:\\n        r\\\"\\\"\\\"Rewrite the SSE ``id:`` line so the live id == the durable ``seq``.\\n\\n        The frame source (``_stream_event_frames``) bakes its OWN per-frame stream\\n        counter into ``id:`` \u2014 counting ephemeral tokens and initial frames too \u2014\\n        so those ids live in a DIFFERENT namespace than ``job_events.seq``. A\\n        client's ``Last-Event-ID`` (a live id) is later fed to\\n        ``read_events(after_seq=...)`` (a durable seq), so the two MUST share one\\n        namespace or a reattach gaps/duplicates milestones. We re-stamp every live\\n        frame's id with its durable cursor (the row seq for a milestone, the last\\n        milestone's seq for an ephemeral token) so live ids and durable replay ids\\n        are one cursor. ``_row_to_frame`` already stamps replayed rows with\\n        ``id=row.seq``, so live and replay now agree byte-for-byte on the id line.\\n\\n        Bare-JSON frames (scripted tests, no ``id:`` line) get one appended; a\\n        frame that already carries an ``id:`` line has it replaced.\\n        \\\"\\\"\\\"\\n        from fastapi.sse import format_sse_event\\n\\n        text = frame_bytes.decode(\\\"utf-8\\\", errors=\\\"replace\\\")\\n        data_str: str | None = None\\n        for line in text.splitlines():\\n            if line.startswith(\\\"data:\\\"):\\n                data_str = line[len(\\\"data:\\\") :].strip()\\n                break\\n        if data_str is None:\\n            # Not SSE-framed (bare JSON from scripted tests): frame it now with id.\\n            data_str = text.strip()\\n        return format_sse_event(data_str=data_str, id=str(seq))\\n\\n    @staticmethod\\n    def _decode_payload(frame_bytes: bytes) -> dict[str, Any]:\\n        r\\\"\\\"\\\"Extract the durable JSON payload from a frame.\\n\\n        The frame may be either a plain JSON object (scripted tests) or a real\\n        SSE-framed body from ``_stream_event_frames`` shaped like\\n        ``b\\\"data: {...}\\\\nid: 3\\\\n\\\\n\\\"``. We pull the ``data:`` line's JSON when\\n        present, else parse the whole frame as JSON. On the off chance a frame\\n        is neither, persist a string fallback rather than crash the run.\\n        \\\"\\\"\\\"\\n        text = frame_bytes.decode(\\\"utf-8\\\", errors=\\\"replace\\\")\\n        data_str = text\\n        if \\\"data:\\\" in text:\\n            for line in text.splitlines():\\n                if line.startswith(\\\"data:\\\"):\\n                    data_str = line[len(\\\"data:\\\") :].strip()\\n                    break\\n        try:\\n            return json.loads(data_str)\\n        except (ValueError, TypeError):\\n            return {\\\"raw\\\": text}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/background_execution/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d5b7f497b6573f893e37958ddf25f7a1291d7200e5f551a9203addb2f5f6f547\",\"content\":\"\\\"\\\"\\\"BackgroundExecutionService: the facade over the background-run primitives.\\n\\nComposes the existing durable store (``JobService``) with the in-process\\nexecutor, the in-memory live bus, and the per-job runner. Methods:\\n\\n* ``submit(flow_id, request, user) -> job_id``\\n* ``events(job_id, last_event_id, user) -> AsyncIterator[bytes]``\\n* ``status(job_id, user)`` / ``result(job_id, user)``\\n* ``stop_job(job_id, user)``\\n\\nThis single-node slice always runs jobs on the in-process executor + in-memory\\nbus implemented here. ``LANGFLOW_JOB_QUEUE_TYPE=redis`` still selects the v1\\n``RedisJobQueueService`` elsewhere; this facade has no scaled backend on this\\nbranch and runs in-process regardless.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nimport json\\nimport math\\nimport os\\nimport tempfile\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING, Any\\nfrom uuid import uuid4\\n\\nfrom filelock import FileLock, Timeout\\nfrom lfx.log.logger import logger\\n\\nfrom langflow.services.background_execution.executor import InProcessExecutor\\nfrom langflow.services.background_execution.live_bus import InMemoryLiveBus, LiveFrame\\nfrom langflow.services.background_execution.runner import JobRunner\\nfrom langflow.services.base import Service\\nfrom langflow.services.database.models.jobs.model import JobStatus, JobType, SignalType\\nfrom langflow.services.deps import get_job_service\\nfrom langflow.services.jobs.exceptions import DuplicateJobError\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncIterator, Callable\\n    from uuid import UUID\\n\\n    from lfx.services.settings.service import SettingsService\\n\\n    from langflow.services.database.models.jobs.model import Job, JobEvent\\n    from langflow.services.database.models.user.model import UserRead\\n\\n    # A frame-source factory returns the async-generator callable the runner drives.\\n    # Default wiring (Task 2.7) returns ``_stream_event_frames`` bound to the run's\\n    # adapter + flow; tests inject a scripted generator.\\n    #\\n    # Defined under TYPE_CHECKING on purpose: as a module-level runtime value,\\n    # ``Callable[..., Any]`` is a GenericAlias that passes ``isinstance(obj, type)``\\n    # but makes ``issubclass(obj, Service)`` raise on Python 3.10/3.14. The service\\n    # factory scans this module for ``Service`` subclasses (services/factory.py), so a\\n    # runtime alias here crashes service initialization on those interpreters.\\n    FrameSourceFactory = Callable[..., Any]\\n\\n# Durable statuses that mean the run is over. ``events()`` keys off these (not the\\n# process-local live bus) so a reattach to a finished job replays and returns\\n# instead of tailing a bus that will never produce another frame.\\n_TERMINAL_STATUSES = frozenset({JobStatus.COMPLETED, JobStatus.FAILED, JobStatus.CANCELLED, JobStatus.TIMED_OUT})\\n_REQUEST_OVERRIDES_FORMAT_KEY = \\\"request_overrides_format\\\"\\n_REQUEST_OVERRIDES_KEY = \\\"request_overrides\\\"\\n_REQUEST_OVERRIDES_FORMAT = \\\"fernet-json-v1\\\"\\n_REQUEST_OVERRIDES_VERSION = 1\\n_REQUEST_OVERRIDE_FIELDS = frozenset({\\\"globals\\\", \\\"tweaks\\\"})\\n_REQUEST_OVERRIDES_CONTAINER_FIELD = \\\"overrides\\\"\\n_REQUEST_OVERRIDES_ERROR = {\\\"type\\\": \\\"request_overrides_unavailable\\\"}\\n_MAX_OVERRIDE_JSON_DEPTH = 64\\n_MAX_OVERRIDE_INTEGER_BITS = 14_000\\n\\n\\nclass RequestOverridesUnavailableError(RuntimeError):\\n    \\\"\\\"\\\"Retryable signal for request overrides blocked by unavailable cryptographic state.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        super().__init__(\\\"Background request overrides are unavailable.\\\")\\n\\n\\nclass RequestOverridesCorruptedError(RequestOverridesUnavailableError):\\n    \\\"\\\"\\\"Fail-closed signal for an authenticated or structurally malformed persisted envelope.\\\"\\\"\\\"\\n\\n\\nclass InvalidRequestOverridesError(ValueError):\\n    \\\"\\\"\\\"Caller-supplied request overrides do not match the supported JSON grammar.\\\"\\\"\\\"\\n\\n    def __init__(self, field: str) -> None:\\n        self.field = field\\n        super().__init__(f\\\"Invalid request override field: {field}\\\")\\n\\n\\nclass BackgroundExecutionService(Service):\\n    name = \\\"background_execution_service\\\"\\n\\n    def __init__(\\n        self,\\n        settings_service: SettingsService,\\n        *,\\n        frame_source_factory: FrameSourceFactory | None = None,\\n        backend: Any | None = None,\\n    ) -> None:\\n        self.settings_service = settings_service\\n        self._settings = settings_service.settings\\n        self._is_redis = self._settings.background_backend_is_scaled\\n        # Scaled backend: the redis claim queue + Streams live bus + DB replay.\\n        # Injected in tests; otherwise built lazily from settings. In the default\\n        # (asyncio) path it stays None and the in-process executor runs jobs here.\\n        if backend is None and self._is_redis:\\n            backend = self._build_scaled_backend()\\n        self._backend = backend\\n        self._executor = InProcessExecutor(max_concurrency=self._settings.background_max_concurrency)\\n        self._bus = InMemoryLiveBus()\\n        # Process-unique owner token stamped on the heartbeat of jobs this API\\n        # process runs. Lets a liveness-aware sweep tell a job this live process\\n        # is running from a genuinely orphaned one.\\n        self._owner = f\\\"api:{os.getpid()}:{uuid4().hex[:8]}\\\"\\n        self._frame_source_factory = frame_source_factory\\n        self._deadline_task: asyncio.Task | None = None\\n        self._orphan_task: asyncio.Task | None = None\\n        self.set_ready()\\n\\n    @property\\n    def _scaled(self) -> bool:\\n        \\\"\\\"\\\"True when a redis-backed scaled backend is wired behind this facade.\\\"\\\"\\\"\\n        return self._backend is not None\\n\\n    def _build_scaled_backend(self) -> Any:\\n        \\\"\\\"\\\"Build the redis-backed scaled backend from settings.\\n\\n        Reuses the worker's redis-client resolution (URL -> host/port/db with the\\n        cache-redis fallbacks) so the API enqueues to the exact redis a worker\\n        drains, and ``select_background_backend`` so selection follows\\n        ``background_backend_is_scaled``. Returns None in the default path.\\n        \\\"\\\"\\\"\\n        try:\\n            from langflow.services.background_execution.factory import select_background_backend\\n            from langflow.services.background_execution.worker import _build_redis_client\\n        except ImportError:\\n            # The scaled modules (worker/redis_backend) are not shipped on this branch;\\n            # degrade to the in-process executor instead of crashing the facade.\\n            logger.warning(\\n                \\\"job_queue_type=redis requested but the scaled background backend is not \\\"\\n                \\\"available; falling back to the in-process executor.\\\"\\n            )\\n            return None\\n        from langflow.services.deps import get_job_service\\n\\n        client = _build_redis_client(self._settings)\\n        return select_background_backend(self._settings, client=client, job_service=get_job_service())\\n\\n    async def start(self) -> None:\\n        # Scaled mode: the external worker owns execution and its watchdogs.\\n        if self._scaled:\\n            return\\n        await self._executor.start()\\n        self._start_deadline_watchdog()\\n        self._start_orphan_watchdog()\\n\\n    async def stop(self) -> None:\\n        watchdogs = [task for task in (self._deadline_task, self._orphan_task) if task is not None]\\n        for task in watchdogs:\\n            task.cancel()\\n        self._deadline_task = None\\n        self._orphan_task = None\\n        if watchdogs:\\n            await asyncio.gather(*watchdogs, return_exceptions=True)\\n        await self._executor.stop()\\n\\n    def _start_deadline_watchdog(self) -> None:\\n        \\\"\\\"\\\"Run the input-deadline sweep on the watchdog interval (only when the budget is set).\\n\\n        Without this, a never-restarting process would enforce the deadline only on the\\n        startup sweep. The loop is skipped entirely when ``background_input_deadline_s`` is\\n        None, so default deployments spawn no extra task.\\n        \\\"\\\"\\\"\\n        if self._settings.background_input_deadline_s is None or self._deadline_task is not None:\\n            return\\n        interval = self._settings.background_watchdog_interval_s\\n\\n        async def _loop() -> None:\\n            while True:\\n                await asyncio.sleep(interval)\\n                with contextlib.suppress(Exception):\\n                    await self.sweep_input_deadlines()\\n\\n        self._deadline_task = asyncio.create_task(_loop())\\n\\n    def _start_orphan_watchdog(self) -> None:\\n        \\\"\\\"\\\"Periodically reconcile dead owners when Redis mode fell back in-process.\\n\\n        The release branch intentionally omits the scaled worker modules. Redis\\n        queue configuration therefore falls back to the in-process executor, but\\n        still sets ``_is_redis``. The startup path historically returned early in\\n        that state, leaving a dead replica's IN_PROGRESS rows stranded forever.\\n        Keep the fallback fleet self-healing without competing with a real scaled\\n        backend, whose worker owns its own retry-aware watchdog.\\n        \\\"\\\"\\\"\\n        if not self._is_redis or self._scaled or self._orphan_task is not None:\\n            return\\n        interval = self._settings.background_watchdog_interval_s\\n        lease_ttl = self._settings.background_lease_ttl_s\\n\\n        async def _loop() -> None:\\n            while True:\\n                await asyncio.sleep(interval)\\n                try:\\n                    await get_job_service().sweep_orphans(lease_ttl_s=lease_ttl)\\n                except asyncio.CancelledError:\\n                    raise\\n                except Exception:  # noqa: BLE001 -- a later watchdog tick must still run\\n                    await logger.aexception(\\\"Periodic background orphan sweep failed\\\")\\n\\n        self._orphan_task = asyncio.create_task(_loop())\\n\\n    async def teardown(self) -> None:\\n        await self.stop()\\n        # Scaled mode: close the redis client this facade built so the API replica\\n        # does not leak its connection pool on shutdown. No-op in default mode.\\n        backend = self._backend\\n        if backend is not None and hasattr(backend, \\\"teardown\\\"):\\n            await backend.teardown()\\n\\n    # ------------------------------------------------------------------ submit\\n\\n    @staticmethod\\n    def _effective_session(job: Job) -> str:\\n        \\\"\\\"\\\"The session/thread a job ran under, normalized the way the runner normalizes it.\\n\\n        ``submit`` persists the submit request under ``job_metadata['request']`` and the\\n        runner threads ``request['session_id'] or str(flow_id)`` into the stream adapter\\n        (``_build_adapter``), so the same fallback keys the supersede scope. Legacy rows\\n        written before the request was persisted keep a flat ``job_metadata['session_id']``\\n        \u2014 read it the way ``_reconstruct_request`` does rather than mis-scoping them.\\n        \\\"\\\"\\\"\\n        meta = job.job_metadata or {}\\n        persisted = meta.get(\\\"request\\\")\\n        source = persisted if isinstance(persisted, dict) and persisted else meta\\n        return source.get(\\\"session_id\\\") or str(job.flow_id)\\n\\n    async def supersede_suspended_runs(\\n        self, *, flow_id: UUID, user_id: UUID, session_id: str | None = None\\n    ) -> list[UUID]:\\n        \\\"\\\"\\\"Cancel this user's SUSPENDED runs of the flow so a rerun replaces the stale pause.\\n\\n        A suspended run holds a pause nobody will answer once its owner reruns that\\n        conversation; left alive it piles up in every pending surface (badge, cards, trace\\n        bar). Scope is flow + user + effective session (``session_id``, falling back to the\\n        flow id \u2014 the runner's own normalization): a rerun replaces the stale pause of the\\n        SAME session/thread, while SUSPENDED runs of OTHER sessions stay untouched so one\\n        flow can serve many independent callers (#14599). Another user's pause on the same\\n        flow is never touched, and running jobs are untouched so parallel runs stay\\n        supported.\\n        \\\"\\\"\\\"\\n        from sqlmodel import select\\n\\n        from langflow.services.database.models.jobs.model import Job\\n        from langflow.services.deps import session_scope\\n\\n        effective_session = session_id or str(flow_id)\\n        job_service = get_job_service()\\n        async with session_scope() as session:\\n            result = await session.exec(\\n                select(Job).where(\\n                    Job.flow_id == flow_id,\\n                    Job.user_id == user_id,\\n                    Job.status == JobStatus.SUSPENDED,\\n                    Job.type == JobType.WORKFLOW,\\n                )\\n            )\\n            # The session lives in job_metadata, so narrow to matching rows INSIDE the\\n            # scope: reading a JSON column off a row already detached from its session\\n            # would depend on the engine's expire_on_commit setting.\\n            stale_job_ids = [job.job_id for job in result.all() if self._effective_session(job) == effective_session]\\n        cancelled: list[UUID] = []\\n        for stale_job_id in stale_job_ids:\\n            if self._scaled:\\n                await self._backend.stop(str(stale_job_id))\\n                cancelled.append(stale_job_id)\\n            elif await self._cancel_suspended(stale_job_id, job_service):\\n                cancelled.append(stale_job_id)\\n        return cancelled\\n\\n    async def submit(self, *, flow_id: UUID, request: dict[str, Any], user: UserRead) -> UUID:\\n        # Lazy-start the executor so the facade works whether or not the app\\n        # lifespan called start() first. start() is idempotent.\\n        await self.start()\\n        job_service = get_job_service()\\n        job_id = uuid4()\\n        dedupe_key = request.get(\\\"idempotency_key\\\")\\n        # Construct and encrypt the durable payload BEFORE creating the row. The\\n        # QUEUED insert then commits the marker, plaintext-safe request, and\\n        # authenticated override envelope together; no worker can claim a row in\\n        # the old create-then-patch gap.\\n        initial_metadata = self._persisted_request_metadata(job_id=job_id, flow_id=flow_id, request=request)\\n        try:\\n            await job_service.create_job(\\n                job_id=job_id,\\n                flow_id=flow_id,\\n                user_id=user.id,\\n                dedupe_key=dedupe_key,\\n                # Serving end user (if any) rides the persisted request; record it so\\n                # status/stop/resume isolate on it. user_id stays the SID so the worker's\\n                # _user_stub(job.user_id) still fetches the SID-owned flow on re-enqueue.\\n                end_user_id=request.get(\\\"end_user_id\\\"),\\n                initial_metadata=initial_metadata,\\n            )\\n        except DuplicateJobError:\\n            # Idempotent retry: a non-terminal job already exists for this key,\\n            # so return that job_id instead of queuing duplicate work. Falls\\n            # through to a fresh submit only if the existing row vanished in the\\n            # race between create_job's check and this lookup.\\n            existing = await self._existing_job_for_dedupe(dedupe_key, user.id)\\n            if existing is not None:\\n                return existing\\n            raise\\n        # After create_job so an idempotent retry returns the existing job instead of\\n        # cancelling it; the new job is QUEUED, so the suspended-only query skips it.\\n        await self.supersede_suspended_runs(flow_id=flow_id, user_id=user.id, session_id=request.get(\\\"session_id\\\"))\\n        if self._scaled:\\n            # Scaled mode: hand the QUEUED job id to a worker via the redis claim\\n            # queue; the worker hydrates the request from the job row.\\n            await self._backend.enqueue(str(job_id))\\n        else:\\n            await self._enqueue(job_id=job_id, flow_id=flow_id, request=request, user=user)\\n        return job_id\\n\\n    @staticmethod\\n    def _redact_request(request: dict[str, Any]) -> dict[str, Any]:\\n        \\\"\\\"\\\"Return a copy of ``request`` with secret-bearing overrides removed.\\n\\n        Returns a shallow copy so the caller's dict (used for the live run) is not\\n        mutated. ``globals`` and ``tweaks`` are dropped from this plaintext blob;\\n        an authenticated encrypted envelope carries them for durable replay.\\n        \\\"\\\"\\\"\\n        if \\\"globals\\\" not in request and \\\"tweaks\\\" not in request:\\n            return request\\n        redacted = dict(request)\\n        redacted.pop(\\\"globals\\\", None)\\n        redacted.pop(\\\"tweaks\\\", None)\\n        return redacted\\n\\n    @classmethod\\n    def _validate_json_value(\\n        cls,\\n        value: Any,\\n        *,\\n        field: str,\\n        seen: set[int] | None = None,\\n        depth: int = 0,\\n    ) -> None:\\n        \\\"\\\"\\\"Validate the deliberately narrow JSON value grammar used by overrides.\\\"\\\"\\\"\\n        if depth > _MAX_OVERRIDE_JSON_DEPTH:\\n            raise InvalidRequestOverridesError(field)\\n        if value is None or isinstance(value, bool):\\n            return\\n        if isinstance(value, str):\\n            try:\\n                value.encode(\\\"utf-8\\\")\\n            except UnicodeEncodeError:\\n                raise InvalidRequestOverridesError(field) from None\\n            return\\n        if isinstance(value, int):\\n            # Bound decimal conversion below Python's default 4,300-digit\\n            # protection so behavior is stable on every supported interpreter.\\n            if value.bit_length() > _MAX_OVERRIDE_INTEGER_BITS:\\n                raise InvalidRequestOverridesError(field)\\n            return\\n        if isinstance(value, float):\\n            if not math.isfinite(value):\\n                raise InvalidRequestOverridesError(field)\\n            return\\n        if not isinstance(value, (dict, list)):\\n            raise InvalidRequestOverridesError(field)\\n        if seen is None:\\n            seen = set()\\n        value_id = id(value)\\n        if value_id in seen:\\n            raise InvalidRequestOverridesError(field)\\n        seen.add(value_id)\\n        try:\\n            if isinstance(value, dict):\\n                for key, nested in value.items():\\n                    if not isinstance(key, str):\\n                        raise InvalidRequestOverridesError(field)\\n                    try:\\n                        key.encode(\\\"utf-8\\\")\\n                    except UnicodeEncodeError:\\n                        raise InvalidRequestOverridesError(field) from None\\n                    cls._validate_json_value(nested, field=field, seen=seen, depth=depth + 1)\\n            else:\\n                for nested in value:\\n                    cls._validate_json_value(nested, field=field, seen=seen, depth=depth + 1)\\n        finally:\\n            seen.remove(value_id)\\n\\n    @classmethod\\n    def _validated_overrides(cls, value: Any) -> dict[str, dict[str, Any]]:\\n        \\\"\\\"\\\"Return validated globals/tweaks only, rejecting all other envelope shapes.\\\"\\\"\\\"\\n        if not isinstance(value, dict) or not set(value).issubset(_REQUEST_OVERRIDE_FIELDS):\\n            raise InvalidRequestOverridesError(_REQUEST_OVERRIDES_CONTAINER_FIELD)\\n        overrides: dict[str, dict[str, Any]] = {}\\n        for key, nested in value.items():\\n            if not isinstance(nested, dict):\\n                raise InvalidRequestOverridesError(key)\\n            cls._validate_json_value(nested, field=key)\\n            overrides[key] = nested\\n        return overrides\\n\\n    def _persisted_request_metadata(self, *, job_id: UUID, flow_id: UUID, request: dict[str, Any]) -> dict[str, Any]:\\n        \\\"\\\"\\\"Build the atomic metadata payload for a background workflow row.\\\"\\\"\\\"\\n        supplied_overrides = self._validated_overrides(\\n            {key: request[key] for key in _REQUEST_OVERRIDE_FIELDS if key in request}\\n        )\\n        # The API models default both fields to {}, so treat empty mappings as no\\n        # override rather than encrypting an envelope for every ordinary run.\\n        overrides = {key: value for key, value in supplied_overrides.items() if value}\\n        metadata: dict[str, Any] = {\\\"request\\\": self._redact_request(request)}\\n        if overrides:\\n            from langflow.services.auth.utils import get_fernet\\n\\n            envelope = {\\n                \\\"version\\\": _REQUEST_OVERRIDES_VERSION,\\n                \\\"job_id\\\": str(job_id),\\n                \\\"flow_id\\\": str(flow_id),\\n                \\\"overrides\\\": overrides,\\n            }\\n            try:\\n                plaintext = json.dumps(\\n                    envelope,\\n                    allow_nan=False,\\n                    ensure_ascii=False,\\n                    separators=(\\\",\\\", \\\":\\\"),\\n                    sort_keys=True,\\n                ).encode()\\n            except (RecursionError, TypeError, UnicodeError, ValueError, OverflowError) as exc:\\n                logger.warning(\\n                    \\\"Background request override serialization failed\\\",\\n                    job_id=str(job_id),\\n                    flow_id=str(flow_id),\\n                    stage=\\\"serialize\\\",\\n                    error_type=type(exc).__name__,\\n                )\\n                raise InvalidRequestOverridesError(_REQUEST_OVERRIDES_CONTAINER_FIELD) from None\\n            except Exception as exc:  # noqa: BLE001 -- resource/server failures remain retryable\\n                logger.error(\\n                    \\\"Background request override serialization unavailable\\\",\\n                    job_id=str(job_id),\\n                    flow_id=str(flow_id),\\n                    stage=\\\"serialize\\\",\\n                    error_type=type(exc).__name__,\\n                )\\n                raise RequestOverridesUnavailableError from None\\n            try:\\n                ciphertext = get_fernet(self.settings_service).encrypt(plaintext).decode(\\\"ascii\\\")\\n            except Exception as exc:  # noqa: BLE001 -- every crypto/config failure becomes the same safe error\\n                logger.error(\\n                    \\\"Background request override encryption failed\\\",\\n                    job_id=str(job_id),\\n                    flow_id=str(flow_id),\\n                    stage=\\\"encrypt\\\",\\n                    error_type=type(exc).__name__,\\n                )\\n                raise RequestOverridesUnavailableError from None\\n            metadata[_REQUEST_OVERRIDES_FORMAT_KEY] = _REQUEST_OVERRIDES_FORMAT\\n            metadata[_REQUEST_OVERRIDES_KEY] = ciphertext\\n        return metadata\\n\\n    def _decrypt_request_overrides(self, job: Job, metadata: dict[str, Any]) -> dict[str, dict[str, Any]]:\\n        \\\"\\\"\\\"Authenticate, decrypt, bind, and validate a job's override envelope.\\\"\\\"\\\"\\n        has_marker = _REQUEST_OVERRIDES_FORMAT_KEY in metadata\\n        has_ciphertext = _REQUEST_OVERRIDES_KEY in metadata\\n        if not has_marker and not has_ciphertext:\\n            # New no-override rows and safe legacy rows intentionally carry neither\\n            # key. Plaintext values are rejected separately by reconstruction.\\n            return {}\\n        if not has_marker or not has_ciphertext or metadata[_REQUEST_OVERRIDES_FORMAT_KEY] != _REQUEST_OVERRIDES_FORMAT:\\n            raise RequestOverridesCorruptedError\\n        ciphertext = metadata[_REQUEST_OVERRIDES_KEY]\\n        if not isinstance(ciphertext, str) or not ciphertext:\\n            raise RequestOverridesCorruptedError\\n\\n        from langflow.services.auth.utils import get_fernet_for_decryption\\n\\n        try:\\n            encoded_ciphertext = ciphertext.encode(\\\"ascii\\\")\\n        except UnicodeEncodeError as exc:\\n            logger.error(\\n                \\\"Background request override ciphertext validation failed\\\",\\n                job_id=str(job.job_id),\\n                flow_id=str(job.flow_id),\\n                stage=\\\"validate\\\",\\n                error_type=type(exc).__name__,\\n            )\\n            raise RequestOverridesCorruptedError from None\\n        except Exception as exc:  # noqa: BLE001 -- resource/server failures remain retryable\\n            logger.error(\\n                \\\"Background request override ciphertext encoding unavailable\\\",\\n                job_id=str(job.job_id),\\n                flow_id=str(job.flow_id),\\n                stage=\\\"encode\\\",\\n                error_type=type(exc).__name__,\\n            )\\n            raise RequestOverridesUnavailableError from None\\n\\n        try:\\n            plaintext = get_fernet_for_decryption(self.settings_service).decrypt(encoded_ciphertext)\\n        except Exception as exc:  # noqa: BLE001 -- Fernet auth failure cannot distinguish bad key from tampering\\n            logger.error(\\n                \\\"Background request override decryption failed\\\",\\n                job_id=str(job.job_id),\\n                flow_id=str(job.flow_id),\\n                stage=\\\"decrypt\\\",\\n                error_type=type(exc).__name__,\\n            )\\n            raise RequestOverridesUnavailableError from None\\n\\n        try:\\n            envelope = json.loads(plaintext)\\n            if not isinstance(envelope, dict) or set(envelope) != {\\\"version\\\", \\\"job_id\\\", \\\"flow_id\\\", \\\"overrides\\\"}:\\n                raise RequestOverridesCorruptedError\\n            if type(envelope[\\\"version\\\"]) is not int or envelope[\\\"version\\\"] != _REQUEST_OVERRIDES_VERSION:\\n                raise RequestOverridesCorruptedError\\n            if envelope[\\\"job_id\\\"] != str(job.job_id) or envelope[\\\"flow_id\\\"] != str(job.flow_id):\\n                raise RequestOverridesCorruptedError\\n            try:\\n                overrides = self._validated_overrides(envelope[\\\"overrides\\\"])\\n            except InvalidRequestOverridesError:\\n                raise RequestOverridesCorruptedError from None\\n            if not overrides:\\n                raise RequestOverridesCorruptedError\\n        except RequestOverridesCorruptedError as exc:\\n            logger.error(\\n                \\\"Background request override envelope validation failed\\\",\\n                job_id=str(job.job_id),\\n                flow_id=str(job.flow_id),\\n                stage=\\\"validate\\\",\\n                error_type=type(exc).__name__,\\n            )\\n            raise\\n        except (RecursionError, TypeError, UnicodeError, ValueError, OverflowError) as exc:\\n            logger.error(\\n                \\\"Background request override parsing failed\\\",\\n                job_id=str(job.job_id),\\n                flow_id=str(job.flow_id),\\n                stage=\\\"parse\\\",\\n                error_type=type(exc).__name__,\\n            )\\n            raise RequestOverridesCorruptedError from None\\n        except Exception as exc:  # noqa: BLE001 -- resource/server failures remain retryable\\n            logger.error(\\n                \\\"Background request override parsing unavailable\\\",\\n                job_id=str(job.job_id),\\n                flow_id=str(job.flow_id),\\n                stage=\\\"parse\\\",\\n                error_type=type(exc).__name__,\\n            )\\n            raise RequestOverridesUnavailableError from None\\n        else:\\n            return overrides\\n\\n    @staticmethod\\n    async def _existing_job_for_dedupe(dedupe_key: str | None, user_id: UUID | None) -> UUID | None:\\n        \\\"\\\"\\\"Return the active job_id sharing ``dedupe_key`` for this user, if any.\\n\\n        Mirrors ``create_job``'s non-terminal set (QUEUED / IN_PROGRESS /\\n        COMPLETED) so a retried POST resolves to the same job a terminal job\\n        with the same key would not block (allowing a genuine re-run).\\n        \\\"\\\"\\\"\\n        if dedupe_key is None:\\n            return None\\n        from sqlmodel import col, select\\n\\n        from langflow.services.database.models.jobs.model import Job as JobModel\\n        from langflow.services.deps import session_scope\\n\\n        async with session_scope() as session:\\n            stmt = (\\n                select(JobModel)\\n                .where(JobModel.dedupe_key == dedupe_key)\\n                # Why: SUSPENDED included so a retry while paused at a HITL node can't bypass dedupe.\\n                .where(\\n                    col(JobModel.status).in_(\\n                        [JobStatus.QUEUED, JobStatus.IN_PROGRESS, JobStatus.SUSPENDED, JobStatus.COMPLETED]\\n                    )\\n                )\\n            )\\n            if user_id is not None:\\n                stmt = stmt.where(JobModel.user_id == user_id)\\n            result = await session.exec(stmt)\\n            row = result.first()\\n            return row.job_id if row is not None else None\\n\\n    async def _enqueue(self, *, job_id: UUID, flow_id: UUID, request: dict[str, Any], user: UserRead | None) -> None:\\n        \\\"\\\"\\\"Build a runner for the job and submit it to the in-process executor.\\\"\\\"\\\"\\n        job_service = get_job_service()\\n        adapter = self._build_adapter(request, job_id, flow_id)\\n        source = self._frame_source_factory(request=request, flow_id=flow_id, user=user, adapter=adapter)\\n        runner = JobRunner(\\n            job_service=job_service,\\n            live_bus=self._bus,\\n            adapter=adapter,\\n            frame_source=source,\\n            job_timeout=self._settings.background_job_timeout,\\n            owner=self._owner,\\n            heartbeat_interval_s=self._settings.background_heartbeat_interval_s,\\n            input_deadline_s=self._settings.background_input_deadline_s,\\n        )\\n\\n        async def _coro() -> None:\\n            # job_id reaches the frame source via source_kwargs so the default\\n            # build-loop source can tag its memory-base hook with the run's job.\\n            await runner.run(job_id=job_id, source_kwargs={\\\"job_id\\\": job_id})\\n\\n        await self._executor.submit(str(job_id), _coro)\\n\\n    # ------------------------------------------------------------------ events\\n\\n    async def events(\\n        self,\\n        job_id: UUID,\\n        last_event_id: str | None,\\n        user: UserRead,\\n    ) -> AsyncIterator[bytes]:\\n        job = await self._validate(job_id, user)\\n        job_service = get_job_service()\\n        last_seq = self._parse_last_event_id(last_event_id)\\n        # The durable replay must serialize with the SAME separators the live\\n        # adapter used (agui = compact, langflow = spaced) so replayed bytes are\\n        # byte-identical. The protocol is on the persisted submit request.\\n        protocol = self._job_protocol(job)\\n\\n        async def read_durable(after_seq: int) -> list[LiveFrame]:\\n            rows = await job_service.read_events(job_id, after_seq=after_seq)\\n            return [LiveFrame(seq=r.seq, data=self._row_to_frame(r, protocol=protocol)) for r in rows]\\n\\n        # Terminal jobs must be answered from the DURABLE log alone. The live bus\\n        # is process-local: after a restart it is fresh and its ``_closed`` marker\\n        # is empty, so ``reattach`` would replay durable rows then block forever on\\n        # ``while True: queue.get()`` waiting for a live tail that will never come.\\n        # Decide \\\"finished\\\" off the persisted status (the cross-restart source of\\n        # truth), replay, and return.\\n        # SUSPENDED is parked awaiting human input: no live tail to wait on, so answer\\n        # from the durable log alone (like a terminal status) instead of blocking.\\n        if job.status in _TERMINAL_STATUSES or job.status == JobStatus.SUSPENDED:\\n            for frame in await read_durable(last_seq):\\n                yield frame.data\\n            return\\n\\n        # Scaled mode: any API replica serves reattach by replaying durable\\n        # job_events (from the DB) then tailing the shared redis Stream.\\n        if self._scaled:\\n            async for item in self._backend.events(str(job_id), last_event_id=last_seq):\\n                seq = getattr(item, \\\"seq\\\", None)\\n                if seq is not None:\\n                    yield self._row_to_frame(item, protocol=protocol)\\n                else:\\n                    yield item.payload\\n            return\\n\\n        async def _is_terminal() -> bool:\\n            # SUSPENDED ends the tail too: a run that connected while IN_PROGRESS and\\n            # then suspended has no live tail to wait on (the pause isn't published live).\\n            current = await job_service.get_job_by_job_id(job_id)\\n            return current is not None and (\\n                current.status in _TERMINAL_STATUSES or current.status == JobStatus.SUSPENDED\\n            )\\n\\n        async for frame in self._bus.reattach(\\n            str(job_id), last_seq=last_seq, read_durable=read_durable, is_done=_is_terminal\\n        ):\\n            yield frame.data\\n\\n    # ------------------------------------------------------------------ status\\n\\n    async def status(self, job_id: UUID, user: UserRead) -> dict[str, Any]:\\n        job = await self._validate(job_id, user)\\n        payload: dict[str, Any] = {\\n            \\\"job_id\\\": str(job.job_id),\\n            \\\"flow_id\\\": str(job.flow_id),\\n            \\\"status\\\": job.status,\\n        }\\n        # Surface durable result/error additively.\\n        if job.result is not None:\\n            payload[\\\"result\\\"] = job.result\\n        if job.error is not None:\\n            payload[\\\"error\\\"] = job.error\\n        if job.status == JobStatus.SUSPENDED:\\n            pending = await get_job_service().get_pending_human_request(job_id)\\n            if pending is not None:\\n                payload[\\\"pending_request\\\"] = pending\\n        return payload\\n\\n    async def result(self, job_id: UUID, user: UserRead) -> Any:\\n        job = await self._validate(job_id, user)\\n        return job.result\\n\\n    async def stop_job(self, job_id: UUID, user: UserRead) -> None:\\n        job = await self._validate(job_id, user)\\n        if self._scaled:\\n            # Scaled mode: the owning worker runs in another process; backend.stop\\n            # writes the durable STOP signal its JobRunner polls at vertex boundaries.\\n            await self._backend.stop(str(job_id))\\n            return\\n        job_service = get_job_service()\\n        # A lost claim means a resume flipped it IN_PROGRESS mid-call \u2014 fall\\n        # through to the running-job stop path instead of doing nothing.\\n        if job.status == JobStatus.SUSPENDED and await self._cancel_suspended(job_id, job_service):\\n            return\\n        await job_service.write_signal(job_id, SignalType.STOP)\\n        await self._executor.cancel(str(job_id))\\n\\n    async def resume_job(self, job_id: UUID, user: UserRead, *, request_id: str, decision: Any) -> bool:  # noqa: ARG002\\n        \\\"\\\"\\\"Carry a human decision back into a SUSPENDED run and re-enqueue it.\\n\\n        Returns True when the run was accepted for resume, False on a conflict\\n        (not suspended, stale request_id, or lost the single-flight flip) \u2014 the\\n        route maps False to 409. Ownership (owner-or-superuser) is enforced at the\\n        HTTP route, so this fetches by id alone and trusts the already-validated user.\\n        \\\"\\\"\\\"\\n        job_service = get_job_service()\\n        job = await job_service.get_job_by_job_id(job_id)\\n        if job is None or job.type != JobType.WORKFLOW or job.status != JobStatus.SUSPENDED:\\n            return False\\n        pending = (job.job_metadata or {}).get(\\\"pending_request_id\\\")\\n        if pending is not None and request_id != pending:\\n            return False\\n        # Decrypt and validate before the single-flight claim or signal write. A\\n        # key-rotation/configuration error must leave the pause and decision seam\\n        # untouched so the caller can retry after restoring the key.\\n        request = self._reconstruct_request(job)\\n        # Win the single-flight flip BEFORE writing the RESUME signal, so exactly one\\n        # RESUME row exists per suspend and a loser never strands a stray decision.\\n        if not await job_service.claim_suspended_for_resume(job_id, owner=self._owner):\\n            return False\\n        await job_service.write_signal(job_id, SignalType.RESUME, {\\\"decision\\\": decision, \\\"request_id\\\": request_id})\\n        try:\\n            await self._enqueue(\\n                job_id=job_id,\\n                flow_id=job.flow_id,\\n                request=request,\\n                user=self._user_stub(job.user_id),\\n            )\\n        except Exception:\\n            # Why: claim already flipped SUSPENDED\u2192IN_PROGRESS; a failed enqueue would strand the job\\n            # and lose the decision \u2014 roll back to SUSPENDED (clearing RESUME) so it can be retried.\\n            with contextlib.suppress(Exception):\\n                await job_service.consume_signals(job_id, SignalType.RESUME)\\n            await job_service.update_job_status(job_id, JobStatus.SUSPENDED)\\n            raise\\n        return True\\n\\n    async def _cancel_suspended(self, job_id: UUID, job_service) -> bool:\\n        \\\"\\\"\\\"Cancel a SUSPENDED job; False when a concurrent resume already claimed it.\\n\\n        The conditional claim is what makes supersede-vs-resume safe: cleanup\\n        (checkpoint delete, metadata clear, terminal event) runs only for the row\\n        this caller actually flipped, never for a run a resume just revived.\\n        \\\"\\\"\\\"\\n        if not await job_service.claim_suspended_for_cancel(job_id):\\n            return False\\n        from langflow.api.v2.hitl import mark_card_superseded\\n\\n        await mark_card_superseded(job_id)\\n        with contextlib.suppress(Exception):\\n            await job_service.delete_checkpoint(job_id, \\\"graph\\\")\\n        await job_service.update_job_metadata(job_id, {\\\"pending_request_id\\\": None})\\n        await job_service.append_event(job_id, \\\"run_cancelled\\\", {\\\"type\\\": \\\"cancelled\\\"})\\n        await job_service.consume_signals(job_id, SignalType.STOP)\\n        await self._bus.close(str(job_id))\\n        return True\\n\\n    # ----------------------------------------------------------- startup sweep\\n\\n    async def sweep_orphans_on_startup(self) -> None:\\n        \\\"\\\"\\\"Reconcile jobs left mid-flight by a crashed process.\\n\\n        Single-flight across workers: this runs in the per-worker lifespan on\\n        every uvicorn/gunicorn boot, so it is guarded by a file lock (the same\\n        primitive ``main.py`` uses for starter projects). Only ONE booting worker\\n        runs the IN_PROGRESS reconcile; the others skip it. The reconcile is also\\n        liveness-aware (``sweep_orphans`` only fails rows whose heartbeat is\\n        stale/absent), so even without the lock a booting worker can never flip a\\n        sibling's actively-running, freshly-heartbeated job FAILED.\\n\\n        ``JobService.sweep_orphans`` does the durable reconcile (FAILED +\\n        worker_lost + terminal event). QUEUED workflow rows never started, so\\n        under at-least-once we re-enqueue them onto this worker's executor with a\\n        reconstructed request. Best-effort per job so one bad row can't block the\\n        rest. A real scaled Redis backend reconciles via its own watchdog; when\\n        those modules are unavailable, the in-process fallback starts its local\\n        periodic watchdog and performs this initial sweep.\\n        \\\"\\\"\\\"\\n        await self.start()\\n        job_service = get_job_service()\\n        lease_ttl = self._settings.background_lease_ttl_s\\n        if self._is_redis:\\n            if not self._scaled:\\n                await job_service.sweep_orphans(lease_ttl_s=lease_ttl)\\n            return\\n        # Single-flight the IN_PROGRESS reconcile: only the worker that wins the\\n        # lock fails orphans; the others skip (a non-blocking try-acquire). The\\n        # QUEUED re-enqueue below stays per-worker because each row is lease-claimed\\n        # atomically (claim_queued_lease), so two workers cannot double-run it.\\n        lock_file = Path(tempfile.gettempdir()) / \\\"langflow_bg_orphan_sweep.lock\\\"\\n        lock = FileLock(lock_file, timeout=0)\\n        try:\\n            with lock:\\n                # Fail genuinely-orphaned IN_PROGRESS rows (stale/absent heartbeat).\\n                await job_service.sweep_orphans(lease_ttl_s=lease_ttl)\\n        except Timeout:\\n            # Another worker is running the reconcile; skip ours.\\n            await logger.adebug(\\\"Another worker is sweeping orphans, skipping\\\")\\n        # Re-enqueue QUEUED workflow rows (at-least-once for not-yet-started work).\\n        # Each row is LEASE-claimed (single-flight) WITHOUT flipping it to\\n        # IN_PROGRESS, so two workers booting against the same DB cannot both\\n        # re-run it (only the claim whose rowcount==1 enqueues), AND a re-enqueue\\n        # that crashes before the runner starts leaves the row QUEUED and\\n        # re-runnable on the next boot rather than a stranded IN_PROGRESS the next\\n        # sweep would fail worker_lost. The runner's execute_with_status performs\\n        # the real QUEUED->IN_PROGRESS flip once it actually starts emitting.\\n        for job in await self._queued_workflow_jobs():\\n            lease_heartbeat = datetime.now(timezone.utc).isoformat()\\n            if not await job_service.claim_queued_lease(\\n                job.job_id,\\n                owner=self._owner,\\n                lease_ttl_s=lease_ttl,\\n                heartbeat_at=lease_heartbeat,\\n            ):\\n                continue\\n            try:\\n                request_dict = self._reconstruct_request(job)\\n            except RequestOverridesCorruptedError:\\n                await job_service.fail_queued_job(\\n                    job.job_id,\\n                    owner=self._owner,\\n                    heartbeat_at=lease_heartbeat,\\n                    error=dict(_REQUEST_OVERRIDES_ERROR),\\n                    event_type=\\\"run_failed\\\",\\n                )\\n                continue\\n            except RequestOverridesUnavailableError as exc:\\n                await logger.aerror(\\n                    \\\"Background request overrides unavailable during startup recovery\\\",\\n                    job_id=str(job.job_id),\\n                    flow_id=str(job.flow_id),\\n                    stage=\\\"startup_restore\\\",\\n                    error_type=type(exc).__name__,\\n                )\\n                await job_service.release_queued_lease(\\n                    job.job_id,\\n                    owner=self._owner,\\n                    heartbeat_at=lease_heartbeat,\\n                )\\n                continue\\n            user = self._user_stub(job.user_id)\\n            with contextlib.suppress(Exception):\\n                await self._enqueue(\\n                    job_id=job.job_id,\\n                    flow_id=job.flow_id,\\n                    request=request_dict,\\n                    user=user,\\n                )\\n        # Give up on runs that have sat suspended past their human-input deadline.\\n        with contextlib.suppress(Exception):\\n            await self.sweep_input_deadlines()\\n\\n    async def sweep_input_deadlines(self) -> list[UUID]:\\n        \\\"\\\"\\\"Enforce the input deadline (LE-1452): FAIL overdue SUSPENDED runs, close their bus.\\n\\n        The durable FAIL + terminal event is JobService's; this also closes any live bus\\n        still held open for a same-process suspended run so a reattaching client ends\\n        cleanly. A no-op (and never queries the DB) when the deadline is disabled.\\n        \\\"\\\"\\\"\\n        if self._settings.background_input_deadline_s is None:\\n            return []\\n        failed = await get_job_service().sweep_input_deadlines()\\n        for job_id in failed:\\n            with contextlib.suppress(Exception):\\n                await self._bus.close(str(job_id))\\n        return failed\\n\\n    @staticmethod\\n    async def _queued_workflow_jobs() -> list[Job]:\\n        from sqlmodel import select\\n\\n        from langflow.services.database.models.jobs.model import Job as JobModel\\n        from langflow.services.deps import session_scope\\n\\n        async with session_scope() as session:\\n            stmt = select(JobModel).where(\\n                JobModel.status == JobStatus.QUEUED,\\n                JobModel.type == JobType.WORKFLOW,\\n            )\\n            result = await session.exec(stmt)\\n            return list(result.all())\\n\\n    def _reconstruct_request(self, job: Job) -> dict[str, Any]:\\n        \\\"\\\"\\\"Rebuild the request dict for a re-enqueued QUEUED job.\\n\\n        ``submit`` persists replay-safe fields under ``job_metadata[\\\"request\\\"]``\\n        and globals/tweaks in an authenticated Fernet envelope beside it. Legacy\\n        rows with no overrides keep their old fallback; legacy plaintext overrides\\n        and malformed encrypted rows fail closed.\\n        \\\"\\\"\\\"\\n        meta = job.job_metadata or {}\\n        persisted = meta.get(\\\"request\\\")\\n        if isinstance(persisted, dict) and persisted:\\n            request = dict(persisted)\\n        else:\\n            request = {\\n                \\\"flow_id\\\": str(job.flow_id),\\n                \\\"mode\\\": \\\"background\\\",\\n                \\\"stream_protocol\\\": meta.get(\\\"stream_protocol\\\", \\\"langflow\\\"),\\n                \\\"session_id\\\": meta.get(\\\"session_id\\\"),\\n                \\\"input_value\\\": meta.get(\\\"input_value\\\", \\\"\\\"),\\n            }\\n        # Pre-fix v2 requests always included empty override defaults. They carry\\n        # no value and are safe to normalize away; every other plaintext shape\\n        # remains a fail-closed downgrade attempt.\\n        for key in _REQUEST_OVERRIDE_FIELDS.intersection(request):\\n            value = request.pop(key)\\n            if not isinstance(value, dict) or value:\\n                raise RequestOverridesCorruptedError\\n        return {**request, **self._decrypt_request_overrides(job, meta)}\\n\\n    @staticmethod\\n    def _user_stub(user_id: UUID | None) -> UserRead | None:\\n        \\\"\\\"\\\"A minimal UserRead carrying only ``id``.\\n\\n        The default frame source only reads ``user.id`` (to fetch the flow), so\\n        a partial object is sufficient. Returns None for legacy ownerless jobs.\\n        \\\"\\\"\\\"\\n        if user_id is None:\\n            return None\\n        from langflow.services.database.models.user.model import UserRead\\n\\n        return UserRead.model_construct(id=user_id)\\n\\n    # ----------------------------------------------------------------- helpers\\n\\n    async def _validate(self, job_id: UUID, user: UserRead) -> Job:\\n        job_service = get_job_service()\\n        try:\\n            job = await job_service._validate_ownership(job_id, user.id)  # noqa: SLF001\\n        except ValueError as exc:\\n            raise PermissionError(str(exc)) from exc\\n        if job.type != JobType.WORKFLOW:\\n            msg = f\\\"Job {job_id} is not a workflow job\\\"\\n            raise PermissionError(msg)\\n        return job\\n\\n    @staticmethod\\n    def _job_protocol(job: Job) -> str:\\n        \\\"\\\"\\\"The stream protocol the run used, read off the persisted submit request.\\n\\n        ``submit`` persists the request (incl. ``stream_protocol``) under\\n        ``job_metadata['request']``. Replay needs it so it serializes durable\\n        rows with the SAME separators the live adapter used. Defaults to\\n        ``langflow`` for legacy rows written before the request was persisted.\\n        \\\"\\\"\\\"\\n        meta = job.job_metadata or {}\\n        request = meta.get(\\\"request\\\")\\n        if isinstance(request, dict):\\n            return request.get(\\\"stream_protocol\\\") or \\\"langflow\\\"\\n        return meta.get(\\\"stream_protocol\\\") or \\\"langflow\\\"\\n\\n    def _build_adapter(self, request: dict[str, Any], job_id: UUID, flow_id: UUID):\\n        from lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\n\\n        protocol = request.get(\\\"stream_protocol\\\", \\\"langflow\\\")\\n        return get_stream_adapter(\\n            protocol,\\n            StreamAdapterContext(\\n                run_id=str(job_id),\\n                thread_id=request.get(\\\"session_id\\\") or str(flow_id),\\n            ),\\n        )\\n\\n    @staticmethod\\n    def _parse_last_event_id(last_event_id: str | None) -> int:\\n        if not last_event_id:\\n            return 0\\n        try:\\n            return int(last_event_id)\\n        except ValueError:\\n            return 0\\n\\n    @staticmethod\\n    def _row_to_frame(row: JobEvent, *, protocol: str = \\\"langflow\\\") -> bytes:\\n        # Re-frame the durable payload through the SAME SSE formatter the live\\n        # path uses (``format_sse_event(data_str=..., id=str(seq))``) so replayed\\n        # bytes are byte-compatible with live frames and a client's\\n        # ``Last-Event-ID`` resume works across the replay/tail boundary. The\\n        # live path passes the payload's JSON string as ``data_str``; ``seq`` is\\n        # the durable row seq, matching the live frame's ``id``.\\n        #\\n        # The JSON separators must match the LIVE adapter or the replayed bytes\\n        # are not byte-identical: the ``langflow`` adapter serializes via\\n        # ``json.dumps`` (default spaced separators) while the ``agui`` adapter\\n        # serializes via pydantic ``model_dump_json`` (compact separators). Pick\\n        # the matching separators by protocol so replay == live for both wires.\\n        from fastapi.sse import format_sse_event\\n\\n        separators = (\\\",\\\", \\\":\\\") if protocol == \\\"agui\\\" else None\\n        return format_sse_event(data_str=json.dumps(row.payload, separators=separators), id=str(row.seq))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"688334fe9fc54b8044ed3c4d51305f75439b89ed507a479e94cd873ccf3d28fe\",\"content\":\"from abc import ABC\\n\\n\\nclass Service(ABC):\\n    name: str\\n    ready: bool = False\\n\\n    def get_schema(self):\\n        \\\"\\\"\\\"Build a dictionary listing all methods, their parameters, types, return types and documentation.\\\"\\\"\\\"\\n        schema = {}\\n        ignore = [\\\"teardown\\\", \\\"set_ready\\\"]\\n        for method in dir(self):\\n            if method.startswith(\\\"_\\\") or method in ignore:\\n                continue\\n            func = getattr(self, method)\\n            schema[method] = {\\n                \\\"name\\\": method,\\n                \\\"parameters\\\": func.__annotations__,\\n                \\\"return\\\": func.__annotations__.get(\\\"return\\\"),\\n                \\\"documentation\\\": func.__doc__,\\n            }\\n        return schema\\n\\n    async def teardown(self) -> None:\\n        return\\n\\n    def set_ready(self) -> None:\\n        self.ready = True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/cache/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"af14baeeee8ff4792ec1962dd6c310b7a14bab2567d858006b5ff15e552b98ec\",\"content\":\"from langflow.services.cache.service import AsyncInMemoryCache, CacheService, RedisCache, ThreadingInMemoryCache\\n\\nfrom . import factory, service\\n\\n__all__ = [\\n    \\\"AsyncInMemoryCache\\\",\\n    \\\"CacheService\\\",\\n    \\\"RedisCache\\\",\\n    \\\"ThreadingInMemoryCache\\\",\\n    \\\"factory\\\",\\n    \\\"service\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/cache/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c2a75ad9ebe3ae6c385ef257d30b0fa790cfdb081b1f22cdb59cc2c5d50b029a\",\"content\":\"import abc\\nimport asyncio\\nimport threading\\nfrom typing import Generic, TypeVar\\n\\nfrom langflow.services.base import Service\\n\\nLockType = TypeVar(\\\"LockType\\\", bound=threading.Lock)\\nAsyncLockType = TypeVar(\\\"AsyncLockType\\\", bound=asyncio.Lock)\\n\\n\\nclass CacheService(Service, Generic[LockType]):\\n    \\\"\\\"\\\"Abstract base class for a cache.\\\"\\\"\\\"\\n\\n    name = \\\"cache_service\\\"\\n\\n    @abc.abstractmethod\\n    def get(self, key, lock: LockType | None = None):\\n        \\\"\\\"\\\"Retrieve an item from the cache.\\n\\n        Args:\\n            key: The key of the item to retrieve.\\n            lock: A lock to use for the operation.\\n\\n        Returns:\\n            The value associated with the key, or CACHE_MISS if the key is not found.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def set(self, key, value, lock: LockType | None = None):\\n        \\\"\\\"\\\"Add an item to the cache.\\n\\n        Args:\\n            key: The key of the item.\\n            value: The value to cache.\\n            lock: A lock to use for the operation.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def upsert(self, key, value, lock: LockType | None = None):\\n        \\\"\\\"\\\"Add an item to the cache if it doesn't exist, or update it if it does.\\n\\n        Args:\\n            key: The key of the item.\\n            value: The value to cache.\\n            lock: A lock to use for the operation.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def delete(self, key, lock: LockType | None = None):\\n        \\\"\\\"\\\"Remove an item from the cache.\\n\\n        Args:\\n            key: The key of the item to remove.\\n            lock: A lock to use for the operation.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def clear(self, lock: LockType | None = None):\\n        \\\"\\\"\\\"Clear all items from the cache.\\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def contains(self, key) -> bool:\\n        \\\"\\\"\\\"Check if the key is in the cache.\\n\\n        Args:\\n            key: The key of the item to check.\\n\\n        Returns:\\n            True if the key is in the cache, False otherwise.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def __contains__(self, key) -> bool:\\n        \\\"\\\"\\\"Check if the key is in the cache.\\n\\n        Args:\\n            key: The key of the item to check.\\n\\n        Returns:\\n            True if the key is in the cache, False otherwise.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def __getitem__(self, key):\\n        \\\"\\\"\\\"Retrieve an item from the cache using the square bracket notation.\\n\\n        Args:\\n            key: The key of the item to retrieve.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def __setitem__(self, key, value) -> None:\\n        \\\"\\\"\\\"Add an item to the cache using the square bracket notation.\\n\\n        Args:\\n            key: The key of the item.\\n            value: The value to cache.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def __delitem__(self, key) -> None:\\n        \\\"\\\"\\\"Remove an item from the cache using the square bracket notation.\\n\\n        Args:\\n            key: The key of the item to remove.\\n        \\\"\\\"\\\"\\n\\n\\nclass AsyncBaseCacheService(Service, Generic[AsyncLockType]):\\n    \\\"\\\"\\\"Abstract base class for a async cache.\\\"\\\"\\\"\\n\\n    name = \\\"cache_service\\\"\\n\\n    @abc.abstractmethod\\n    async def get(self, key, lock: AsyncLockType | None = None):\\n        \\\"\\\"\\\"Retrieve an item from the cache.\\n\\n        Args:\\n            key: The key of the item to retrieve.\\n            lock: A lock to use for the operation.\\n\\n        Returns:\\n            The value associated with the key, or CACHE_MISS if the key is not found.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def set(self, key, value, lock: AsyncLockType | None = None):\\n        \\\"\\\"\\\"Add an item to the cache.\\n\\n        Args:\\n            key: The key of the item.\\n            value: The value to cache.\\n            lock: A lock to use for the operation.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def upsert(self, key, value, lock: AsyncLockType | None = None):\\n        \\\"\\\"\\\"Add an item to the cache if it doesn't exist, or update it if it does.\\n\\n        Args:\\n            key: The key of the item.\\n            value: The value to cache.\\n            lock: A lock to use for the operation.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def delete(self, key, lock: AsyncLockType | None = None):\\n        \\\"\\\"\\\"Remove an item from the cache.\\n\\n        Args:\\n            key: The key of the item to remove.\\n            lock: A lock to use for the operation.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def clear(self, lock: AsyncLockType | None = None):\\n        \\\"\\\"\\\"Clear all items from the cache.\\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def contains(self, key) -> bool:\\n        \\\"\\\"\\\"Check if the key is in the cache.\\n\\n        Args:\\n            key: The key of the item to check.\\n\\n        Returns:\\n            True if the key is in the cache, False otherwise.\\n        \\\"\\\"\\\"\\n\\n\\nclass ExternalAsyncBaseCacheService(AsyncBaseCacheService):\\n    \\\"\\\"\\\"Abstract base class for an external async cache.\\n\\n    Subclasses MUST implement ``teardown`` so the Gunicorn master preload\\n    hook can close any OS-level connection resources (TCP sockets, file\\n    descriptors, etc.) before fork. Leaving ``teardown`` unimplemented\\n    would cause workers to share a single connection across processes,\\n    leading to undefined protocol-level behavior.\\n    \\\"\\\"\\\"\\n\\n    name = \\\"cache_service\\\"\\n\\n    @abc.abstractmethod\\n    async def is_connected(self) -> bool:\\n        \\\"\\\"\\\"Check if the cache is connected.\\n\\n        Returns:\\n            True if the cache is connected, False otherwise.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def teardown(self) -> None:\\n        \\\"\\\"\\\"Release fork-unsafe OS resources held by this cache.\\n\\n        Called from the Gunicorn master preload hook *before* workers are\\n        forked. After this returns, subsequent cache operations in a\\n        worker must transparently re-establish their own connections.\\n        \\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/cache/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9f69a26dd7dd782031ce3b76440d66919b346f6fa7ef68bbc42e839f4cb4cb87\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\nfrom typing_extensions import override\\n\\nfrom langflow.services.cache.service import AsyncInMemoryCache, CacheService, RedisCache, ThreadingInMemoryCache\\nfrom langflow.services.factory import ServiceFactory\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.service import SettingsService\\n\\n\\nclass CacheServiceFactory(ServiceFactory):\\n    def __init__(self) -> None:\\n        super().__init__(CacheService)\\n\\n    @override\\n    def create(self, settings_service: SettingsService):\\n        # Here you would have logic to create and configure a CacheService\\n        # based on the settings_service\\n\\n        if settings_service.settings.cache_type == \\\"redis\\\":\\n            logger.debug(\\\"Creating Redis cache\\\")\\n            return RedisCache(\\n                host=settings_service.settings.redis_host,\\n                port=settings_service.settings.redis_port,\\n                db=settings_service.settings.redis_db,\\n                url=settings_service.settings.redis_url,\\n                expiration_time=settings_service.settings.redis_cache_expire,\\n            )\\n\\n        if settings_service.settings.cache_type == \\\"memory\\\":\\n            return ThreadingInMemoryCache(expiration_time=settings_service.settings.cache_expire)\\n        if settings_service.settings.cache_type == \\\"async\\\":\\n            return AsyncInMemoryCache(expiration_time=settings_service.settings.cache_expire)\\n        return None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/cache/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"735e38a5ebd51379ee76961fe2b27bd122fc55da6c94266f73b35b0acf911946\",\"content\":\"import asyncio\\nimport atexit\\nimport hashlib\\nimport hmac\\nimport os\\nimport pickle\\nimport tempfile\\nimport threading\\nimport time\\nfrom collections import OrderedDict\\nfrom pathlib import Path\\nfrom typing import Generic, Union\\n\\nimport dill\\nfrom lfx.log.logger import logger\\nfrom lfx.services.cache.utils import CACHE_MISS\\nfrom typing_extensions import override\\n\\nfrom langflow.services.cache.base import (\\n    AsyncBaseCacheService,\\n    AsyncLockType,\\n    CacheService,\\n    ExternalAsyncBaseCacheService,\\n    LockType,\\n)\\n\\n_redis_cache_experimental_warning_lock = threading.Lock()\\n_redis_cache_experimental_warning_emitted = False\\n\\n\\ndef _warn_redis_experimental_once() -> None:\\n    \\\"\\\"\\\"Emit the RedisCache experimental warning only once per server run.\\\"\\\"\\\"\\n    global _redis_cache_experimental_warning_emitted  # noqa: PLW0603\\n\\n    with _redis_cache_experimental_warning_lock:\\n        if _redis_cache_experimental_warning_emitted:\\n            return\\n        _redis_cache_experimental_warning_emitted = True\\n\\n    # Cross-process deduplication: all workers forked from the same master\\n    # share the same getppid() value, so they all target the same sentinel.\\n    sentinel = Path(tempfile.gettempdir()) / f\\\"langflow_redis_cache_warned_{os.getppid()}.sentinel\\\"\\n    try:\\n        fd = os.open(sentinel, os.O_CREAT | os.O_EXCL | os.O_WRONLY)\\n        os.close(fd)\\n    except FileExistsError:\\n        return  # Another worker already logged the warning\\n\\n    # Best-effort cleanup so we don't leave a stale file in /tmp after every restart.\\n    atexit.register(sentinel.unlink, missing_ok=True)\\n\\n    logger.warning(\\n        \\\"RedisCache is an experimental feature and may not work as expected.\\\"\\n        \\\" Please report any issues to our GitHub repository.\\\"\\n    )\\n\\n\\nclass ThreadingInMemoryCache(CacheService, Generic[LockType]):\\n    \\\"\\\"\\\"A simple in-memory cache using an OrderedDict.\\n\\n    This cache supports setting a maximum size and expiration time for cached items.\\n    When the cache is full, it uses a Least Recently Used (LRU) eviction policy.\\n    Thread-safe using a threading Lock.\\n\\n    Attributes:\\n        max_size (int, optional): Maximum number of items to store in the cache.\\n        expiration_time (int, optional): Time in seconds after which a cached item expires. Default is 1 hour.\\n\\n    Example:\\n        cache = InMemoryCache(max_size=3, expiration_time=5)\\n\\n        # setting cache values\\n        cache.set(\\\"a\\\", 1)\\n        cache.set(\\\"b\\\", 2)\\n        cache[\\\"c\\\"] = 3\\n\\n        # getting cache values\\n        a = cache.get(\\\"a\\\")\\n        b = cache[\\\"b\\\"]\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, max_size=None, expiration_time=60 * 60) -> None:\\n        \\\"\\\"\\\"Initialize a new InMemoryCache instance.\\n\\n        Args:\\n            max_size (int, optional): Maximum number of items to store in the cache.\\n            expiration_time (int, optional): Time in seconds after which a cached item expires. Default is 1 hour.\\n        \\\"\\\"\\\"\\n        self._cache: OrderedDict = OrderedDict()\\n        self._lock = threading.RLock()\\n        self.max_size = max_size\\n        self.expiration_time = expiration_time\\n\\n    def get(self, key, lock: Union[threading.Lock, None] = None):  # noqa: UP007\\n        \\\"\\\"\\\"Retrieve an item from the cache.\\n\\n        Args:\\n            key: The key of the item to retrieve.\\n            lock: A lock to use for the operation.\\n\\n        Returns:\\n            The value associated with the key, or CACHE_MISS if the key is not found or the item has expired.\\n        \\\"\\\"\\\"\\n        with lock or self._lock:\\n            return self._get_without_lock(key)\\n\\n    def _get_without_lock(self, key):\\n        \\\"\\\"\\\"Retrieve an item from the cache without acquiring the lock.\\\"\\\"\\\"\\n        if item := self._cache.get(key):\\n            if self.expiration_time is None or time.time() - item[\\\"time\\\"] < self.expiration_time:\\n                # Move the key to the end to make it recently used\\n                self._cache.move_to_end(key)\\n                # Check if the value is pickled\\n                return pickle.loads(item[\\\"value\\\"]) if isinstance(item[\\\"value\\\"], bytes) else item[\\\"value\\\"]\\n            self.delete(key)\\n        return CACHE_MISS\\n\\n    def set(self, key, value, lock: Union[threading.Lock, None] = None) -> None:  # noqa: UP007\\n        \\\"\\\"\\\"Add an item to the cache.\\n\\n        If the cache is full, the least recently used item is evicted.\\n\\n        Args:\\n            key: The key of the item.\\n            value: The value to cache.\\n            lock: A lock to use for the operation.\\n        \\\"\\\"\\\"\\n        with lock or self._lock:\\n            if key in self._cache:\\n                # Remove existing key before re-inserting to update order\\n                self.delete(key)\\n            elif self.max_size and len(self._cache) >= self.max_size:\\n                # Remove least recently used item\\n                self._cache.popitem(last=False)\\n            # pickle locally to mimic Redis\\n\\n            self._cache[key] = {\\\"value\\\": value, \\\"time\\\": time.time()}\\n\\n    def upsert(self, key, value, lock: Union[threading.Lock, None] = None) -> None:  # noqa: UP007\\n        \\\"\\\"\\\"Inserts or updates a value in the cache.\\n\\n        If the existing value and the new value are both dictionaries, they are merged.\\n\\n        Args:\\n            key: The key of the item.\\n            value: The value to insert or update.\\n            lock: A lock to use for the operation.\\n        \\\"\\\"\\\"\\n        with lock or self._lock:\\n            existing_value = self._get_without_lock(key)\\n            if existing_value is not CACHE_MISS and isinstance(existing_value, dict) and isinstance(value, dict):\\n                existing_value.update(value)\\n                value = existing_value\\n\\n            self.set(key, value)\\n\\n    def get_or_set(self, key, value, lock: Union[threading.Lock, None] = None):  # noqa: UP007\\n        \\\"\\\"\\\"Retrieve an item from the cache.\\n\\n        If the item does not exist, set it with the provided value.\\n\\n        Args:\\n            key: The key of the item.\\n            value: The value to cache if the item doesn't exist.\\n            lock: A lock to use for the operation.\\n\\n        Returns:\\n            The cached value associated with the key.\\n        \\\"\\\"\\\"\\n        with lock or self._lock:\\n            if key in self._cache:\\n                return self.get(key)\\n            self.set(key, value)\\n            return value\\n\\n    def delete(self, key, lock: Union[threading.Lock, None] = None) -> None:  # noqa: UP007\\n        with lock or self._lock:\\n            self._cache.pop(key, None)\\n\\n    def clear(self, lock: Union[threading.Lock, None] = None) -> None:  # noqa: UP007\\n        \\\"\\\"\\\"Clear all items from the cache.\\\"\\\"\\\"\\n        with lock or self._lock:\\n            self._cache.clear()\\n\\n    def contains(self, key) -> bool:\\n        \\\"\\\"\\\"Check if the key is in the cache.\\\"\\\"\\\"\\n        return key in self._cache\\n\\n    def __contains__(self, key) -> bool:\\n        \\\"\\\"\\\"Check if the key is in the cache.\\\"\\\"\\\"\\n        return self.contains(key)\\n\\n    def __getitem__(self, key):\\n        \\\"\\\"\\\"Retrieve an item from the cache using the square bracket notation.\\\"\\\"\\\"\\n        return self.get(key)\\n\\n    def __setitem__(self, key, value) -> None:\\n        \\\"\\\"\\\"Add an item to the cache using the square bracket notation.\\\"\\\"\\\"\\n        self.set(key, value)\\n\\n    def __delitem__(self, key) -> None:\\n        \\\"\\\"\\\"Remove an item from the cache using the square bracket notation.\\\"\\\"\\\"\\n        self.delete(key)\\n\\n    def __len__(self) -> int:\\n        \\\"\\\"\\\"Return the number of items in the cache.\\\"\\\"\\\"\\n        return len(self._cache)\\n\\n    def __repr__(self) -> str:\\n        \\\"\\\"\\\"Return a string representation of the InMemoryCache instance.\\\"\\\"\\\"\\n        return f\\\"InMemoryCache(max_size={self.max_size}, expiration_time={self.expiration_time})\\\"\\n\\n\\nclass RedisCache(ExternalAsyncBaseCacheService, Generic[LockType]):\\n    \\\"\\\"\\\"A Redis-based cache implementation.\\n\\n    This cache supports setting an expiration time for cached items.\\n\\n    Attributes:\\n        expiration_time (int, optional): Time in seconds after which a cached item expires. Default is 1 hour.\\n\\n    Example:\\n        cache = RedisCache(expiration_time=5)\\n\\n        # setting cache values\\n        cache.set(\\\"a\\\", 1)\\n        cache.set(\\\"b\\\", 2)\\n        cache[\\\"c\\\"] = 3\\n\\n        # getting cache values\\n        a = cache.get(\\\"a\\\")\\n        b = cache[\\\"b\\\"]\\n    \\\"\\\"\\\"\\n\\n    KEY_PREFIX = \\\"langflow:cache:\\\"\\n\\n    # Size of the HMAC-SHA256 tag prepended to every stored payload.\\n    _HMAC_DIGEST_SIZE = hashlib.sha256().digest_size\\n\\n    def __init__(self, host=\\\"localhost\\\", port=6379, db=0, url=None, expiration_time=60 * 60) -> None:\\n        \\\"\\\"\\\"Initialize a new RedisCache instance.\\n\\n        Args:\\n            host (str, optional): Redis host.\\n            port (int, optional): Redis port.\\n            db (int, optional): Redis DB.\\n            url (str, optional): Redis URL.\\n            expiration_time (int, optional): Time in seconds after which a\\n                cached item expires. Default is 1 hour.\\n        \\\"\\\"\\\"\\n        # Redis is a main dependency, no need to import check\\n        from redis.asyncio import StrictRedis\\n\\n        _warn_redis_experimental_once()\\n        if url:\\n            self._client = StrictRedis.from_url(url)\\n        else:\\n            self._client = StrictRedis(host=host, port=port, db=db)\\n        self.expiration_time = expiration_time\\n        self._signing_key: bytes | None = None\\n\\n    def _key(self, key) -> str:\\n        \\\"\\\"\\\"Return the namespaced Redis key.\\\"\\\"\\\"\\n        return f\\\"{self.KEY_PREFIX}{key}\\\"\\n\\n    def _get_signing_key(self) -> bytes:\\n        \\\"\\\"\\\"Derive the HMAC key for cache payload integrity from the server secret.\\n\\n        Bound to the same ``SECRET_KEY`` used elsewhere, so no extra config is\\n        required. Cached after first use (the secret does not change at runtime).\\n        \\\"\\\"\\\"\\n        if self._signing_key is None:\\n            from langflow.services.deps import get_settings_service\\n\\n            secret = get_settings_service().auth_settings.SECRET_KEY.get_secret_value()\\n            self._signing_key = hashlib.sha256(b\\\"langflow-redis-cache-hmac:\\\" + secret.encode()).digest()\\n        return self._signing_key\\n\\n    def _integrity_tag(self, namespaced_key: str, payload: bytes) -> bytes:\\n        \\\"\\\"\\\"Compute the HMAC-SHA256 tag binding ``payload`` to ``namespaced_key``.\\n\\n        The Redis key is mixed in as associated authenticated data so a tag is\\n        only valid for the exact key the payload was written under. Without this\\n        binding, a payload signed for one key verifies under any other key,\\n        letting anyone with write access to the ``langflow:cache:`` namespace\\n        relocate/replay a validly-signed entry across keys (cross-key\\n        substitution \u2192 type confusion / stale-value injection) without ever\\n        knowing the secret. The key is length-prefixed so the (key, payload)\\n        framing is unambiguous and bytes cannot be shifted across the boundary\\n        while keeping a valid tag.\\n        \\\"\\\"\\\"\\n        mac = hmac.new(self._get_signing_key(), digestmod=hashlib.sha256)\\n        key_bytes = namespaced_key.encode(\\\"utf-8\\\")\\n        mac.update(len(key_bytes).to_bytes(8, \\\"big\\\"))\\n        mac.update(key_bytes)\\n        mac.update(payload)\\n        return mac.digest()\\n\\n    async def is_connected(self) -> bool:\\n        \\\"\\\"\\\"Check if the Redis client is connected.\\\"\\\"\\\"\\n        import redis\\n\\n        try:\\n            await self._client.ping()\\n        except redis.exceptions.ConnectionError:\\n            msg = \\\"RedisCache could not connect to the Redis server\\\"\\n            await logger.aexception(msg)\\n            return False\\n        return True\\n\\n    @override\\n    async def get(self, key, lock=None):\\n        if key is None:\\n            return CACHE_MISS\\n        namespaced_key = self._key(key)\\n        value = await self._client.get(namespaced_key)\\n        if not value:\\n            return CACHE_MISS\\n        # Integrity check before deserializing. The Redis datastore is an\\n        # untrusted boundary (a co-tenant on a shared Redis, an exposed/un-ACL'd\\n        # port, or anyone able to write under the langflow:cache: namespace could\\n        # plant a payload). dill.loads() executes embedded reduce gadgets, so we\\n        # only deserialize bytes carrying a valid HMAC produced with the server\\n        # secret. Unsigned/tampered/legacy entries are treated as a miss and are\\n        # never passed to dill.loads (CWE-502).\\n        if len(value) < self._HMAC_DIGEST_SIZE:\\n            return CACHE_MISS\\n        tag, payload = value[: self._HMAC_DIGEST_SIZE], value[self._HMAC_DIGEST_SIZE :]\\n        expected = self._integrity_tag(namespaced_key, payload)\\n        if not hmac.compare_digest(tag, expected):\\n            await logger.awarning(\\\"RedisCache: discarding cache entry with an invalid integrity tag\\\")\\n            return CACHE_MISS\\n        return dill.loads(payload)\\n\\n    @override\\n    async def set(self, key, value, lock=None) -> None:\\n        # Serialize first, in isolation from the network write. Live objects built during\\n        # a flow run -- LLM clients holding an ``ssl.SSLContext``, httpx clients, thread\\n        # locks, dynamically-created pydantic models -- are inherently unpicklable, and\\n        # dill signals this with a variety of exception types (a bare ``TypeError`` for an\\n        # SSLContext, ``AttributeError`` for dynamic classes, ``RecursionError`` for deep\\n        # graphs, etc.) -- not only ``pickle.PicklingError``. Failing to serialize must not\\n        # crash the caller (e.g. the vertex build); skip the cache write instead, which\\n        # just means the value is recomputed on the next access. See issue #13764.\\n        try:\\n            pickled = dill.dumps(value, recurse=True)\\n        except Exception as exc:  # noqa: BLE001\\n            await logger.awarning(\\n                f\\\"RedisCache skipping cache for key '{key}': value is not serializable ({type(exc).__name__}: {exc}).\\\"\\n            )\\n            # Drop any previously-cached value for this key. ``upsert`` does\\n            # get -> merge -> set, so leaving an older entry in place would let a\\n            # later get() serve stale data instead of recomputing. (DEL of a\\n            # missing key is a harmless no-op.)\\n            await self._client.delete(self._key(key))\\n            return\\n        if pickled:\\n            # Prefix an HMAC tag so get() can reject tampered/forged payloads\\n            # before deserialization (see get()). The tag is bound to the\\n            # namespaced key so it cannot be replayed under a different key.\\n            namespaced_key = self._key(key)\\n            tag = self._integrity_tag(namespaced_key, pickled)\\n            result = await self._client.setex(namespaced_key, self.expiration_time, tag + pickled)\\n            if not result:\\n                msg = \\\"RedisCache could not set the value.\\\"\\n                raise ValueError(msg)\\n\\n    @override\\n    async def upsert(self, key, value, lock=None) -> None:\\n        \\\"\\\"\\\"Inserts or updates a value in the cache.\\n\\n        If the existing value and the new value are both dictionaries, they are merged.\\n\\n        Args:\\n            key: The key of the item.\\n            value: The value to insert or update.\\n            lock: A lock to use for the operation.\\n        \\\"\\\"\\\"\\n        if key is None:\\n            return\\n        existing_value = await self.get(key)\\n        if existing_value is not None and isinstance(existing_value, dict) and isinstance(value, dict):\\n            existing_value.update(value)\\n            value = existing_value\\n\\n        await self.set(key, value)\\n\\n    @override\\n    async def delete(self, key, lock=None) -> None:\\n        await self._client.delete(self._key(key))\\n\\n    @override\\n    async def clear(self, lock=None) -> None:\\n        \\\"\\\"\\\"Clear all items from the cache using a key-prefix scan to avoid nuking unrelated data.\\\"\\\"\\\"\\n        cursor = 0\\n        pattern = f\\\"{self.KEY_PREFIX}*\\\"\\n        while True:\\n            cursor, keys = await self._client.scan(cursor, match=pattern, count=100)\\n            if keys:\\n                await self._client.delete(*keys)\\n            if cursor == 0:\\n                break\\n\\n    async def contains(self, key) -> bool:\\n        \\\"\\\"\\\"Check if the key is in the cache.\\\"\\\"\\\"\\n        if key is None:\\n            return False\\n        return bool(await self._client.exists(self._key(key)))\\n\\n    @override\\n    async def teardown(self) -> None:\\n        \\\"\\\"\\\"Close the Redis client connection to prevent socket leaks across fork.\\\"\\\"\\\"\\n        await self._client.aclose()\\n\\n    def __repr__(self) -> str:\\n        \\\"\\\"\\\"Return a string representation of the RedisCache instance.\\\"\\\"\\\"\\n        return f\\\"RedisCache(expiration_time={self.expiration_time})\\\"\\n\\n\\nclass AsyncInMemoryCache(AsyncBaseCacheService, Generic[AsyncLockType]):\\n    def __init__(self, max_size=None, expiration_time=3600) -> None:\\n        self.cache: OrderedDict = OrderedDict()\\n\\n        self.lock = asyncio.Lock()\\n        self.max_size = max_size\\n        self.expiration_time = expiration_time\\n\\n    async def get(self, key, lock: asyncio.Lock | None = None):\\n        async with lock or self.lock:\\n            return await self._get(key)\\n\\n    async def _get(self, key):\\n        item = self.cache.get(key, None)\\n        if item:\\n            if time.time() - item[\\\"time\\\"] < self.expiration_time:\\n                self.cache.move_to_end(key)\\n                return pickle.loads(item[\\\"value\\\"]) if isinstance(item[\\\"value\\\"], bytes) else item[\\\"value\\\"]\\n            await logger.ainfo(f\\\"Cache item for key '{key}' has expired and will be deleted.\\\")\\n            await self._delete(key)  # Log before deleting the expired item\\n        return CACHE_MISS\\n\\n    async def set(self, key, value, lock: asyncio.Lock | None = None) -> None:\\n        async with lock or self.lock:\\n            await self._set(\\n                key,\\n                value,\\n            )\\n\\n    async def _set(self, key, value) -> None:\\n        if self.max_size and len(self.cache) >= self.max_size:\\n            self.cache.popitem(last=False)\\n        self.cache[key] = {\\\"value\\\": value, \\\"time\\\": time.time()}\\n        self.cache.move_to_end(key)\\n\\n    async def delete(self, key, lock: asyncio.Lock | None = None) -> None:\\n        async with lock or self.lock:\\n            await self._delete(key)\\n\\n    async def _delete(self, key) -> None:\\n        if key in self.cache:\\n            del self.cache[key]\\n\\n    async def clear(self, lock: asyncio.Lock | None = None) -> None:\\n        async with lock or self.lock:\\n            await self._clear()\\n\\n    async def _clear(self) -> None:\\n        self.cache.clear()\\n\\n    async def upsert(self, key, value, lock: asyncio.Lock | None = None) -> None:\\n        await self._upsert(key, value, lock)\\n\\n    async def _upsert(self, key, value, lock: asyncio.Lock | None = None) -> None:\\n        existing_value = await self.get(key, lock)\\n        if existing_value is not None and isinstance(existing_value, dict) and isinstance(value, dict):\\n            existing_value.update(value)\\n            value = existing_value\\n        await self.set(key, value, lock)\\n\\n    async def contains(self, key) -> bool:\\n        return key in self.cache\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/cache/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3ef863216cff67833e832a23ac067c688c051e1a05d988be1a04d683b01e6f25\",\"content\":\"import base64\\nimport contextlib\\nimport hashlib\\nimport tempfile\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom fastapi import UploadFile\\nfrom platformdirs import user_cache_dir\\n\\nif TYPE_CHECKING:\\n    from langflow.api.v1.schemas import BuildStatus\\n\\nCACHE: dict[str, Any] = {}\\n\\nCACHE_DIR = user_cache_dir(\\\"langflow\\\", \\\"langflow\\\")\\n\\nPREFIX = \\\"langflow_cache\\\"\\n\\n\\ndef create_cache_folder(func):\\n    def wrapper(*args, **kwargs):\\n        # Get the destination folder\\n        cache_path = Path(CACHE_DIR) / PREFIX\\n\\n        # Create the destination folder if it doesn't exist\\n        cache_path.mkdir(parents=True, exist_ok=True)\\n\\n        return func(*args, **kwargs)\\n\\n    return wrapper\\n\\n\\n@create_cache_folder\\ndef clear_old_cache_files(max_cache_size: int = 3) -> None:\\n    cache_dir = Path(tempfile.gettempdir()) / PREFIX\\n    cache_files = list(cache_dir.glob(\\\"*.dill\\\"))\\n\\n    if len(cache_files) > max_cache_size:\\n        cache_files_sorted_by_mtime = sorted(cache_files, key=lambda x: x.stat().st_mtime, reverse=True)\\n\\n        for cache_file in cache_files_sorted_by_mtime[max_cache_size:]:\\n            with contextlib.suppress(OSError):\\n                cache_file.unlink()\\n\\n\\ndef filter_json(json_data):\\n    filtered_data = json_data.copy()\\n\\n    # Remove 'viewport' and 'chatHistory' keys\\n    if \\\"viewport\\\" in filtered_data:\\n        del filtered_data[\\\"viewport\\\"]\\n    if \\\"chatHistory\\\" in filtered_data:\\n        del filtered_data[\\\"chatHistory\\\"]\\n\\n    # Filter nodes\\n    if \\\"nodes\\\" in filtered_data:\\n        for node in filtered_data[\\\"nodes\\\"]:\\n            if \\\"position\\\" in node:\\n                del node[\\\"position\\\"]\\n            if \\\"positionAbsolute\\\" in node:\\n                del node[\\\"positionAbsolute\\\"]\\n            if \\\"selected\\\" in node:\\n                del node[\\\"selected\\\"]\\n            if \\\"dragging\\\" in node:\\n                del node[\\\"dragging\\\"]\\n\\n    return filtered_data\\n\\n\\n@create_cache_folder\\ndef save_binary_file(content: str, file_name: str, accepted_types: list[str]) -> str:\\n    \\\"\\\"\\\"Save a binary file to the specified folder.\\n\\n    Args:\\n        content: The content of the file as a bytes object.\\n        file_name: The name of the file, including its extension.\\n        accepted_types: A list of accepted file types.\\n\\n    Returns:\\n        The path to the saved file.\\n    \\\"\\\"\\\"\\n    if not any(file_name.endswith(suffix) for suffix in accepted_types):\\n        msg = f\\\"File {file_name} is not accepted\\\"\\n        raise ValueError(msg)\\n\\n    # Get the destination folder\\n    cache_path = Path(CACHE_DIR) / PREFIX\\n    if not content:\\n        msg = \\\"Please, reload the file in the loader.\\\"\\n        raise ValueError(msg)\\n    data = content.split(\\\",\\\")[1]\\n    decoded_bytes = base64.b64decode(data)\\n\\n    # Create the full file path\\n    file_path = cache_path / file_name\\n\\n    # Save the binary content to the file\\n    file_path.write_bytes(decoded_bytes)\\n\\n    return str(file_path)\\n\\n\\n@create_cache_folder\\ndef save_uploaded_file(file: UploadFile, folder_name):\\n    \\\"\\\"\\\"Save an uploaded file to the specified folder with a hash of its content as the file name.\\n\\n    Args:\\n        file: The uploaded file object.\\n        folder_name: The name of the folder to save the file in.\\n\\n    Returns:\\n        The path to the saved file.\\n    \\\"\\\"\\\"\\n    cache_path = Path(CACHE_DIR)\\n    folder_path = cache_path / folder_name\\n    filename = file.filename\\n    file_extension = Path(filename).suffix if isinstance(filename, str | Path) else \\\"\\\"\\n    file_object = file.file\\n\\n    # Create the folder if it doesn't exist\\n    if not folder_path.exists():\\n        folder_path.mkdir()\\n\\n    # Create a hash of the file content\\n    sha256_hash = hashlib.sha256()\\n    # Reset the file cursor to the beginning of the file\\n    file_object.seek(0)\\n    # Iterate over the uploaded file in small chunks to conserve memory\\n    while chunk := file_object.read(8192):  # Read 8KB at a time (adjust as needed)\\n        sha256_hash.update(chunk)\\n\\n    # Use the hex digest of the hash as the file name\\n    hex_dig = sha256_hash.hexdigest()\\n    file_name = f\\\"{hex_dig}{file_extension}\\\"\\n\\n    # Reset the file cursor to the beginning of the file\\n    file_object.seek(0)\\n\\n    # Save the file with the hash as its name\\n    file_path = folder_path / file_name\\n\\n    with file_path.open(\\\"wb\\\") as new_file:\\n        while chunk := file_object.read(8192):\\n            new_file.write(chunk)\\n\\n    return file_path\\n\\n\\ndef update_build_status(cache_service, flow_id: str, status: \\\"BuildStatus\\\") -> None:\\n    cached_flow = cache_service[flow_id]\\n    if cached_flow is None:\\n        msg = f\\\"Flow {flow_id} not found in cache\\\"\\n        raise ValueError(msg)\\n    cached_flow[\\\"status\\\"] = status\\n    cache_service[flow_id] = cached_flow\\n    cached_flow[\\\"status\\\"] = status\\n    cache_service[flow_id] = cached_flow\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/catalog_policy/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c729ad210a1e003a0bc7aea5568b92c46d3fb121a10366dc0b7e5d82d30d89cf\",\"content\":\"\\\"\\\"\\\"Langflow catalog-policy service.\\\"\\\"\\\"\\n\\nfrom langflow.services.catalog_policy.service import LangflowCatalogPolicyService\\n\\n__all__ = [\\\"LangflowCatalogPolicyService\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/catalog_policy/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7d311045279c3787055ea47fdcee048b30adfaa3d2fa1520567418e249d81601\",\"content\":\"\\\"\\\"\\\"Catalog-policy service factory.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom langflow.services.factory import ServiceFactory\\nfrom langflow.services.schema import ServiceType\\n\\nif TYPE_CHECKING:\\n    from lfx.services.catalog_policy import BaseCatalogPolicyService\\n\\n    from langflow.services.catalog_policy.service import LangflowCatalogPolicyService\\n    from langflow.services.database.service import DatabaseService\\n\\n\\nclass CatalogPolicyServiceFactory(ServiceFactory):\\n    \\\"\\\"\\\"Create the Langflow database-backed catalog-policy service.\\\"\\\"\\\"\\n\\n    name = ServiceType.CATALOG_POLICY_SERVICE.value\\n\\n    service_class: type[LangflowCatalogPolicyService]\\n\\n    def __init__(self) -> None:\\n        from langflow.services.catalog_policy.service import LangflowCatalogPolicyService\\n\\n        super().__init__(LangflowCatalogPolicyService)\\n\\n    def create(self, database_service: DatabaseService) -> BaseCatalogPolicyService:\\n        \\\"\\\"\\\"Build a catalog-policy service using the injected database service.\\\"\\\"\\\"\\n        from lfx.services.deps import get_policy_bundle_service\\n\\n        return self.service_class(database_service, get_policy_bundle_service())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/catalog_policy/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2a345feb0881be7933e360ffc17a57fbf16c38ff4c96a92fbd1a5a6df7af6982\",\"content\":\"\\\"\\\"\\\"Database-backed catalog-policy service.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.services.catalog_policy import BaseCatalogPolicyService, CatalogPolicySnapshot, CatalogPolicyUpdate\\nfrom lfx.services.deps import session_scope, session_scope_readonly\\nfrom lfx.services.policy_bundle import BasePolicyBundleService, PolicyBundleSnapshot\\nfrom lfx.services.schema import ServiceType\\nfrom sqlmodel import col, select\\n\\nfrom langflow.services.database.models.catalog_policy import (\\n    CatalogPolicyMode,\\n    CatalogPolicyRule,\\n    CatalogPolicyScope,\\n    CatalogResourceKind,\\n)\\nfrom langflow.services.policy_bundle import (\\n    PolicyBundleRevisionConflictError,\\n    apply_policy_bundle_state,\\n    get_policy_bundle_state,\\n    replace_policy_bundle_state,\\n)\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Collection\\n    from uuid import UUID\\n\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n    from langflow.services.database.service import DatabaseService\\n\\n\\n_CATALOG_POLICY_CAS_ATTEMPTS = 3\\n\\n\\ndef _normalize_keys(keys: Collection[str]) -> frozenset[str]:\\n    \\\"\\\"\\\"Trim and deduplicate keys while preserving their case.\\\"\\\"\\\"\\n    normalized: set[str] = set()\\n    for raw_key in keys:\\n        key = raw_key.strip()\\n        if not key:\\n            msg = \\\"Catalog policy keys must not be empty\\\"\\n            raise ValueError(msg)\\n        normalized.add(key)\\n    return frozenset(normalized)\\n\\n\\nclass LangflowCatalogPolicyService(BaseCatalogPolicyService):\\n    \\\"\\\"\\\"Catalog projection of the process-wide immutable policy bundle.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        database_service: DatabaseService | None,\\n        policy_bundle_service: BasePolicyBundleService | None = None,\\n    ) -> None:\\n        super().__init__()\\n        self.database_service = database_service\\n        self._policy_bundle_service = policy_bundle_service\\n        self._legacy_snapshot = CatalogPolicySnapshot()\\n        self._legacy_hydrated = False\\n        self._projected_snapshot: tuple[PolicyBundleSnapshot, CatalogPolicySnapshot] | None = None\\n        self._write_lock = asyncio.Lock()\\n        # Direct service-class registration does not call set_ready(), unlike\\n        # factory creation. The fail-open snapshot is usable immediately.\\n        self.set_ready()\\n\\n    @property\\n    def name(self) -> str:\\n        \\\"\\\"\\\"Return the canonical service-type name.\\\"\\\"\\\"\\n        return ServiceType.CATALOG_POLICY_SERVICE.value\\n\\n    @property\\n    def snapshot(self) -> CatalogPolicySnapshot:\\n        \\\"\\\"\\\"Return the current immutable process-local snapshot.\\\"\\\"\\\"\\n        if self._policy_bundle_service is None:\\n            return self._legacy_snapshot\\n        bundle = self._policy_bundle_service.snapshot\\n        projected = self._projected_snapshot\\n        if projected is None or projected[0] is not bundle:\\n            projected = (\\n                bundle,\\n                CatalogPolicySnapshot(\\n                    blocked_component_keys=bundle.blocked_component_keys,\\n                    blocked_template_keys=bundle.blocked_template_keys,\\n                ),\\n            )\\n            self._projected_snapshot = projected\\n        return projected[1]\\n\\n    @property\\n    def policy_bundle_snapshot(self) -> PolicyBundleSnapshot:\\n        if self._policy_bundle_service is None:\\n            return PolicyBundleSnapshot(\\n                blocked_component_keys=self._legacy_snapshot.blocked_component_keys,\\n                blocked_template_keys=self._legacy_snapshot.blocked_template_keys,\\n            )\\n        return self._policy_bundle_service.snapshot\\n\\n    @property\\n    def supports_policy_bundle_updates(self) -> bool:\\n        return self._policy_bundle_service is not None\\n\\n    def apply_policy_bundle(self, snapshot: PolicyBundleSnapshot) -> bool:\\n        if self._policy_bundle_service is None:\\n            return False\\n        return self._policy_bundle_service.publish(snapshot)\\n\\n    @property\\n    def hydrated(self) -> bool:\\n        \\\"\\\"\\\"Return whether durable policy has been loaded successfully.\\\"\\\"\\\"\\n        if self._policy_bundle_service is None:\\n            return self._legacy_hydrated\\n        return self._policy_bundle_service.hydrated\\n\\n    async def hydrate(self) -> CatalogPolicySnapshot:\\n        \\\"\\\"\\\"Load global block rules and atomically publish a complete snapshot.\\n\\n        A failed load leaves the previous snapshot untouched. Callers may log\\n        the failure and continue with its fail-open decision surface.\\n        \\\"\\\"\\\"\\n        async with self._write_lock:\\n            if self._policy_bundle_service is None:\\n                async with session_scope_readonly() as session:\\n                    snapshot, _rows = await self._read_policy(session)\\n                self._legacy_snapshot = snapshot\\n                self._legacy_hydrated = True\\n                return snapshot\\n\\n            async with session_scope_readonly() as session:\\n                bundle = await get_policy_bundle_state(session)\\n            apply_policy_bundle_state(bundle)\\n            return self.snapshot\\n\\n    async def replace_blocked_component_keys(\\n        self,\\n        keys: Collection[str],\\n        *,\\n        actor_user_id: UUID | None,\\n    ) -> CatalogPolicyUpdate:\\n        \\\"\\\"\\\"Replace the global component block set and publish it after commit.\\\"\\\"\\\"\\n        return await self._replace_blocked_keys(\\n            CatalogResourceKind.COMPONENT,\\n            keys,\\n            actor_user_id=actor_user_id,\\n        )\\n\\n    async def replace_blocked_template_keys(\\n        self,\\n        keys: Collection[str],\\n        *,\\n        actor_user_id: UUID | None,\\n    ) -> CatalogPolicyUpdate:\\n        \\\"\\\"\\\"Replace the global template block set and publish it after commit.\\\"\\\"\\\"\\n        return await self._replace_blocked_keys(\\n            CatalogResourceKind.TEMPLATE,\\n            keys,\\n            actor_user_id=actor_user_id,\\n        )\\n\\n    async def _replace_blocked_keys(\\n        self,\\n        resource_kind: CatalogResourceKind,\\n        keys: Collection[str],\\n        *,\\n        actor_user_id: UUID | None,\\n    ) -> CatalogPolicyUpdate:\\n        desired = _normalize_keys(keys)\\n\\n        async with self._write_lock:\\n            if self._policy_bundle_service is None:\\n                return await self._replace_legacy_blocked_keys(\\n                    resource_kind,\\n                    desired,\\n                    actor_user_id=actor_user_id,\\n                )\\n\\n            for attempt in range(_CATALOG_POLICY_CAS_ATTEMPTS):\\n                async with session_scope() as session:\\n                    current = await get_policy_bundle_state(session)\\n                    if resource_kind == CatalogResourceKind.COMPONENT:\\n                        current_keys = current.blocked_component_keys\\n                        components = desired\\n                        templates = current.blocked_template_keys\\n                    else:\\n                        current_keys = current.blocked_template_keys\\n                        components = current.blocked_component_keys\\n                        templates = desired\\n                    try:\\n                        committed = await replace_policy_bundle_state(\\n                            session,\\n                            expected_revision=current.revision,\\n                            approved_provider_ids=current.approved_provider_ids,\\n                            blocked_component_keys=components,\\n                            blocked_template_keys=templates,\\n                            blocked_model_keys=current.blocked_model_keys,\\n                            actor_user_id=actor_user_id,\\n                            reason=f\\\"Replace blocked {resource_kind.value} catalog keys\\\",\\n                        )\\n                    except PolicyBundleRevisionConflictError:\\n                        if attempt == _CATALOG_POLICY_CAS_ATTEMPTS - 1:\\n                            raise\\n                        continue\\n                    break\\n\\n            apply_policy_bundle_state(committed)\\n            return CatalogPolicyUpdate(\\n                snapshot=CatalogPolicySnapshot(\\n                    blocked_component_keys=committed.blocked_component_keys,\\n                    blocked_template_keys=committed.blocked_template_keys,\\n                ),\\n                added=desired - current_keys,\\n                removed=current_keys - desired,\\n            )\\n\\n    async def _replace_legacy_blocked_keys(\\n        self,\\n        resource_kind: CatalogResourceKind,\\n        desired: frozenset[str],\\n        *,\\n        actor_user_id: UUID | None,\\n    ) -> CatalogPolicyUpdate:\\n        \\\"\\\"\\\"Preserve the pre-bundle service seam for direct/plugin construction.\\\"\\\"\\\"\\n        async with session_scope() as session:\\n            current_snapshot, rows = await self._read_policy(session)\\n            current_rows = {row.resource_key: row for row in rows if row.resource_kind == resource_kind.value}\\n            current = frozenset(current_rows)\\n            added = desired - current\\n            removed = current - desired\\n\\n            for key in removed:\\n                await session.delete(current_rows[key])\\n            for key in added:\\n                session.add(\\n                    CatalogPolicyRule(\\n                        resource_kind=resource_kind.value,\\n                        resource_key=key,\\n                        mode=CatalogPolicyMode.BLOCK.value,\\n                        scope=CatalogPolicyScope.GLOBAL.value,\\n                        domain_id=None,\\n                        created_by=actor_user_id,\\n                    )\\n                )\\n\\n        if resource_kind == CatalogResourceKind.COMPONENT:\\n            committed_snapshot = CatalogPolicySnapshot(\\n                blocked_component_keys=desired,\\n                blocked_template_keys=current_snapshot.blocked_template_keys,\\n            )\\n        else:\\n            committed_snapshot = CatalogPolicySnapshot(\\n                blocked_component_keys=current_snapshot.blocked_component_keys,\\n                blocked_template_keys=desired,\\n            )\\n\\n        self._legacy_snapshot = committed_snapshot\\n        self._legacy_hydrated = True\\n        return CatalogPolicyUpdate(\\n            snapshot=committed_snapshot,\\n            added=frozenset(added),\\n            removed=frozenset(removed),\\n        )\\n\\n    @staticmethod\\n    async def _read_policy(\\n        session: AsyncSession,\\n    ) -> tuple[CatalogPolicySnapshot, list[CatalogPolicyRule]]:\\n        stmt = select(CatalogPolicyRule).where(\\n            CatalogPolicyRule.mode == CatalogPolicyMode.BLOCK.value,\\n            CatalogPolicyRule.scope == CatalogPolicyScope.GLOBAL.value,\\n            col(CatalogPolicyRule.domain_id).is_(None),\\n        )\\n        rows = list((await session.exec(stmt)).all())\\n        return (\\n            CatalogPolicySnapshot(\\n                blocked_component_keys=frozenset(\\n                    row.resource_key for row in rows if row.resource_kind == CatalogResourceKind.COMPONENT.value\\n                ),\\n                blocked_template_keys=frozenset(\\n                    row.resource_key for row in rows if row.resource_kind == CatalogResourceKind.TEMPLATE.value\\n                ),\\n            ),\\n            rows,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/chat/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/chat/cache.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d652eb4218786c3442a697779c3486ce8134b42ebbfa9b7684f621dbcdb7e202\",\"content\":\"from collections.abc import Awaitable, Callable\\nfrom contextlib import contextmanager\\nfrom typing import Any\\n\\nimport pandas as pd\\nfrom PIL import Image\\n\\nfrom langflow.services.base import Service\\n\\n\\nclass Subject:\\n    \\\"\\\"\\\"Base class for implementing the observer pattern.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        self.observers: list[Callable[[], None]] = []\\n\\n    def attach(self, observer: Callable[[], None]) -> None:\\n        \\\"\\\"\\\"Attach an observer to the subject.\\\"\\\"\\\"\\n        self.observers.append(observer)\\n\\n    def detach(self, observer: Callable[[], None]) -> None:\\n        \\\"\\\"\\\"Detach an observer from the subject.\\\"\\\"\\\"\\n        self.observers.remove(observer)\\n\\n    def notify(self) -> None:\\n        \\\"\\\"\\\"Notify all observers about an event.\\\"\\\"\\\"\\n        for observer in self.observers:\\n            if observer is None:\\n                continue\\n            observer()\\n\\n\\nclass AsyncSubject:\\n    \\\"\\\"\\\"Base class for implementing the async observer pattern.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        self.observers: list[Callable[[], Awaitable]] = []\\n\\n    def attach(self, observer: Callable[[], Awaitable]) -> None:\\n        \\\"\\\"\\\"Attach an observer to the subject.\\\"\\\"\\\"\\n        self.observers.append(observer)\\n\\n    def detach(self, observer: Callable[[], Awaitable]) -> None:\\n        \\\"\\\"\\\"Detach an observer from the subject.\\\"\\\"\\\"\\n        self.observers.remove(observer)\\n\\n    async def notify(self) -> None:\\n        \\\"\\\"\\\"Notify all observers about an event.\\\"\\\"\\\"\\n        for observer in self.observers:\\n            if observer is None:\\n                continue\\n            await observer()\\n\\n\\nclass CacheService(Subject, Service):\\n    \\\"\\\"\\\"Manages cache for different clients and notifies observers on changes.\\\"\\\"\\\"\\n\\n    name = \\\"cache_service\\\"\\n\\n    def __init__(self) -> None:\\n        super().__init__()\\n        self._cache: dict[str, Any] = {}\\n        self.current_client_id: str | None = None\\n        self.current_cache: dict[str, Any] = {}\\n\\n    @contextmanager\\n    def set_client_id(self, client_id: str):\\n        \\\"\\\"\\\"Context manager to set the current client_id and associated cache.\\n\\n        Args:\\n            client_id (str): The client identifier.\\n        \\\"\\\"\\\"\\n        previous_client_id = self.current_client_id\\n        self.current_client_id = client_id\\n        self.current_cache = self._cache.setdefault(client_id, {})\\n        try:\\n            yield\\n        finally:\\n            self.current_client_id = previous_client_id\\n            self.current_cache = self._cache.setdefault(previous_client_id, {}) if previous_client_id else {}\\n\\n    def add(self, name: str, obj: Any, obj_type: str, extension: str | None = None) -> None:\\n        \\\"\\\"\\\"Add an object to the current client's cache.\\n\\n        Args:\\n            name (str): The cache key.\\n            obj (Any): The object to cache.\\n            obj_type (str): The type of the object.\\n            extension: The file extension of the object.\\n        \\\"\\\"\\\"\\n        object_extensions = {\\n            \\\"image\\\": \\\"png\\\",\\n            \\\"pandas\\\": \\\"csv\\\",\\n        }\\n        extension_ = object_extensions[obj_type] if obj_type in object_extensions else type(obj).__name__.lower()\\n        self.current_cache[name] = {\\n            \\\"obj\\\": obj,\\n            \\\"type\\\": obj_type,\\n            \\\"extension\\\": extension or extension_,\\n        }\\n        self.notify()\\n\\n    def add_pandas(self, name: str, obj: Any) -> None:\\n        \\\"\\\"\\\"Add a pandas DataFrame or Series to the current client's cache.\\n\\n        Args:\\n            name (str): The cache key.\\n            obj (Any): The pandas DataFrame or Series object.\\n        \\\"\\\"\\\"\\n        if isinstance(obj, pd.DataFrame | pd.Series):\\n            self.add(name, obj.to_csv(), \\\"pandas\\\", extension=\\\"csv\\\")\\n        else:\\n            msg = \\\"Object is not a pandas DataFrame or Series\\\"\\n            raise TypeError(msg)\\n\\n    def add_image(self, name: str, obj: Any, extension: str = \\\"png\\\") -> None:\\n        \\\"\\\"\\\"Add a PIL Image to the current client's cache.\\n\\n        Args:\\n            name (str): The cache key.\\n            obj (Any): The PIL Image object.\\n            extension: The file extension of the image.\\n        \\\"\\\"\\\"\\n        if isinstance(obj, Image.Image):\\n            self.add(name, obj, \\\"image\\\", extension=extension)\\n        else:\\n            msg = \\\"Object is not a PIL Image\\\"\\n            raise TypeError(msg)\\n\\n    def get(self, name: str):\\n        \\\"\\\"\\\"Get an object from the current client's cache.\\n\\n        Args:\\n            name (str): The cache key.\\n\\n        Returns:\\n            The cached object associated with the given cache key.\\n        \\\"\\\"\\\"\\n        return self.current_cache[name]\\n\\n    def get_last(self):\\n        \\\"\\\"\\\"Get the last added item in the current client's cache.\\n\\n        Returns:\\n            The last added item in the cache.\\n        \\\"\\\"\\\"\\n        return list(self.current_cache.values())[-1]\\n\\n\\ncache_service = CacheService()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/chat/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a819439cdbeb40fb14c76c34f09c8481a7b9912bb70732606f775b6dc66a8736\",\"content\":\"from langflow.services.chat.service import ChatService\\nfrom langflow.services.factory import ServiceFactory\\n\\n\\nclass ChatServiceFactory(ServiceFactory):\\n    def __init__(self) -> None:\\n        super().__init__(ChatService)\\n\\n    def create(self):\\n        # Here you would have logic to create and configure a ChatService\\n        return ChatService()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/chat/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"307ab9a3769d0222d922947c3b1336bc493146612d654448bef07d4b8fa95e87\",\"content\":\"import asyncio\\nfrom typing import Any, Protocol\\n\\n\\nclass GetCache(Protocol):\\n    async def __call__(self, key: str, lock: asyncio.Lock | None = None) -> Any: ...\\n\\n\\nclass SetCache(Protocol):\\n    async def __call__(self, key: str, data: Any, lock: asyncio.Lock | None = None) -> bool: ...\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/chat/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"09e7ece63d22dceb4ade6f991e2d48e9dbd0853394449a62c3b3bddf59f99e34\",\"content\":\"import asyncio\\nfrom collections import defaultdict\\nfrom threading import RLock\\nfrom typing import Any\\n\\nfrom langflow.services.base import Service\\nfrom langflow.services.cache.base import AsyncBaseCacheService, CacheService\\nfrom langflow.services.deps import get_cache_service\\n\\n\\nclass ChatService(Service):\\n    \\\"\\\"\\\"Service class for managing chat-related operations.\\\"\\\"\\\"\\n\\n    name = \\\"chat_service\\\"\\n\\n    def __init__(self) -> None:\\n        self.async_cache_locks: dict[str, asyncio.Lock] = defaultdict(asyncio.Lock)\\n        self._sync_cache_locks: dict[str, RLock] = defaultdict(RLock)\\n        self.cache_service: CacheService | AsyncBaseCacheService = get_cache_service()\\n\\n    async def set_cache(self, key: str, data: Any, lock: asyncio.Lock | None = None) -> bool:\\n        \\\"\\\"\\\"Set the cache for a client.\\n\\n        Args:\\n            key (str): The cache key.\\n            data (Any): The data to be cached.\\n            lock (Optional[asyncio.Lock], optional): The lock to use for the cache operation. Defaults to None.\\n\\n        Returns:\\n            bool: True if the cache was set successfully, False otherwise.\\n        \\\"\\\"\\\"\\n        result_dict = {\\n            \\\"result\\\": data,\\n            \\\"type\\\": type(data),\\n        }\\n        if isinstance(self.cache_service, AsyncBaseCacheService):\\n            await self.cache_service.upsert(str(key), result_dict, lock=lock or self.async_cache_locks[key])\\n            return await self.cache_service.contains(key)\\n        await asyncio.to_thread(\\n            self.cache_service.upsert, str(key), result_dict, lock=lock or self._sync_cache_locks[key]\\n        )\\n        return key in self.cache_service\\n\\n    async def get_cache(self, key: str, lock: asyncio.Lock | None = None) -> Any:\\n        \\\"\\\"\\\"Get the cache for a client.\\n\\n        Args:\\n            key (str): The cache key.\\n            lock (Optional[asyncio.Lock], optional): The lock to use for the cache operation. Defaults to None.\\n\\n        Returns:\\n            Any: The cached data.\\n        \\\"\\\"\\\"\\n        if isinstance(self.cache_service, AsyncBaseCacheService):\\n            return await self.cache_service.get(key, lock=lock or self.async_cache_locks[key])\\n        return await asyncio.to_thread(self.cache_service.get, key, lock=lock or self._sync_cache_locks[key])\\n\\n    async def clear_cache(self, key: str, lock: asyncio.Lock | None = None) -> None:\\n        \\\"\\\"\\\"Clear the cache for a client.\\n\\n        Args:\\n            key (str): The cache key.\\n            lock (Optional[asyncio.Lock], optional): The lock to use for the cache operation. Defaults to None.\\n        \\\"\\\"\\\"\\n        if isinstance(self.cache_service, AsyncBaseCacheService):\\n            return await self.cache_service.delete(key, lock=lock or self.async_cache_locks[key])\\n        return await asyncio.to_thread(self.cache_service.delete, key, lock=lock or self._sync_cache_locks[key])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/checkpoint/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a7a0b46a31549c2a8d806c75092caae6f8d0ea46f25aa0e929ff8f522e95d2b3\",\"content\":\"from langflow.services.checkpoint.store import JobScopedCheckpointStore\\n\\n__all__ = [\\\"JobScopedCheckpointStore\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/checkpoint/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"98e2d35a4632e56c89b90ffed9e9056ebb159a0f03139b4a1e6ddfe806756480\",\"content\":\"\\\"\\\"\\\"Factory for the durable JobScopedCheckpointStore (LE-1441).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom typing_extensions import override\\n\\nfrom langflow.services.checkpoint.store import JobScopedCheckpointStore\\nfrom langflow.services.factory import ServiceFactory\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.service import SettingsService\\n\\n\\nclass CheckpointServiceFactory(ServiceFactory):\\n    def __init__(self) -> None:\\n        super().__init__(JobScopedCheckpointStore)\\n\\n    @override\\n    def create(self, settings_service: SettingsService):\\n        from langflow.services.jobs.service import JobService\\n\\n        return JobScopedCheckpointStore(JobService())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/checkpoint/store.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"65c5eccba9498858deec9adea1f8066e3c76794a9f1abd6783c50741d1ebc853\",\"content\":\"\\\"\\\"\\\"Durable, job-scoped graph CheckpointStore (LE-1441).\\n\\nPersists a paused graph's ``GraphCheckpoint`` through the ``JobService``\\ncheckpoint helper (one JSON row per ``(job_id, \\\"graph\\\")``), so a checkpoint\\nsurvives a process restart. The in-memory store (LE-1440) stays the standalone\\ndefault; this is wired as ``CHECKPOINT_SERVICE`` inside the running app.\\n\\nResume resolves a checkpoint by ``load_by_run_id`` only: the run id carries the\\njob id, so it reads the one job-scoped row directly. The other ``CheckpointStore``\\nlookups (``load``/``delete`` by checkpoint id, ``list_by_session``) would have to\\nscan every job's row \u2014 there is no per-row user id and no request user to filter\\non \u2014 so they raise ``NotImplementedError`` rather than risk a silent cross-user\\nscan if ever wired onto a request. The in-memory store keeps them for standalone.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING\\nfrom uuid import UUID\\n\\nfrom lfx.graph.checkpoint.schema import GraphCheckpoint\\nfrom lfx.graph.checkpoint.store import CheckpointStore\\nfrom lfx.services.base import Service\\nfrom pydantic import ValidationError\\n\\nif TYPE_CHECKING:\\n    from langflow.services.jobs.service import JobService\\n\\n_KIND = \\\"graph\\\"\\n\\n_SCAN_UNSUPPORTED = (\\n    \\\"JobScopedCheckpointStore.{method} is unsupported: it would scan checkpoints across all \\\"\\n    \\\"jobs/users (not tenant-scoped). The durable resume path uses load_by_run_id (job-scoped).\\\"\\n)\\n\\n\\ndef _expired(checkpoint: GraphCheckpoint) -> bool:\\n    return checkpoint.expires_at is not None and checkpoint.expires_at <= datetime.now(timezone.utc)\\n\\n\\ndef _as_uuid(value: str) -> UUID | None:\\n    try:\\n        return UUID(value)\\n    except (ValueError, AttributeError):\\n        return None\\n\\n\\ndef _decode(blob: str) -> GraphCheckpoint | None:\\n    try:\\n        return GraphCheckpoint.model_validate_json(blob)\\n    except ValidationError:\\n        return None\\n\\n\\nclass JobScopedCheckpointStore(CheckpointStore, Service):\\n    name = \\\"checkpoint_service\\\"  # registry key for ServiceType.CHECKPOINT_SERVICE\\n\\n    def __init__(self, job_service: JobService) -> None:\\n        super().__init__()\\n        self._jobs = job_service\\n\\n    async def teardown(self) -> None:\\n        pass\\n\\n    async def save_blob(self, job_id: str, kind: str, blob: str) -> None:\\n        \\\"\\\"\\\"Durably persist the agent-thread blob (LE-1447) on the job-scoped row.\\\"\\\"\\\"\\n        parsed = _as_uuid(job_id)\\n        if parsed is not None:\\n            await self._jobs.save_checkpoint(parsed, kind, blob)\\n\\n    async def load_blob(self, job_id: str, kind: str) -> str | None:\\n        parsed = _as_uuid(job_id)\\n        if parsed is None:\\n            return None\\n        return await self._jobs.load_checkpoint(parsed, kind)\\n\\n    async def save(self, checkpoint: GraphCheckpoint) -> None:\\n        if checkpoint.job_id is None:\\n            msg = \\\"GraphCheckpoint.job_id is required to persist a durable checkpoint\\\"\\n            raise ValueError(msg)\\n        await self._jobs.save_checkpoint(UUID(checkpoint.job_id), _KIND, checkpoint.model_dump_json())\\n\\n    async def load(self, checkpoint_id: str) -> GraphCheckpoint | None:\\n        raise NotImplementedError(_SCAN_UNSUPPORTED.format(method=\\\"load(checkpoint_id)\\\"))\\n\\n    async def delete(self, checkpoint_id: str) -> None:\\n        raise NotImplementedError(_SCAN_UNSUPPORTED.format(method=\\\"delete(checkpoint_id)\\\"))\\n\\n    async def load_by_run_id(self, run_id: str) -> GraphCheckpoint | None:\\n        # run_id carries the job_id (LE-1446 threads it), so resume resolves the\\n        # one job-scoped row directly instead of scanning every stored checkpoint.\\n        job_id = _as_uuid(run_id)\\n        if job_id is None:\\n            return None\\n        blob = await self._jobs.load_checkpoint(job_id, _KIND)\\n        if blob is None:\\n            return None\\n        checkpoint = _decode(blob)\\n        if checkpoint is None or _expired(checkpoint):\\n            return None\\n        return checkpoint\\n\\n    async def list_by_session(self, session_id: str) -> list[GraphCheckpoint]:\\n        raise NotImplementedError(_SCAN_UNSUPPORTED.format(method=\\\"list_by_session\\\"))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3d10863f598c07e2905ea94d6ddbf990cd081071f840857c8a677b94f60a97f4\",\"content\":\"\\\"\\\"\\\"Database service constants.\\\"\\\"\\\"\\n\\n# Minimum PostgreSQL major version required by Langflow.\\n# The schema uses UNIQUE NULLS DISTINCT, which is only supported in PostgreSQL 15+.\\nMIN_POSTGRESQL_MAJOR_VERSION = 15\\n\\n# User-facing message when migrations fail due to PostgreSQL < 15 (e.g. UNIQUE NULLS DISTINCT).\\nPOSTGRESQL_VERSION_REQUIRED_MESSAGE = (\\n    f\\\"Langflow requires PostgreSQL {MIN_POSTGRESQL_MAJOR_VERSION} or higher when using PostgreSQL as the database. \\\"\\n    \\\"The current PostgreSQL version does not support the syntax used by Langflow's schema. \\\"\\n    f\\\"Please upgrade your PostgreSQL instance to version {MIN_POSTGRESQL_MAJOR_VERSION} or higher. \\\"\\n    \\\"See: https://docs.langflow.org/configuration-custom-database\\\"\\n)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"feb4b59108e62fb42181be4fbe02303e437d99cfc730f76ebb5e512500b25b4a\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom langflow.services.database.service import DatabaseService\\nfrom langflow.services.factory import ServiceFactory\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.service import SettingsService\\n\\n\\nclass DatabaseServiceFactory(ServiceFactory):\\n    def __init__(self) -> None:\\n        super().__init__(DatabaseService)\\n\\n    def create(self, settings_service: SettingsService):\\n        # Here you would have logic to create and configure a DatabaseService\\n        if not settings_service.settings.database_url:\\n            msg = \\\"No database URL provided\\\"\\n            raise ValueError(msg)\\n        return DatabaseService(settings_service)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/lock_retry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bf5495d14cc0a0303c03f9d59ef064a8bba71c776c8779dfae9d289d72e3b621\",\"content\":\"\\\"\\\"\\\"Recovery helpers for transient database write-lock contention.\\n\\nSQLite serializes writers, and under WAL a transaction that has already read\\ncannot be upgraded to a writer once another connection has committed: SQLite\\nanswers ``SQLITE_BUSY_SNAPSHOT`` (message: \\\"database is locked\\\") *immediately*\\nand deliberately does not invoke the busy handler, because waiting could never\\nresolve a stale snapshot. ``busy_timeout`` therefore has no effect on this\\nclass of failure \u2014 the only valid recovery is to end the transaction and run it\\nagain against a fresh snapshot, which is what :func:`run_with_lock_retry` does.\\n\\nPostgreSQL deployments never take this path: the predicate below only matches\\nSQLite lock errors, so the retry is inert elsewhere.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport random\\nimport sqlite3\\nfrom typing import TYPE_CHECKING, TypeVar\\n\\nfrom lfx.log.logger import logger\\nfrom sqlalchemy.exc import SQLAlchemyError\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Awaitable, Callable\\n\\n    from sqlalchemy.ext.asyncio import AsyncSession\\n\\nT = TypeVar(\\\"T\\\")\\n\\nDEFAULT_LOCK_RETRY_ATTEMPTS = 8\\nDEFAULT_LOCK_RETRY_BASE_DELAY = 0.02\\nMAX_LOCK_RETRY_DELAY = 0.75\\n\\n# sqlite3 exposes the extended result code by name from Python 3.11 on; the\\n# message check keeps older interpreters and non-extended codes covered.\\n_SQLITE_LOCK_ERROR_NAMES = frozenset(\\n    {\\n        \\\"SQLITE_BUSY\\\",\\n        \\\"SQLITE_BUSY_SNAPSHOT\\\",\\n        \\\"SQLITE_BUSY_RECOVERY\\\",\\n        \\\"SQLITE_BUSY_TIMEOUT\\\",\\n        \\\"SQLITE_LOCKED\\\",\\n        \\\"SQLITE_LOCKED_SHAREDCACHE\\\",\\n    }\\n)\\n_SQLITE_LOCK_MESSAGES = (\\\"database is locked\\\", \\\"database table is locked\\\")\\n\\n\\ndef is_database_lock_error(exc: BaseException | None) -> bool:\\n    \\\"\\\"\\\"Return True when *exc* (or anything it wraps) is a transient SQLite lock error.\\\"\\\"\\\"\\n    seen: set[int] = set()\\n    while exc is not None and id(exc) not in seen:\\n        seen.add(id(exc))\\n        error_name = getattr(exc, \\\"sqlite_errorname\\\", None)\\n        if error_name in _SQLITE_LOCK_ERROR_NAMES:\\n            return True\\n        # SQLAlchemy's wrapper text contains the SQL statement and bound\\n        # parameters. Inspect only the underlying SQLite operational error so\\n        # user data containing \\\"database is locked\\\" cannot trigger retries.\\n        if isinstance(exc, sqlite3.OperationalError):\\n            message = str(exc).lower()\\n            if any(marker in message for marker in _SQLITE_LOCK_MESSAGES):\\n                return True\\n        exc = getattr(exc, \\\"orig\\\", None) or exc.__cause__\\n    return False\\n\\n\\ndef sanitize_database_error(exc: BaseException, fallback: str) -> str:\\n    \\\"\\\"\\\"Return a client-safe message for *exc*.\\n\\n    SQLAlchemy's ``str()`` embeds the failing statement, the table name and the\\n    bound parameters, so it must never reach an API consumer.\\n    \\\"\\\"\\\"\\n    if isinstance(exc, SQLAlchemyError):\\n        return fallback\\n    return str(exc)\\n\\n\\nasync def run_with_lock_retry(\\n    operation: Callable[[int], Awaitable[T]],\\n    *,\\n    session: AsyncSession,\\n    description: str,\\n    attempts: int = DEFAULT_LOCK_RETRY_ATTEMPTS,\\n    base_delay: float = DEFAULT_LOCK_RETRY_BASE_DELAY,\\n) -> T:\\n    \\\"\\\"\\\"Run *operation* until it succeeds, retrying only transient lock failures.\\n\\n    *operation* receives the zero-based attempt number and must be safe to run\\n    again from scratch: every retry starts a brand new transaction, so state\\n    read or written by a failed attempt is gone and has to be re-established.\\n\\n    The last attempt's error propagates unchanged so callers can map an\\n    exhausted retry budget to their own response.\\n    \\\"\\\"\\\"\\n    last_attempt = attempts - 1\\n    for attempt in range(attempts):\\n        try:\\n            return await operation(attempt)\\n        except Exception as exc:\\n            if attempt == last_attempt or not is_database_lock_error(exc):\\n                raise\\n            # The snapshot is stale: roll the transaction back so the retry\\n            # reads current data instead of failing on the same conflict.\\n            await session.rollback()\\n            delay = min(base_delay * (2**attempt), MAX_LOCK_RETRY_DELAY)\\n            # Jitter keeps concurrent losers from colliding again in lockstep.\\n            await asyncio.sleep(delay * (0.5 + random.random()))  # noqa: S311\\n            await logger.adebug(\\n                \\\"Database lock contention on %s, retrying (attempt %s/%s)\\\", description, attempt + 2, attempts\\n            )\\n    msg = \\\"unreachable: the retry loop either returns or raises\\\"\\n    raise AssertionError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/migration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ba4ff934a211cef9b01caabe11b6ce974bbdae8ab1018f8ed8069ffa6f997f93\",\"content\":\"\\\"\\\"\\\"Shared Alembic state probes for application startup.\\\"\\\"\\\"\\n\\nfrom collections.abc import Sequence\\n\\nfrom alembic.migration import MigrationContext\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\nasync def get_current_alembic_heads(session: AsyncSession) -> Sequence[str]:\\n    \\\"\\\"\\\"Return current database revisions without treating a missing table as an error.\\n\\n    Alembic's ``MigrationContext`` returns an empty tuple when its version table\\n    does not exist and supports multiple current heads. Connection and driver\\n    failures are intentionally allowed to propagate to the caller.\\n    \\\"\\\"\\\"\\n    async_connection = await session.connection()\\n    heads = await async_connection.run_sync(\\n        lambda connection: MigrationContext.configure(connection).get_current_heads()\\n    )\\n    return heads or ()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bd9b20757680c58bcfc5da3e60a6abbadc740efd4a6f58c1eefe2e9ee9f59e5c\",\"content\":\"from .a2a import A2ACheckpoint, A2ATask\\nfrom .api_key import ApiKey\\nfrom .auth import (\\n    AuthzAuditLog,\\n    AuthzEditLock,\\n    AuthzRole,\\n    AuthzRoleAssignment,\\n    AuthzShare,\\n    AuthzTeam,\\n    AuthzTeamMember,\\n    CasbinRule,\\n    SSOConfig,\\n    SSOConfigCreate,\\n    SSOConfigRead,\\n    SSOConfigUpdate,\\n    SSOSecretError,\\n    SSOSettings,\\n    SSOUserProfile,\\n    decrypt_sso_client_secret,\\n    encrypt_sso_client_secret,\\n    is_sso_client_secret_envelope,\\n)\\nfrom .catalog_policy import CatalogPolicyMode, CatalogPolicyRule, CatalogPolicyScope, CatalogResourceKind\\nfrom .deployment import Deployment\\nfrom .deployment_provider_account import DeploymentProviderAccount\\nfrom .file import File\\nfrom .flow import Flow\\nfrom .flow_version import FlowVersion\\nfrom .flow_version_deployment_attachment import FlowVersionDeploymentAttachment\\nfrom .folder import Folder\\nfrom .ingestion_run import IngestionRun, IngestionRunStatus\\nfrom .jobs import ExecutionSignal, Job, JobCheckpoint, JobEvent, SignalType\\nfrom .knowledge_base import KnowledgeBaseRecord, KnowledgeBaseStatus\\nfrom .mcp_server import MCPServer\\nfrom .memory_base import MemoryBase, MemoryBaseSession, MemoryBaseWorkflowRun, MessageIngestionRecord\\nfrom .message import MessageTable\\nfrom .model_provider_policy import ModelProviderPolicy\\nfrom .policy_bundle import PolicyBundleActive, PolicyBundleRevision\\nfrom .traces.model import SpanTable, TraceTable\\nfrom .transactions import TransactionTable\\nfrom .user import User\\nfrom .variable import Variable\\n\\n__all__ = [\\n    \\\"A2ACheckpoint\\\",\\n    \\\"A2ATask\\\",\\n    \\\"ApiKey\\\",\\n    \\\"AuthzAuditLog\\\",\\n    \\\"AuthzEditLock\\\",\\n    \\\"AuthzRole\\\",\\n    \\\"AuthzRoleAssignment\\\",\\n    \\\"AuthzShare\\\",\\n    \\\"AuthzTeam\\\",\\n    \\\"AuthzTeamMember\\\",\\n    \\\"CasbinRule\\\",\\n    \\\"CatalogPolicyMode\\\",\\n    \\\"CatalogPolicyRule\\\",\\n    \\\"CatalogPolicyScope\\\",\\n    \\\"CatalogResourceKind\\\",\\n    \\\"Deployment\\\",\\n    \\\"DeploymentProviderAccount\\\",\\n    \\\"ExecutionSignal\\\",\\n    \\\"File\\\",\\n    \\\"Flow\\\",\\n    \\\"FlowVersion\\\",\\n    \\\"FlowVersionDeploymentAttachment\\\",\\n    \\\"Folder\\\",\\n    \\\"IngestionRun\\\",\\n    \\\"IngestionRunStatus\\\",\\n    \\\"Job\\\",\\n    \\\"JobCheckpoint\\\",\\n    \\\"JobEvent\\\",\\n    \\\"KnowledgeBaseRecord\\\",\\n    \\\"KnowledgeBaseStatus\\\",\\n    \\\"MCPServer\\\",\\n    \\\"MemoryBase\\\",\\n    \\\"MemoryBaseSession\\\",\\n    \\\"MemoryBaseWorkflowRun\\\",\\n    \\\"MessageIngestionRecord\\\",\\n    \\\"MessageTable\\\",\\n    \\\"ModelProviderPolicy\\\",\\n    \\\"PolicyBundleActive\\\",\\n    \\\"PolicyBundleRevision\\\",\\n    \\\"SSOConfig\\\",\\n    \\\"SSOConfigCreate\\\",\\n    \\\"SSOConfigRead\\\",\\n    \\\"SSOConfigUpdate\\\",\\n    \\\"SSOSecretError\\\",\\n    \\\"SSOSettings\\\",\\n    \\\"SSOUserProfile\\\",\\n    \\\"SignalType\\\",\\n    \\\"SpanTable\\\",\\n    \\\"TraceTable\\\",\\n    \\\"TransactionTable\\\",\\n    \\\"User\\\",\\n    \\\"Variable\\\",\\n    \\\"decrypt_sso_client_secret\\\",\\n    \\\"encrypt_sso_client_secret\\\",\\n    \\\"is_sso_client_secret_envelope\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/a2a/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5065cfbc204277bdab31b4235b1a7462d0f239f56d874028dd38c866e1bfa742\",\"content\":\"from .model import A2ACheckpoint, A2ATask\\n\\n__all__ = [\\\"A2ACheckpoint\\\", \\\"A2ATask\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/a2a/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"dec9ec020f60b938d40cfde641857afe6508ef27832e2fffd5e39b5829125c90\",\"content\":\"\\\"\\\"\\\"Durable storage for A2A protocol tasks.\\\"\\\"\\\"\\n\\nfrom datetime import datetime\\nfrom typing import Any\\n\\nfrom sqlalchemy import JSON, Column, DateTime, func\\nfrom sqlalchemy.dialects.postgresql import JSONB\\nfrom sqlmodel import Field, SQLModel\\n\\n# JSONB on Postgres (GIN-indexable), JSON elsewhere \u2014 same variant as the other JSON columns.\\nJsonVariant = JSON().with_variant(JSONB(), \\\"postgresql\\\")\\n\\n\\nclass A2ATask(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"One A2A protocol Task, persisted so it survives restart and is visible across workers.\\n\\n    ``task`` holds the whole protobuf ``Task`` as ``MessageToDict`` JSON; the A2A surface\\n    only does point lookups by id this slice, so a single blob is enough (a tasks/list or\\n    contextId filter would add decomposed columns later). The composite PK ``(id, owner)``\\n    mirrors the SDK TaskStore's owner-scoped keying. Legacy anonymous rows used an empty SDK\\n    owner inside the flow scope; current public rows use the stable anonymous principal. ``id``\\n    is declared first so ``session.get(A2ATask, (id, owner))`` passes the tuple in primary-key order.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"a2a_tasks\\\"\\n\\n    id: str = Field(primary_key=True)\\n    owner: str = Field(default=\\\"\\\", primary_key=True)\\n    task: dict[str, Any] = Field(sa_column=Column(JsonVariant, nullable=False))\\n    # Nothing prunes a2a_tasks yet, so the table grows unbounded. These let a retention reaper (or\\n    # an operator) prune by age; the DB maintains both, so the store needs no timestamp code.\\n    created_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), server_default=func.now(), nullable=True),\\n    )\\n    updated_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), server_default=func.now(), onupdate=func.now(), nullable=True),\\n    )\\n\\n\\nclass A2ACheckpoint(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"A paused HITL run's graph checkpoint, so an A2A ``input-required`` task can be resumed.\\n\\n    Keyed by ``run_id`` (the A2A task id, a UUID4); ``checkpoint`` is the lfx ``GraphCheckpoint``\\n    as ``model_dump`` JSON. Resume access is gated by the route's apikey auth, the unguessable\\n    task id, and a ``checkpoint.flow_id == flow_id`` check in ``_resume_flow`` (so a task parked\\n    under one flow can't be resumed via another's endpoint). Kept separate from ``a2a_tasks`` so\\n    the public Task blob never carries internal resume state. lfx-portable: only ``session_scope``\\n    + this table, no langflow job machinery.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"a2a_checkpoints\\\"\\n\\n    run_id: str = Field(primary_key=True)\\n    checkpoint: dict[str, Any] = Field(sa_column=Column(JsonVariant, nullable=False))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/api_key/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8ba27e0a2e5edecc8b7061a1e6fa6e88017b19019d4b12e30d2875387977a5cb\",\"content\":\"from .model import ApiKey, ApiKeyCreate, ApiKeyRead, UnmaskedApiKeyRead\\n\\n__all__ = [\\\"ApiKey\\\", \\\"ApiKeyCreate\\\", \\\"ApiKeyRead\\\", \\\"UnmaskedApiKeyRead\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/api_key/crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ddbb4f43725f3bf28c1deffc01b81abf112d1317378c3bdb8aa6497f9c8e04d7\",\"content\":\"import binascii\\nimport datetime\\nimport hashlib\\nimport os\\nimport secrets\\nfrom collections.abc import Callable\\nfrom contextlib import AbstractAsyncContextManager\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING\\nfrom uuid import UUID\\n\\nfrom cryptography.fernet import InvalidToken\\nfrom lfx.log.logger import logger\\nfrom sqlmodel import select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.services.auth import utils as auth_utils\\nfrom langflow.services.database.models.api_key.model import ApiKey, ApiKeyCreate, ApiKeyRead, UnmaskedApiKeyRead\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_settings_service, session_scope\\n\\nif TYPE_CHECKING:\\n    from sqlmodel.sql.expression import SelectOfScalar\\n\\n\\n@dataclass(frozen=True)\\nclass ApiKeyAuthResult:\\n    \\\"\\\"\\\"Authenticated API-key metadata.\\\"\\\"\\\"\\n\\n    user: User\\n    api_key_source: str\\n    api_key_id: UUID | None = None\\n\\n\\nSessionScopeFactory = Callable[[], AbstractAsyncContextManager[AsyncSession]]\\n\\n\\ndef hash_api_key(api_key: str) -> str:\\n    \\\"\\\"\\\"One-way SHA-256 hash of a plaintext API key for indexed lookup.\\\"\\\"\\\"\\n    return hashlib.sha256(api_key.encode()).hexdigest()\\n\\n\\ndef _api_keys_match(provided: str, expected: str) -> bool:\\n    \\\"\\\"\\\"Compare API keys without content-dependent short-circuiting.\\\"\\\"\\\"\\n    return secrets.compare_digest(provided.encode(), expected.encode())\\n\\n\\ndef _is_expired(expires_at: datetime.datetime | None) -> bool:\\n    if expires_at is None:\\n        return False\\n    # Rows written before the expires_at column became tz-aware come back naive.\\n    # All historical writes used datetime.now(timezone.utc), so interpret naive as UTC.\\n    if expires_at.tzinfo is None:\\n        expires_at = expires_at.replace(tzinfo=datetime.timezone.utc)\\n    return datetime.datetime.now(datetime.timezone.utc) > expires_at\\n\\n\\nasync def get_api_keys(session: AsyncSession, user_id: UUID) -> list[ApiKeyRead]:\\n    \\\"\\\"\\\"Get all API keys for a user with decrypted values.\\\"\\\"\\\"\\n    query: SelectOfScalar = select(ApiKey).where(ApiKey.user_id == user_id)\\n    api_key_objects = (await session.exec(query)).all()\\n\\n    api_keys = []\\n    for api_key_obj in api_key_objects:\\n        data = api_key_obj.model_dump()\\n\\n        api_key = data.get(\\\"api_key\\\")\\n        if api_key:\\n            try:\\n                actual_key = auth_utils.decrypt_api_key(api_key)\\n            except (ValueError, TypeError, InvalidToken, UnicodeDecodeError, AttributeError, binascii.Error):\\n                actual_key = api_key\\n            # decrypt_api_key returns \\\"\\\" on failure; fall back to stored value\\n            if not actual_key:\\n                actual_key = api_key\\n        else:\\n            actual_key = api_key\\n\\n        data[\\\"api_key\\\"] = actual_key\\n        api_keys.append(ApiKeyRead.model_validate(data))\\n\\n    return api_keys\\n\\n\\nasync def create_api_key(session: AsyncSession, api_key_create: ApiKeyCreate, user_id: UUID) -> UnmaskedApiKeyRead:\\n    \\\"\\\"\\\"Create a new API key, storing an encrypted value and a SHA-256 hash for fast lookup.\\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n    auth_settings = settings_service.auth_settings\\n    if (\\n        auth_settings.EXTERNAL_AUTH_ACCESS_CEILING_ENABLED\\n        and auth_settings.EXTERNAL_AUTH_DISABLE_API_KEYS_FOR_EXTERNAL_USERS\\n    ):\\n        from langflow.services.authorization.access_ceiling import get_current_external_access_context\\n\\n        if get_current_external_access_context() is not None:\\n            msg = \\\"API key creation is disabled for externally authenticated users\\\"\\n            raise PermissionError(msg)\\n\\n    # Generate a random API key with 32 bytes of randomness\\n    generated_api_key = f\\\"sk-{secrets.token_urlsafe(32)}\\\"\\n\\n    stored_api_key = auth_utils.encrypt_api_key(generated_api_key)\\n\\n    api_key = ApiKey(\\n        api_key=stored_api_key,\\n        api_key_hash=hash_api_key(generated_api_key),\\n        name=api_key_create.name,\\n        user_id=user_id,\\n        created_at=api_key_create.created_at or datetime.datetime.now(datetime.timezone.utc),\\n        expires_at=api_key_create.expires_at,\\n    )\\n\\n    session.add(api_key)\\n    await session.flush()\\n    await session.refresh(api_key)\\n    unmasked = UnmaskedApiKeyRead.model_validate(api_key, from_attributes=True)\\n    unmasked.api_key = generated_api_key\\n    return unmasked\\n\\n\\nasync def delete_api_key(session: AsyncSession, api_key_id: UUID, user_id: UUID) -> None:\\n    \\\"\\\"\\\"Delete an API key, raising ValueError if not found or not owned by user_id.\\\"\\\"\\\"\\n    api_key = await session.get(ApiKey, api_key_id)\\n    if api_key is None:\\n        msg = \\\"API Key not found\\\"\\n        raise ValueError(msg)\\n    if api_key.user_id != user_id:\\n        msg = \\\"API Key not found\\\"\\n        raise ValueError(msg)\\n    await session.delete(api_key)\\n\\n\\nasync def check_key(api_key: str) -> User | None:\\n    \\\"\\\"\\\"Check if the API key is valid.\\n\\n    Validates API keys based on the LANGFLOW_API_KEY_SOURCE setting:\\n    - 'db': Validates against database-stored API keys (default)\\n    - 'env': Validates against the LANGFLOW_API_KEY environment variable,\\n             falls back to database if env validation fails\\n    \\\"\\\"\\\"\\n    result = await authenticate_api_key(api_key)\\n    return result.user if result is not None else None\\n\\n\\nasync def authenticate_api_key(api_key: str) -> ApiKeyAuthResult | None:\\n    \\\"\\\"\\\"Validate an API key in an owned transaction and return non-secret metadata.\\\"\\\"\\\"\\n    return await _authenticate_api_key_in_owned_scope(api_key, session_scope)\\n\\n\\nasync def _authenticate_api_key_in_owned_scope(\\n    api_key: str,\\n    scope_factory: SessionScopeFactory,\\n) -> ApiKeyAuthResult | None:\\n    \\\"\\\"\\\"Authenticate and durably persist bookkeeping in a top-level transaction.\\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n    async with scope_factory() as auth_session:\\n        result = await _authenticate_api_key_with_session(auth_session, api_key, settings_service)\\n        if result is not None and result.user in auth_session:\\n            # Keep scalar user fields available after the owned scope commits and\\n            # closes, independent of the session maker's expire_on_commit value.\\n            auth_session.expunge(result.user)\\n        return result\\n\\n\\nasync def _authenticate_api_key_with_session(\\n    session: AsyncSession,\\n    api_key: str,\\n    settings_service,\\n) -> ApiKeyAuthResult | None:\\n    \\\"\\\"\\\"Transaction-local API-key authentication implementation.\\\"\\\"\\\"\\n    api_key_source = settings_service.auth_settings.API_KEY_SOURCE\\n\\n    if api_key_source == \\\"env\\\":\\n        user = await _check_key_from_env(session, api_key, settings_service)\\n        if user is not None:\\n            return ApiKeyAuthResult(user=user, api_key_source=\\\"env\\\")\\n        # Fallback to database if env validation fails\\n    return await _check_key_from_db_with_context(session, api_key, settings_service)\\n\\n\\nasync def _external_access_ceiling_blocks_user(session: AsyncSession, user: User, settings_service) -> bool:\\n    \\\"\\\"\\\"Return True when API-key auth must be denied for an externally-managed user.\\n\\n    Single chokepoint for the EXTERNAL_AUTH access ceiling: every DB-path API-key\\n    authentication flows through ``_check_key_from_db_with_context``, so enforcing\\n    here covers ``_api_key_security_impl`` (/run, v2 workflow, openai_responses),\\n    ``ws_api_key_security``, ``get_webhook_user``, ``get_current_user_mcp`` and the\\n    auth service. When the feature is OFF (ceiling disabled OR disable-keys\\n    disabled) this is a no-op.\\n    \\\"\\\"\\\"\\n    auth_settings = settings_service.auth_settings\\n    if (\\n        not auth_settings.EXTERNAL_AUTH_ACCESS_CEILING_ENABLED\\n        or not auth_settings.EXTERNAL_AUTH_DISABLE_API_KEYS_FOR_EXTERNAL_USERS\\n    ):\\n        return False\\n\\n    from langflow.services.database.models.auth import SSOUserProfile\\n\\n    profile_stmt = select(SSOUserProfile).where(\\n        SSOUserProfile.user_id == user.id,\\n        SSOUserProfile.sso_provider == auth_settings.EXTERNAL_AUTH_PROVIDER,\\n    )\\n    return (await session.exec(profile_stmt)).first() is not None\\n\\n\\nasync def _check_key_from_db(session: AsyncSession, api_key: str, settings_service) -> User | None:\\n    \\\"\\\"\\\"Validate API key against the database and return only the user.\\\"\\\"\\\"\\n    result = await _check_key_from_db_with_context(session, api_key, settings_service)\\n    return result.user if result is not None else None\\n\\n\\nasync def _check_key_from_db_with_context(\\n    session: AsyncSession,\\n    api_key: str,\\n    settings_service,\\n) -> ApiKeyAuthResult | None:\\n    \\\"\\\"\\\"Validate API key against the database.\\n\\n    Uses hash-based O(1) lookup first. Falls back to decrypt-and-compare\\n    for legacy keys that don't have a hash yet, and backfills the hash on match.\\n    \\\"\\\"\\\"\\n    if not api_key:\\n        return None\\n\\n    incoming_hash = hash_api_key(api_key)\\n\\n    # Fast path: O(1) indexed lookup by hash\\n    query = select(ApiKey).where(ApiKey.api_key_hash == incoming_hash, ApiKey.is_active.is_(True))\\n    matches = (await session.exec(query)).all()\\n\\n    if len(matches) == 1:\\n        api_key_obj = matches[0]\\n        if _is_expired(api_key_obj.expires_at):\\n            return None\\n        # Resolve + authorize the user BEFORE the usage counters, so a denied authentication\\n        # (missing user, blocked external user) does not bump total_uses / last_used_at.\\n        user = await session.get(User, api_key_obj.user_id)\\n        if user is None or not user.is_active:\\n            return None\\n        if await _external_access_ceiling_blocks_user(session, user, settings_service):\\n            logger.info(\\\"API key rejected for externally managed user while external access ceiling is enabled\\\")\\n            return None\\n        if settings_service.settings.disable_track_apikey_usage is not True:\\n            api_key_obj.total_uses += 1\\n            api_key_obj.last_used_at = datetime.datetime.now(datetime.timezone.utc)\\n            session.add(api_key_obj)\\n            await session.flush()\\n        return ApiKeyAuthResult(user=user, api_key_source=\\\"db\\\", api_key_id=api_key_obj.id)  # pragma: allowlist secret\\n\\n    if len(matches) > 1:\\n        key_ids = [str(m.id) for m in matches]\\n        logger.error(\\n            \\\"Data integrity violation: %d API keys share hash %s (key IDs: %s). Refusing to authenticate.\\\",\\n            len(matches),\\n            incoming_hash[:12] + \\\"...\\\",\\n            \\\", \\\".join(key_ids),\\n        )\\n        return None\\n\\n    # Slow path: legacy keys without hash (plaintext from 1.6.x or encrypted without hash)\\n    query = select(ApiKey).where(ApiKey.api_key_hash.is_(None), ApiKey.is_active.is_(True))  # type: ignore[union-attr]\\n    legacy_keys = (await session.exec(query)).all()\\n\\n    for api_key_obj in legacy_keys:\\n        stored_value = api_key_obj.api_key\\n        if stored_value is None:\\n            continue\\n\\n        # decrypt_api_key returns \\\"\\\" on failure (never raises for decryption errors)\\n        if _api_keys_match(api_key, stored_value):\\n            matched = True\\n        else:\\n            candidate = auth_utils.decrypt_api_key(stored_value)\\n            matched = _api_keys_match(api_key, candidate)\\n\\n        if matched:\\n            if _is_expired(api_key_obj.expires_at):\\n                return None\\n            # Resolve + authorize the user BEFORE the usage counters / hash backfill, so a denied\\n            # authentication (missing user, blocked external user) does not bump total_uses.\\n            user = await session.get(User, api_key_obj.user_id)\\n            if user is None or not user.is_active:\\n                return None\\n            if await _external_access_ceiling_blocks_user(session, user, settings_service):\\n                logger.info(\\\"API key rejected for externally managed user while external access ceiling is enabled\\\")\\n                return None\\n            # Backfill hash for future O(1) lookups\\n            api_key_obj.api_key_hash = incoming_hash\\n            if settings_service.settings.disable_track_apikey_usage is not True:\\n                api_key_obj.total_uses += 1\\n                api_key_obj.last_used_at = datetime.datetime.now(datetime.timezone.utc)\\n            session.add(api_key_obj)\\n            await session.flush()\\n            return ApiKeyAuthResult(\\n                user=user,\\n                api_key_source=\\\"db\\\",  # pragma: allowlist secret\\n                api_key_id=api_key_obj.id,\\n            )\\n\\n    return None\\n\\n\\nasync def _check_key_from_env(session: AsyncSession, api_key: str, settings_service) -> User | None:\\n    \\\"\\\"\\\"Validate API key against the environment variable.\\n\\n    When API_KEY_SOURCE='env', the x-api-key header is validated against\\n    LANGFLOW_API_KEY environment variable. If valid, returns the superuser for authorization.\\n    \\\"\\\"\\\"\\n    from langflow.services.database.models.user.crud import get_user_by_username\\n\\n    env_api_key = os.getenv(\\\"LANGFLOW_API_KEY\\\")\\n    if not env_api_key:\\n        return None\\n\\n    if not _api_keys_match(api_key, env_api_key):\\n        return None\\n\\n    # Return the superuser for authorization purposes\\n    superuser_username = settings_service.auth_settings.SUPERUSER\\n    user = await get_user_by_username(session, superuser_username)\\n    if user and user.is_active:\\n        return user\\n    return None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/api_key/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"45b55cd538c3a252d45f306521f86b9d6cff5de01a7256106a28b03c4e3875a7\",\"content\":\"from datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING\\nfrom uuid import uuid4\\n\\nfrom pydantic import field_serializer, field_validator\\nfrom sqlmodel import Column, DateTime, Field, Relationship, SQLModel, func\\n\\nfrom langflow.schema.serialize import UUIDstr\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.models.user.model import User\\n\\n\\ndef utc_now():\\n    \\\"\\\"\\\"Return the current UTC datetime.\\\"\\\"\\\"\\n    return datetime.now(timezone.utc)\\n\\n\\ndef _as_utc_iso(v: datetime | None) -> str | None:\\n    # SQLite (and pre-migration Postgres rows) return naive datetimes from a\\n    # timezone=True column. Every writer in this codebase persists UTC, so\\n    # treat naive values as UTC rather than letting Pydantic emit them without\\n    # an offset \u2014 JS Date() parses an offset-less ISO string as local time,\\n    # which shifts the displayed expiry by the viewer's UTC offset.\\n    if v is None:\\n        return None\\n    if v.tzinfo is None:\\n        v = v.replace(tzinfo=timezone.utc)\\n    return v.replace(microsecond=0).isoformat()\\n\\n\\nclass ApiKeyBase(SQLModel):\\n    name: str | None = Field(index=True, nullable=True, default=None)\\n    last_used_at: datetime | None = Field(default=None, nullable=True)\\n    total_uses: int = Field(default=0)\\n    is_active: bool = Field(default=True)\\n    expires_at: datetime | None = Field(default=None, sa_column=Column(DateTime(timezone=True), nullable=True))\\n\\n    @field_serializer(\\\"expires_at\\\", \\\"last_used_at\\\", when_used=\\\"always\\\")\\n    def _serialize_expires_last_used(self, v: datetime | None) -> str | None:\\n        return _as_utc_iso(v)\\n\\n\\nclass ApiKey(ApiKeyBase, table=True):  # type: ignore[call-arg]\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True, unique=True)\\n    created_at: datetime | None = Field(\\n        default=None, sa_column=Column(DateTime(timezone=True), server_default=func.now(), nullable=False)\\n    )\\n    api_key: str = Field(index=True, unique=True)\\n    api_key_hash: str | None = Field(default=None, index=True)\\n    # User relationship\\n    # Delete API keys when user is deleted\\n    user_id: UUIDstr = Field(index=True, foreign_key=\\\"user.id\\\")\\n    user: \\\"User\\\" = Relationship(\\n        back_populates=\\\"api_keys\\\",\\n    )\\n\\n\\nclass ApiKeyCreate(ApiKeyBase):\\n    api_key: str | None = None\\n    user_id: UUIDstr | None = None\\n    created_at: datetime | None = Field(default_factory=utc_now)\\n\\n    @field_validator(\\\"created_at\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def set_created_at(cls, v):\\n        \\\"\\\"\\\"Default created_at to the current UTC time when not provided.\\\"\\\"\\\"\\n        return v or utc_now()\\n\\n\\nclass UnmaskedApiKeyRead(ApiKeyBase):\\n    id: UUIDstr\\n    api_key: str = Field()\\n    user_id: UUIDstr = Field()\\n\\n\\nclass ApiKeyRead(ApiKeyBase):\\n    id: UUIDstr\\n    api_key: str = Field(schema_extra={\\\"validate_default\\\": True})\\n    user_id: UUIDstr = Field()\\n    created_at: datetime = Field()\\n\\n    @field_validator(\\\"api_key\\\")\\n    @classmethod\\n    def mask_api_key(cls, v) -> str:\\n        \\\"\\\"\\\"Mask all but the first 8 characters of the API key.\\\"\\\"\\\"\\n        return f\\\"{v[:8]}{'*' * (len(v) - 8)}\\\"\\n\\n    @field_serializer(\\\"created_at\\\", when_used=\\\"always\\\")\\n    def _serialize_created_at(self, v: datetime) -> str | None:\\n        return _as_utc_iso(v)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/auth/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"61fe473b46c1e5af29c24a219cb5803d52ac95abafbac87e418df86ee6e6bc85\",\"content\":\"from .authz import (\\n    AuthzAuditLog,\\n    AuthzEditLock,\\n    AuthzRole,\\n    AuthzRoleAssignment,\\n    AuthzRoleAssignmentGrant,\\n    AuthzShare,\\n    AuthzTeam,\\n    AuthzTeamMember,\\n    CasbinRule,\\n    SharePermissionLevel,\\n    ShareScope,\\n)\\nfrom .sso import SSOConfig, SSOConfigCreate, SSOConfigRead, SSOConfigUpdate, SSOSettings, SSOUserProfile\\nfrom .sso_secret import (\\n    SSOSecretError,\\n    decrypt_sso_client_secret,\\n    encrypt_sso_client_secret,\\n    is_sso_client_secret_envelope,\\n)\\n\\n__all__ = [\\n    \\\"AuthzAuditLog\\\",\\n    \\\"AuthzEditLock\\\",\\n    \\\"AuthzRole\\\",\\n    \\\"AuthzRoleAssignment\\\",\\n    \\\"AuthzRoleAssignmentGrant\\\",\\n    \\\"AuthzShare\\\",\\n    \\\"AuthzTeam\\\",\\n    \\\"AuthzTeamMember\\\",\\n    \\\"CasbinRule\\\",\\n    \\\"SSOConfig\\\",\\n    \\\"SSOConfigCreate\\\",\\n    \\\"SSOConfigRead\\\",\\n    \\\"SSOConfigUpdate\\\",\\n    \\\"SSOSecretError\\\",\\n    \\\"SSOSettings\\\",\\n    \\\"SSOUserProfile\\\",\\n    \\\"SharePermissionLevel\\\",\\n    \\\"ShareScope\\\",\\n    \\\"decrypt_sso_client_secret\\\",\\n    \\\"encrypt_sso_client_secret\\\",\\n    \\\"is_sso_client_secret_envelope\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/auth/authz.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8fc82a1439610d4e731abf8236aef8c41f3bd4bf0d173051dddcc28058317bf3\",\"content\":\"\\\"\\\"\\\"Authorization (RBAC) tables (Alembic-owned; plugins populate policy data).\\\"\\\"\\\"\\n\\nfrom datetime import datetime, timezone\\nfrom enum import Enum\\nfrom uuid import uuid4\\n\\nimport sqlalchemy as sa\\nfrom sqlalchemy import CheckConstraint, Column, ForeignKey, Index, UniqueConstraint, text\\nfrom sqlalchemy.sql.naming import conv\\nfrom sqlmodel import Field, Relationship, SQLModel\\n\\nfrom langflow.schema.serialize import UUIDstr\\n\\n\\nclass ShareScope(str, Enum):\\n    \\\"\\\"\\\"Audience of an AuthzShare row (private = owner only, public = anyone).\\\"\\\"\\\"\\n\\n    PRIVATE = \\\"private\\\"\\n    TEAM = \\\"team\\\"\\n    USER = \\\"user\\\"\\n    PUBLIC = \\\"public\\\"\\n\\n\\nclass SharePermissionLevel(str, Enum):\\n    \\\"\\\"\\\"Level of access granted by an AuthzShare row.\\\"\\\"\\\"\\n\\n    READ = \\\"read\\\"\\n    WRITE = \\\"write\\\"\\n    EXECUTE = \\\"execute\\\"\\n    ADMIN = \\\"admin\\\"\\n\\n\\ndef _tz_aware_now() -> datetime:\\n    \\\"\\\"\\\"Return a TZ-aware UTC datetime \u2014 used by every authz default_factory.\\\"\\\"\\\"\\n    return datetime.now(timezone.utc)\\n\\n\\ndef _tz_column(*, nullable: bool = False, index: bool = False) -> Column:\\n    \\\"\\\"\\\"Return a ``DateTime(timezone=True)`` column \u2014 keeps the type consistent.\\\"\\\"\\\"\\n    return Column(sa.DateTime(timezone=True), nullable=nullable, index=index)\\n\\n\\nclass CasbinRule(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Policy rule storage (ptype-indexed for loader queries).\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"casbin_rule\\\"\\n    __table_args__ = (Index(\\\"ix_casbin_rule_ptype\\\", \\\"ptype\\\"),)\\n\\n    id: int | None = Field(default=None, primary_key=True)\\n    ptype: str = Field(max_length=255)\\n    v0: str | None = Field(default=None, max_length=255)\\n    v1: str | None = Field(default=None, max_length=255)\\n    v2: str | None = Field(default=None, max_length=255)\\n    v3: str | None = Field(default=None, max_length=255)\\n    v4: str | None = Field(default=None, max_length=255)\\n    v5: str | None = Field(default=None, max_length=255)\\n\\n\\nclass AuthzRole(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Role metadata for admin UI.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"authz_role\\\"\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    name: str = Field(index=True, unique=True)\\n    description: str | None = Field(default=None)\\n    is_system: bool = Field(default=False)\\n    permissions: list[str] = Field(default_factory=list, sa_column=Column(sa.JSON, nullable=False))\\n    parent_role_id: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"authz_role.id\\\", ondelete=\\\"SET NULL\\\"), nullable=True),\\n    )\\n    workspace_id: UUIDstr | None = Field(default=None, index=True)\\n    created_at: datetime = Field(default_factory=_tz_aware_now, sa_column=_tz_column())\\n    updated_at: datetime = Field(default_factory=_tz_aware_now, sa_column=_tz_column())\\n    created_by: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"SET NULL\\\"), nullable=True),\\n    )\\n\\n\\nclass AuthzRoleAssignment(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Binds a user to a role within an optional domain (global/org/workspace).\\n\\n    A plain UNIQUE(user_id, role_id, domain_type, domain_id) treats NULL\\n    ``domain_id`` values as never-equal, so duplicates with NULL would slip\\n    through. Two partial unique indexes cover the cases without gaps:\\n\\n    * scoped: rows with ``domain_id IS NOT NULL`` (workspace/org assignments).\\n    * unscoped: rows with ``domain_id IS NULL`` (every domain_type \u2014 global,\\n      and any ill-formed org/workspace without an id \u2014 so the unique guarantee\\n      is exhaustive regardless of how callers spell ``domain_type``).\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"authz_role_assignment\\\"\\n    __table_args__ = (\\n        Index(\\n            \\\"uq_authz_role_assignment_scoped\\\",\\n            \\\"user_id\\\",\\n            \\\"role_id\\\",\\n            \\\"domain_type\\\",\\n            \\\"domain_id\\\",\\n            unique=True,\\n            postgresql_where=text(\\\"domain_id IS NOT NULL\\\"),\\n            sqlite_where=text(\\\"domain_id IS NOT NULL\\\"),\\n        ),\\n        Index(\\n            \\\"uq_authz_role_assignment_unscoped\\\",\\n            \\\"user_id\\\",\\n            \\\"role_id\\\",\\n            \\\"domain_type\\\",\\n            unique=True,\\n            postgresql_where=text(\\\"domain_id IS NULL\\\"),\\n            sqlite_where=text(\\\"domain_id IS NULL\\\"),\\n        ),\\n        # Hot-path lookup: \\\"all assignments for user X scoped to a domain\\\"\\n        # Composite index for enforce() lookups.\\n        # single-column scans.\\n        Index(\\n            \\\"ix_authz_role_assignment_user_domain\\\",\\n            \\\"user_id\\\",\\n            \\\"domain_type\\\",\\n            \\\"domain_id\\\",\\n        ),\\n    )\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    user_id: UUIDstr = Field(\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False, index=True),\\n    )\\n    role_id: UUIDstr = Field(\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"authz_role.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False, index=True),\\n    )\\n    domain_type: str = Field(default=\\\"global\\\", description=\\\"global, workspace, project\\\")\\n    # Explicit ``sa_column`` so SQLModel emits ``sa.Uuid()`` matching the\\n    # migration's column type. Without this, SQLModel can fall back to\\n    # ``AutoString``/``CHAR(32)`` on SQLite, which drifts from the migration\\n    # and confuses downstream type introspection.\\n    domain_id: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(sa.Uuid(), nullable=True, index=True),\\n    )\\n    assigned_at: datetime = Field(default_factory=_tz_aware_now, sa_column=_tz_column())\\n    assigned_by: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"SET NULL\\\"), nullable=True),\\n    )\\n    # SQLite ignores ``ON DELETE CASCADE`` unless ``PRAGMA foreign_keys=ON`` is\\n    # issued on every connection, which Langflow never does, so revoking an\\n    # assignment on the default backend left its provenance rows orphaned.\\n    # Cascading through the ORM issues the child deletes on every backend.\\n    #\\n    # ``all, delete`` deliberately excludes ``delete-orphan``: grant rows are\\n    # created by setting ``assignment_id`` directly rather than by appending to\\n    # this collection, and ``delete-orphan`` would reject those as unparented.\\n    grants: list[\\\"AuthzRoleAssignmentGrant\\\"] = Relationship(\\n        sa_relationship_kwargs={\\\"cascade\\\": \\\"all, delete\\\", \\\"passive_deletes\\\": False},\\n    )\\n\\n\\nclass AuthzRoleAssignmentGrant(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Independent provenance source that keeps an effective assignment alive.\\n\\n    An assignment may have one manual source and any number of IdP group\\n    sources. This avoids making provenance a lossy property of the effective\\n    assignment when a manual grant overlaps an externally-derived grant.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"authz_role_assignment_grant\\\"\\n    __table_args__ = (\\n        CheckConstraint(\\n            \\\"(source_kind = 'manual' AND provider_id IS NULL AND external_group IS NULL) \\\"\\n            \\\"OR (source_kind = 'idp' AND provider_id IS NOT NULL AND external_group IS NOT NULL)\\\",\\n            name=conv(\\\"ck_authz_role_assignment_grant_source\\\"),\\n        ),\\n        Index(\\n            \\\"uq_authz_role_assignment_grant_manual\\\",\\n            \\\"assignment_id\\\",\\n            unique=True,\\n            postgresql_where=text(\\\"source_kind = 'manual'\\\"),\\n            sqlite_where=text(\\\"source_kind = 'manual'\\\"),\\n        ),\\n        Index(\\n            \\\"uq_authz_role_assignment_grant_idp\\\",\\n            \\\"assignment_id\\\",\\n            \\\"provider_id\\\",\\n            \\\"external_group\\\",\\n            unique=True,\\n            postgresql_where=text(\\\"source_kind = 'idp'\\\"),\\n            sqlite_where=text(\\\"source_kind = 'idp'\\\"),\\n        ),\\n        Index(\\n            \\\"ix_authz_role_assignment_grant_provider_group\\\",\\n            \\\"provider_id\\\",\\n            \\\"external_group\\\",\\n        ),\\n    )\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    assignment_id: UUIDstr = Field(\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"authz_role_assignment.id\\\", ondelete=\\\"CASCADE\\\"),\\n            nullable=False,\\n            index=True,\\n        ),\\n    )\\n    source_kind: str = Field(description=\\\"manual or idp\\\")\\n    provider_id: str | None = Field(default=None, max_length=256)\\n    external_group: str | None = Field(default=None, max_length=256)\\n    administrative_actor: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"SET NULL\\\"), nullable=True),\\n    )\\n    created_at: datetime = Field(default_factory=_tz_aware_now, sa_column=_tz_column())\\n    updated_at: datetime = Field(default_factory=_tz_aware_now, sa_column=_tz_column())\\n\\n\\nclass AuthzTeam(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Logical grouping of users for share scopes and bulk role assignments.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"authz_team\\\"\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    team_name: str = Field(index=True)\\n    adom_name: str = Field(unique=True, index=True)\\n    description: str | None = Field(default=None)\\n    is_active: bool = Field(default=True)\\n    created_at: datetime = Field(default_factory=_tz_aware_now, sa_column=_tz_column())\\n    updated_at: datetime = Field(default_factory=_tz_aware_now, sa_column=_tz_column())\\n\\n\\nclass AuthzTeamMember(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Membership row linking a user to an AuthzTeam.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"authz_team_member\\\"\\n    __table_args__ = (UniqueConstraint(\\\"team_id\\\", \\\"user_id\\\", name=\\\"uq_authz_team_member\\\"),)\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    team_id: UUIDstr = Field(\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"authz_team.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False, index=True),\\n    )\\n    user_id: UUIDstr = Field(\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False, index=True),\\n    )\\n    source: str = Field(default=\\\"manual\\\", description=\\\"sso or manual\\\")\\n    created_at: datetime = Field(default_factory=_tz_aware_now, sa_column=_tz_column())\\n\\n\\nclass AuthzShare(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Resource share record granting access at a specific scope/permission level.\\n\\n    ``target_id`` is naturally NULL for PRIVATE/PUBLIC scopes and a UUID for\\n    TEAM/USER scopes \u2014 partial unique indexes split the two cases so the NULL\\n    rows can still be deduplicated.\\n\\n    ``created_by`` uses ``SET NULL`` (not CASCADE) so deleting a user does not\\n    silently revoke every share that user ever created. The grant survives\\n    with no recorded creator; admins can clean up if needed.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"authz_share\\\"\\n    __table_args__ = (\\n        # Hot path: \\\"list all shares for resource X\\\" \u2192 composite index avoids\\n        # a bitmap-AND of two single-column indexes.\\n        Index(\\\"ix_authz_share_resource\\\", \\\"resource_type\\\", \\\"resource_id\\\"),\\n        # Bound scope and permission_level to known enum values at the DB\\n        # Without this, a plugin (or manual INSERT) could\\n        # write a typo like ``scope='PRIVATE'`` that silently bypasses the\\n        # partial unique indexes (which match on the lowercase form).\\n        CheckConstraint(\\n            \\\"scope IN ('private', 'team', 'user', 'public')\\\",\\n            name=conv(\\\"ck_authz_share_scope_enum\\\"),\\n        ),\\n        CheckConstraint(\\n            \\\"permission_level IN ('read', 'write', 'execute', 'admin')\\\",\\n            name=conv(\\\"ck_authz_share_permission_enum\\\"),\\n        ),\\n        # Targeted (TEAM/USER) shares require a target_id; untargeted\\n        # (PRIVATE/PUBLIC) shares forbid one. Matches the partial-unique-index\\n        # split so callers can't accidentally construct rows that one index\\n        # covers but the other shouldn't.\\n        CheckConstraint(\\n            \\\"(scope IN ('team', 'user') AND target_id IS NOT NULL) \\\"\\n            \\\"OR (scope IN ('private', 'public') AND target_id IS NULL)\\\",\\n            name=conv(\\\"ck_authz_share_scope_target_consistency\\\"),\\n        ),\\n        Index(\\n            \\\"uq_authz_share_targeted\\\",\\n            \\\"resource_type\\\",\\n            \\\"resource_id\\\",\\n            \\\"scope\\\",\\n            \\\"target_id\\\",\\n            unique=True,\\n            postgresql_where=text(\\\"target_id IS NOT NULL\\\"),\\n            sqlite_where=text(\\\"target_id IS NOT NULL\\\"),\\n        ),\\n        Index(\\n            \\\"uq_authz_share_untargeted\\\",\\n            \\\"resource_type\\\",\\n            \\\"resource_id\\\",\\n            \\\"scope\\\",\\n            unique=True,\\n            postgresql_where=text(\\\"target_id IS NULL\\\"),\\n            sqlite_where=text(\\\"target_id IS NULL\\\"),\\n        ),\\n    )\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    resource_type: str = Field(index=True)\\n    resource_id: UUIDstr = Field(index=True)\\n    scope: str = Field(index=True)\\n    target_id: UUIDstr | None = Field(default=None, index=True)\\n    permission_level: str = Field(default=SharePermissionLevel.READ.value)\\n    created_by: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"SET NULL\\\"), nullable=True),\\n    )\\n    created_at: datetime = Field(default_factory=_tz_aware_now, sa_column=_tz_column())\\n\\n\\nclass AuthzEditLock(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Optimistic edit lock that prevents concurrent edits to the same flow.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"authz_edit_lock\\\"\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    flow_id: UUIDstr = Field(\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"flow.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False, unique=True, index=True),\\n    )\\n    holder_user_id: UUIDstr = Field(\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False),\\n    )\\n    acquired_at: datetime = Field(default_factory=_tz_aware_now, sa_column=_tz_column())\\n    # ``index=True`` matches the migration's ``ix_authz_edit_lock_expires_at``\\n    # so the expired-lock sweeper can do an index seek instead of a table scan.\\n    expires_at: datetime = Field(sa_column=_tz_column(index=True))\\n\\n\\n# TODO: AuthzAuditLog is append-only and unbounded. At large scale this\\n# table will outgrow practical query windows. Decide between (a) Postgres native\\n# partitioning by ``timestamp`` (monthly/quarterly), (b) an out-of-band\\n# archival/TTL job, or (c) SIEM export per design note \u00a75.3 Phase 5. The\\n# composite ix_authz_audit_log_user_timestamp index keeps \\\"all events for user\\n# X in last N days\\\" fast under either strategy.\\nclass AuthzAuditLog(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"Append-only audit row produced by every authorization decision.\\\"\\\"\\\"\\n\\n    __tablename__ = \\\"authz_audit_log\\\"\\n    __table_args__ = (\\n        Index(\\\"ix_authz_audit_log_user_timestamp\\\", \\\"user_id\\\", \\\"timestamp\\\"),\\n        Index(\\\"ix_authz_audit_log_actor_timestamp\\\", \\\"actor_id\\\", \\\"timestamp\\\"),\\n        Index(\\\"ix_authz_audit_log_actor_type_timestamp\\\", \\\"actor_type\\\", \\\"timestamp\\\"),\\n        Index(\\\"ix_authz_audit_log_resource\\\", \\\"resource_type\\\", \\\"resource_id\\\"),\\n        # Keep this vocabulary aligned with ``services.authorization.audit``.\\n        # ``skip`` records an operator-visible reconciliation attempt that did\\n        # not apply an authoritative directory snapshot.\\n        CheckConstraint(\\n            \\\"result IN ('allow', 'deny', 'owner_override', 'skip')\\\",\\n            name=conv(\\\"ck_authz_audit_log_result_enum\\\"),\\n        ),\\n    )\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    user_id: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(sa.Uuid(), ForeignKey(\\\"user.id\\\", ondelete=\\\"SET NULL\\\"), nullable=True, index=True),\\n    )\\n    actor_type: str | None = Field(default=None)\\n    # Deliberately no FK: API-key actor attribution must survive key deletion.\\n    actor_id: UUIDstr | None = Field(default=None, sa_column=Column(sa.Uuid(), nullable=True))\\n    action: str = Field(index=True)\\n    resource_type: str | None = Field(default=None)\\n    resource_id: UUIDstr | None = Field(default=None)\\n    result: str = Field()\\n    details: dict | None = Field(default=None, sa_column=Column(sa.JSON))\\n    timestamp: datetime = Field(default_factory=_tz_aware_now, sa_column=_tz_column(index=True))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/auth/sso.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"34c3a9d5a2c3d5b2a91069fd46b8365966102f7b1d922aecaa4a43efa908428a\",\"content\":\"\\\"\\\"\\\"SSO plugin tables.\\n\\nThese tables are used by the SSO plugin for identity and provider configuration.\\nMigrations are managed by Langflow (OSS); the plugin must not create or\\nmigrate these tables.\\n\\nPlugins must use these tables via the models exported from\\n``langflow.services.database.models`` (e.g. ``SSOUserProfile``, ``SSOConfig``).\\n\\\"\\\"\\\"\\n\\nimport re\\nfrom datetime import datetime, timezone\\nfrom typing import Annotated, Any, Literal, TypeAlias\\nfrom urllib.parse import urlsplit\\nfrom uuid import uuid4\\n\\nimport sqlalchemy as sa\\nfrom pydantic import AnyHttpUrl, BaseModel, ConfigDict, SecretStr, TypeAdapter, field_validator, model_validator\\nfrom pydantic import Field as PydanticField\\nfrom sqlalchemy import CheckConstraint, Column, DateTime, ForeignKey, Index\\nfrom sqlalchemy.orm import validates\\nfrom sqlalchemy.sql.naming import conv\\nfrom sqlmodel import Field, SQLModel\\nfrom typing_extensions import Self\\n\\nfrom langflow.schema.serialize import UUIDstr\\nfrom langflow.services.database.models.auth.sso_secret import is_sso_client_secret_envelope\\n\\n_SSO_SLUG_PATTERN = re.compile(r\\\"^[a-z0-9]+(?:-[a-z0-9]+)*$\\\")\\n_INVALID_PERCENT_ESCAPE_PATTERN = re.compile(r\\\"%(?![0-9A-Fa-f]{2})\\\")\\n_HTTP_URL_ADAPTER = TypeAdapter(AnyHttpUrl)\\n_SSO_SECRET_ENVELOPE_HEADER = \\\"lf-sso:v1:hkdf-sha256-v1:aes-256-gcm:\\\"  # noqa: S105  # pragma: allowlist secret\\n_SSO_SECRET_NONCE_LENGTH = 16\\n_SSO_SECRET_MIN_CIPHERTEXT_LENGTH = 22\\n_VALIDATED_UPDATE_FLAG = \\\"_sso_validated_update_in_progress\\\"\\n_OIDC_REMOTE_URL_FIELDS = (\\n    \\\"discovery_url\\\",\\n    \\\"token_endpoint\\\",\\n    \\\"authorization_endpoint\\\",\\n    \\\"jwks_uri\\\",\\n    \\\"issuer\\\",\\n)\\n\\n\\ndef _generate_sso_slug() -> str:\\n    \\\"\\\"\\\"Generate an opaque, URL-safe connection identifier.\\\"\\\"\\\"\\n    return f\\\"sso-{uuid4().hex}\\\"\\n\\n\\ndef _utc_now() -> datetime:\\n    return datetime.now(timezone.utc)\\n\\n\\nclass OIDCProviderSettings(BaseModel):\\n    \\\"\\\"\\\"OIDC-specific settings stored in ``sso_config.provider_settings``.\\\"\\\"\\\"\\n\\n    model_config = ConfigDict(extra=\\\"forbid\\\", frozen=True)\\n\\n    protocol: Literal[\\\"oidc\\\"] = \\\"oidc\\\"\\n    discovery_url: str | None = None\\n    redirect_uri: str | None = None\\n    scopes: str | None = \\\"openid email profile\\\"\\n    token_endpoint: str | None = None\\n    authorization_endpoint: str | None = None\\n    jwks_uri: str | None = None\\n    issuer: str | None = None\\n    client_id: str | None = None\\n\\n    @field_validator(\\\"client_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_client_id(cls, value: object) -> object:\\n        if not isinstance(value, str):\\n            return value\\n        value = value.strip()\\n        if not value:\\n            msg = \\\"OIDC client_id must not be blank\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n    @field_validator(*_OIDC_REMOTE_URL_FIELDS, mode=\\\"before\\\")\\n    @classmethod\\n    def validate_remote_url(cls, value: object, info: Any) -> object:\\n        \\\"\\\"\\\"Require absolute HTTP(S) URLs for values consumed by the OIDC HTTP client.\\\"\\\"\\\"\\n        if value is None or not isinstance(value, str):\\n            return value\\n        value = value.strip()\\n        if not value:\\n            msg = f\\\"OIDC {info.field_name} must not be blank\\\"\\n            raise ValueError(msg)\\n        is_http_url = False\\n        try:\\n            parsed = urlsplit(value)\\n            # urlsplit alone accepts malformed hosts and ports. Pydantic's URL\\n            # parser closes those gaps, while the pre-checks preserve the\\n            # original URL structure and reject invalid percent escapes rather\\n            # than normalizing them into a different URL.\\n            is_http_url = (\\n                parsed.scheme.lower() in {\\\"http\\\", \\\"https\\\"}\\n                and bool(parsed.netloc)\\n                and parsed.hostname is not None\\n                and not any(character.isspace() for character in value)\\n                and _INVALID_PERCENT_ESCAPE_PATTERN.search(value) is None\\n                and \\\"%\\\" not in parsed.hostname\\n            )\\n            if is_http_url:\\n                _ = parsed.port\\n                _HTTP_URL_ADAPTER.validate_python(value)\\n        except ValueError:\\n            is_http_url = False\\n        if not is_http_url:\\n            msg = f\\\"OIDC {info.field_name} must be an absolute HTTP(S) URL\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n\\nclass LegacyProviderSettings(BaseModel):\\n    \\\"\\\"\\\"Read-compatible settings for disabled legacy SAML and LDAP rows.\\n\\n    Langflow does not currently execute these protocols through this typed\\n    contract. Keeping their migrated values loadable avoids making an upgrade\\n    destructive; enabled legacy rows still fail closed below.\\n    \\\"\\\"\\\"\\n\\n    model_config = ConfigDict(extra=\\\"forbid\\\", frozen=True)\\n\\n    protocol: Literal[\\\"saml\\\", \\\"ldap\\\"]\\n    discovery_url: str | None = None\\n    redirect_uri: str | None = None\\n    scopes: str | None = None\\n    token_endpoint: str | None = None\\n    authorization_endpoint: str | None = None\\n    jwks_uri: str | None = None\\n    issuer: str | None = None\\n    client_id: str | None = None\\n\\n\\n# Add future protocol variants to this discriminated union. The database schema\\n# remains unchanged because every variant is stored in the same JSON column.\\nSSOProviderSettings: TypeAlias = Annotated[\\n    OIDCProviderSettings | LegacyProviderSettings,\\n    PydanticField(discriminator=\\\"protocol\\\"),\\n]\\n_PROVIDER_SETTINGS_ADAPTER = TypeAdapter(SSOProviderSettings)\\n\\n\\ndef _validate_provider_settings(protocol: str, value: object) -> SSOProviderSettings:\\n    settings = _PROVIDER_SETTINGS_ADAPTER.validate_python(value)\\n    if settings.protocol != protocol:\\n        msg = f\\\"provider_settings protocol {settings.protocol!r} does not match sso_config.protocol {protocol!r}\\\"\\n        raise ValueError(msg)\\n    return settings\\n\\n\\ndef _validate_enabled_config(\\n    provider_settings: SSOProviderSettings,\\n    *,\\n    enabled: bool,\\n    has_client_secret: bool,\\n) -> None:\\n    if not enabled:\\n        return\\n\\n    if provider_settings.protocol != \\\"oidc\\\":\\n        msg = \\\"Only OIDC configurations can be enabled\\\"\\n        raise ValueError(msg)\\n\\n    if not provider_settings.client_id:\\n        msg = \\\"Enabled OIDC configurations require a client_id\\\"\\n        raise ValueError(msg)\\n    if not has_client_secret:\\n        msg = \\\"Enabled OIDC configurations require a client secret\\\"\\n        raise ValueError(msg)\\n\\n    has_discovery = bool(provider_settings.discovery_url)\\n    has_explicit_endpoints = all(\\n        (\\n            provider_settings.authorization_endpoint,\\n            provider_settings.token_endpoint,\\n            provider_settings.jwks_uri,\\n        )\\n    )\\n    if not has_discovery and not has_explicit_endpoints:\\n        msg = (\\n            \\\"Enabled OIDC configurations require discovery_url or authorization_endpoint, token_endpoint, and jwks_uri\\\"\\n        )\\n        raise ValueError(msg)\\n\\n\\nclass _ProviderSettingsJSON(sa.TypeDecorator):\\n    \\\"\\\"\\\"Persist validated provider settings as JSON and restore their Pydantic type.\\\"\\\"\\\"\\n\\n    impl = sa.JSON\\n    cache_ok = True\\n\\n    def process_bind_param(\\n        self,\\n        value: SSOProviderSettings | dict[str, Any] | None,\\n        _dialect: sa.engine.Dialect,\\n    ) -> dict[str, Any] | None:\\n        if value is None:\\n            return None\\n        settings = _PROVIDER_SETTINGS_ADAPTER.validate_python(value)\\n        return _PROVIDER_SETTINGS_ADAPTER.dump_python(settings, mode=\\\"json\\\")\\n\\n    def process_result_value(\\n        self,\\n        value: dict[str, Any] | None,\\n        _dialect: sa.engine.Dialect,\\n    ) -> SSOProviderSettings | None:\\n        if value is None:\\n            return None\\n        return _PROVIDER_SETTINGS_ADAPTER.validate_python(value)\\n\\n\\nclass _SSOClientSecretEnvelope(sa.TypeDecorator):\\n    \\\"\\\"\\\"Reject non-envelope values on every SQL bind path, including Core updates.\\\"\\\"\\\"\\n\\n    impl = sa.String\\n    cache_ok = True\\n\\n    def process_bind_param(self, value: str | None, _dialect: sa.engine.Dialect) -> str | None:\\n        if value is not None and not is_sso_client_secret_envelope(value):\\n            msg = \\\"client_secret_encrypted must be a versioned SSO secret envelope\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n\\nclass SSOUserProfile(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"SSO profile per user.\\n\\n    During the expand phase, ``sso_provider`` can contain a legacy provider name,\\n    an OSS ``EXTERNAL_AUTH_PROVIDER`` key, or the immutable ``SSOConfig.slug``.\\n    SSO plugins must dual-read names and slugs until a later contract migration;\\n    no database foreign key is intentionally enforced.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"sso_user_profile\\\"\\n    # Use Index(unique=True) to match migrations (create_index); avoids model/DB mismatch.\\n    __table_args__ = (\\n        Index(\\\"uq_sso_user_profile_provider_user\\\", \\\"sso_provider\\\", \\\"sso_user_id\\\", unique=True),\\n        Index(\\\"uq_sso_user_profile_user_provider\\\", \\\"user_id\\\", \\\"sso_provider\\\", unique=True),\\n    )\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    user_id: UUIDstr = Field(\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"user.id\\\", ondelete=\\\"CASCADE\\\"),\\n            nullable=False,\\n            index=True,\\n        )\\n    )\\n    sso_provider: str = Field(description=\\\"SSO connection slug or expand-phase legacy provider key\\\")\\n    sso_user_id: str = Field()\\n    email: str | None = Field(default=None, index=True)\\n    first_name: str | None = Field(default=None)\\n    last_name: str | None = Field(default=None)\\n    picture: str | None = Field(default=None)\\n    sso_last_login_at: datetime | None = Field(default=None)\\n    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n    updated_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n\\n\\nclass SSOConfig(SQLModel, table=True):  # type: ignore[call-arg]\\n    \\\"\\\"\\\"SSO provider configuration (persisted in DB). Used by the SSO plugin.\\n\\n    ``client_secret_encrypted`` is an at-rest ciphertext envelope and must never\\n    be returned by a read path. Consumers encrypt/decrypt it with the helpers in\\n    ``sso_secret``.\\n    \\\"\\\"\\\"\\n\\n    __tablename__ = \\\"sso_config\\\"\\n    __table_args__ = (Index(\\\"uq_sso_config_slug\\\", \\\"slug\\\", unique=True),)\\n\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True)\\n    slug: str = Field(default_factory=_generate_sso_slug, description=\\\"Immutable URL-safe connection identifier\\\")\\n    display_name: str = Field(description=\\\"Mutable admin-facing connection label\\\")\\n    protocol: str = Field(default=\\\"oidc\\\", description=\\\"Protocol discriminator for provider_settings\\\")\\n    enabled: bool = Field(default=False)\\n    sort_order: int = Field(default=0, description=\\\"Login-button display order\\\")\\n    client_secret_encrypted: str | None = Field(\\n        default=None,\\n        exclude=True,\\n        repr=False,\\n        sa_column=Column(_SSOClientSecretEnvelope(), nullable=True),\\n        description=\\\"Versioned ciphertext envelope; never serialize in a read response\\\",\\n    )\\n    provider_settings: SSOProviderSettings = Field(\\n        default_factory=OIDCProviderSettings,\\n        sa_column=Column(_ProviderSettingsJSON(), nullable=False),\\n        description=(\\n            \\\"Validated provider settings persisted as JSON. Assign a new object \\\"\\n            \\\"(or call flag_modified) to persist changes; in-place nested field \\\"\\n            \\\"mutations are not tracked by SQLAlchemy.\\\"\\n        ),\\n    )\\n    email_claim: str = Field(default=\\\"email\\\")\\n    username_claim: str = Field(default=\\\"preferred_username\\\")\\n    user_id_claim: str = Field(default=\\\"sub\\\")\\n    created_at: datetime = Field(\\n        default_factory=_utc_now,\\n        sa_column=Column(DateTime(timezone=True), nullable=False),\\n    )\\n    updated_at: datetime = Field(\\n        default_factory=_utc_now,\\n        sa_column=Column(DateTime(timezone=True), nullable=False, onupdate=_utc_now),\\n    )\\n    created_by: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"user.id\\\", ondelete=\\\"SET NULL\\\"),\\n            nullable=True,\\n        ),\\n    )\\n    updated_by: UUIDstr | None = Field(\\n        default=None,\\n        sa_column=Column(\\n            sa.Uuid(),\\n            ForeignKey(\\\"user.id\\\", ondelete=\\\"SET NULL\\\"),\\n            nullable=True,\\n        ),\\n    )\\n\\n    def __init__(self, **data: Any) -> None:\\n        slug = data.get(\\\"slug\\\")\\n        if slug is not None and not _SSO_SLUG_PATTERN.fullmatch(slug):\\n            msg = \\\"SSOConfig.slug must contain only lowercase letters, numbers, and single hyphens\\\"\\n            raise ValueError(msg)\\n        protocol = data.get(\\\"protocol\\\", \\\"oidc\\\")\\n        data[\\\"protocol\\\"] = protocol\\n        data[\\\"provider_settings\\\"] = _validate_provider_settings(\\n            protocol,\\n            data.get(\\\"provider_settings\\\", OIDCProviderSettings()),\\n        )\\n        super().__init__(**data)\\n        _validate_enabled_config(\\n            self.provider_settings,\\n            enabled=self.enabled,\\n            has_client_secret=self.client_secret_";
